    animation: fade-in 0.25s ease-out;
}

@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.pantry-list {
    flex: 1;
    overflow-y: auto;
    padding-right: 10px;
    margin-top: 10px;
}

.pantry-list::-webkit-scrollbar {
    width: 6px;
}

.pantry-list::-webkit-scrollbar-track {
    background: var(--border-secondary-hover-translucent-15);
    border-radius: 3px;
}

.pantry-list::-webkit-scrollbar-thumb {
    background: var(--border-secondary-hover-translucent-15);
    border-radius: 3px;
}

.pantry-list::-webkit-scrollbar-thumb:hover {
    background: var(--border-secondary-hover-translucent-15);
}








.eat-raw-btn {
    font-family: var(--font-ui);
    font-size: 0.798em;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    color: var(--text-primary-hover);
    border: 1.5px solid var(--text-primary-hover);
    border-radius: 4px;
    padding: 3px 8px;
    margin-left: 10px;
