.affinity-name { font-weight: bold; color: var(--text-detail-label); }
.affinity-val.weakness { color: var(--text-cost-bad); font-weight: bold; }
.affinity-val.resistance { color: var(--text-cost-ok); font-weight: bold; }

/* Ecology reads in the shared fact grid, so nothing here but its spacing. */
.ecology-list { gap: var(--sp-1) var(--sp-5); }
.ecology-row { padding: 2px 0; background: transparent; border: none; }

/* The four trophic roles are a named ladder. */
.bestiary-role { font-weight: bold; }
.bestiary-role--predator { color: var(--text-cost-bad); }
.bestiary-role--hunter { color: var(--text-primary-hover); }
.bestiary-role--prey { color: var(--text-cost-ok); }
