    align-items: center;
    gap: var(--sp-3);
    min-width: 0;
}

/* The IconSet cell is handed in as two custom properties. */
.harvest-icon {
    width: 24px;
    height: 24px;
    flex-shrink: 0;
    background-image: url('../img/system/IconSet.png');
    background-repeat: no-repeat;
    background-position: var(--icon-x, 0) var(--icon-y, 0);
    background-size: 384px auto;
}

.harvest-name {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-body);
