    flex-wrap: wrap;
    justify-content: center;
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

/* Both portraits (the drawn bust and the live 3D model) fill the box exactly,
   letterboxed by object-fit, so neither can print over the gauges below. They
   are absolutely placed so their height never depends on a percentage
   resolving against a flex item. */
#status-bust,
#status-bust-3d {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: block;
    background: transparent;
    border-radius: 0;
    object-fit: contain;
}

/* The gauges are the point of the left page, so they claim their space first and
   the portrait above absorbs the whole shortfall. Framed like the backpack's
   carry-weight strip: transparent plate, hairline gold frame. */
.status-gauges-box {
    flex: 0 0 auto;
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 6px;
    padding: 12px 14px;
    margin-top: 4px;
}

.status-gauge-row {
    margin-bottom: 10px;
    min-width: 0;
}

.status-gauge-row:last-child {
    margin-bottom: 0;
}

/* Gauges are laid out two per line so the whole block fits the page without
   scrolling; the grid gap replaces the per-row bottom margin. */
.status-gauge-grid,
.status-needs-rows {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 20px;
    row-gap: 12px;
    align-content: start;
}

.status-gauge-grid .status-gauge-row,
.status-needs-rows .status-gauge-row {
    margin-bottom: 0;
}

/* HP and MP are the two that matter at a glance, so they are stacked full
   width; AP and experience share the line under them. */
.status-gauge-grid > .status-gauge-row:nth-child(1),
.status-gauge-grid > .status-gauge-row:nth-child(2) {
    grid-column: 1 / -1;
}

.status-gauge-meta {
    display: flex;
    justify-content: space-between;
    font-family: var(--font-ui);
    font-size: 0.892em;
    font-weight: bold;
    color: var(--text-text-alt-1-active);
    margin-bottom: 2px;
}

.status-gauge-bar-outer {
    width: 100%;
    height: 11px;
    background: var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid var(--border-primary-hover-translucent-15);
}

.status-gauge-bar-inner {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s ease;
}

.status-gauge-bar-inner.hp {
    background: var(--gradient-3);
}

.status-gauge-bar-inner.mp {
    background: var(--gradient-2);
}

.status-gauge-bar-inner.tp {
    background: var(--gradient-14);
}

.status-gauge-bar-inner.exp {
    background: var(--gradient-11);
}

/* Sub-line under a gauge (how much experience the next level still wants).
   On the caption token, which is the floor: it was under it, and faded on top
   of that. */
.status-gauge-note {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    color: var(--text-text-alt-1-active);
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.status-gauge-note:empty {
    display: none;
}

.status-needs-rows {
    margin-top: 12px;
    padding-top: 12px;
    border-top: none;
}

.status-gauge-bar-inner.hunger {
    background: var(--gradient-12);
}

.status-gauge-bar-inner.sleep {
    background: var(--gradient-16);
}

.status-gauge-bar-inner.hygiene {
    background: var(--gradient-13);
}

.status-gauge-bar-inner.social {
    background: var(--gradient-27);
}

.status-gauge-bar-inner.leisure {
    background: var(--gradient-25);
}

.stats-medallions-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 14px;
}

.stat-medallion {
    background: transparent;
    border: none;
    border-radius: 50%;
    width: 100%;
    max-width: 120px;
    height: 80px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    position: relative;
}

/* The value and its modifier badge sit on one line, the badge to the right of
   the number, so nothing hangs off the bottom of the medallion. */
.stat-medallion-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
}

.stat-medallion-lbl {
    font-family: var(--font-ui);
    font-size: 0.928em;
    color: var(--text-primary-hover);
    font-weight: bold;
    margin-top: 1px;
}

.stat-medallion-val {
    font-family: var(--font-ui);
    font-size: 1.19em;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.stat-medallion-mod {
    position: static;
    background: var(--text-primary-hover);
    color: var(--bg-secondary-hover);
    font-family: var(--font-ui);
    font-size: 0.82em;
    font-weight: bold;
    padding: 1px 5px;
    border-radius: 8px;
    box-shadow: 0 2px 4px var(--shadow-primary-hover-translucent-5);
}

/* The alignment box is what is left on the attributes tab under the medallions,
   now that the traits have a page of their own. */
.status-alignment-row {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 12px;
}

.status-stat-breakdown-card {
    background: transparent;
    border: none;
    border-radius: 6px;
    padding: 8px 10px;
    margin-bottom: 10px;
    font-family: var(--font-ui);
}

.status-stat-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.84em;
    color: var(--text-card-medium);
}

.status-stat-table th {
    color: var(--text-primary-hover);
    font-weight: bold;
    text-align: center;
    padding: 3px 4px;
    border-bottom: none;
    font-size: 0.88em;
}

.status-stat-table th:first-child,
.status-stat-table td:first-child {
    text-align: left;
    font-weight: bold;
    color: var(--text-primary-hover);
}

.status-stat-table td {
    padding: 3px 4px;
    text-align: center;
    border-bottom: 1px solid var(--border-primary-hover-translucent-5);
}

.status-stat-table tr:last-child td {
    border-bottom: none;
}

.status-stat-bonus-positive {
    color: var(--text-cost-ok);
    font-weight: 600;
}

.status-stat-bonus-zero {
    color: var(--text-card-medium);
    opacity: 0.6;
}

.status-stat-bonus-negative {
    color: var(--text-blood-red);
    font-weight: 600;
}

.status-stat-mod-badge {
    display: inline-block;
    background: var(--text-primary-hover);
    color: var(--bg-secondary-hover);
    font-weight: bold;
    font-size: 0.88em;
    padding: 0 5px;
    border-radius: 6px;
}

/* Bio Tab Styles */
.status-bio-scroll {
    flex-grow: 1;
    min-height: 0;
    overflow-y: auto;
    padding-right: 6px;
    font-family: var(--font-ui);
}

.status-bio-scroll::-webkit-scrollbar {
    width: 5px;
}

.status-bio-scroll::-webkit-scrollbar-track {
    background: var(--border-primary-hover-translucent-15);
}

.status-bio-scroll::-webkit-scrollbar-thumb {
    background: var(--border-primary-hover-translucent-15);
    border-radius: 3px;
}

.status-bio-section {
    margin-bottom: 12px;
}

.status-bio-section:last-child {
    margin-bottom: 0;
}

.status-bio-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 6px 14px;
    font-size: 0.88em;
    padding: 4px 2px;
}

.status-bio-grid.single-col {
    grid-template-columns: 1fr;
}

/* Every bio row is read the way an inventory slot is read: a transparent plate
   inside a hairline gold frame, a muted label on the left and the answer in the
   bright value ink on the right (.item-slot / .inspect-spec-* in the backpack). */
.status-bio-item {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
    padding: 4px 9px;
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    min-width: 0;
}

.status-bio-item-lbl {
    color: var(--text-text-alt-4);
    font-weight: 600;
    font-size: 0.92em;
    white-space: nowrap;
}

.status-bio-item-val {
    color: var(--text-success-active);
    font-weight: bold;
    text-align: right;
    word-break: break-word;
    min-width: 0;
}

.status-bio-item-val.badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 1px 6px;
    border-radius: 4px;
    background: var(--border-primary-hover-translucent-15);
    font-weight: 600;
}

.status-bio-narrative {
    font-size: 0.892em;
    line-height: 1.45;
    color: var(--text-card-medium);
    padding: 4px 2px;
    white-space: pre-line;
}

.status-bio-events-list {
    margin-top: 6px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.status-bio-event-row {
    display: flex;
    align-items: flex-start;
    gap: 6px;
    font-size: 0.84em;
    color: var(--text-card-medium);
    padding: 3px 4px;
    border-radius: 4px;
    background: var(--border-primary-hover-translucent-5);
}

.status-bio-event-date {
    font-weight: bold;
    color: var(--text-primary-hover);
    white-space: nowrap;
    flex: 0 0 auto;
}

.status-element-box {
    background: transparent;
    border: none;
    padding: 10px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

.element-title {
    font-family: var(--font-ui);
    font-size: 0.856em;
    font-weight: bold;
    color: var(--text-text-alt-4);
    margin-bottom: 4px;
}

.element-badge {
    background: transparent;
    color: var(--text-primary-hover);
    font-family: var(--font-ui);
    font-size: 1.048em;
    font-weight: bold;
    padding: 3px 10px;
    border: none;
}

/* The traits page: every trait the character carries, each written out in full,
   one dossier under the next down a scrolling card. */
.status-traits-full {
    flex-grow: 1;
    min-height: 0;
    overflow-y: auto;
    padding-right: 4px;
}

.status-trait-entry {
    font-family: var(--font-ui);
    padding: 8px 0;
}

.status-trait-entry + .status-trait-entry {
    border-top: none;
}

.status-traits-empty {
    font-family: var(--font-ui);
    font-style: normal;
    color: var(--text-card-medium);
    font-size: 0.892em;
    text-align: center;
    padding: 12px;
}

.card-label {
    font-family: var(--font-ui);
    font-size: 1em;
    color: var(--text-primary-hover);
    font-weight: bold;
    border-bottom: none;
    padding-bottom: 3px;
    margin-bottom: 5px;
}

/* The stack the right page's tab panels live in. */
#status-lower-cards {
    display: flex;
    flex-direction: column;
    flex-grow: 1;
    min-height: 0;
}

/* The medallions take only their own height: the alignment box under them is
   not pushed off the page by a grid that wanted to grow. */
#status-attr-cards {
    flex: 0 0 auto;
}

/* Right-page section tabs. The chips are the shared bookmark-tab design
   (.backpack-tabs / .backpack-tab); only the spacing is this page's own, since
   what sits under them is a flex column that must not be squeezed. */
#status-tabs {
    flex: 0 0 auto;
    gap: 4px;
    margin-bottom: 10px;
    padding-bottom: 8px;
}

#status-tabs .backpack-tab {
    font-size: 0.856em;
    padding: 3px 12px;
    border-radius: 2px;
    font-weight: 600;
    white-space: nowrap;
}

/* One section is in the layout at a time: a hidden panel leaves the flex column
   entirely, so the visible one gets the whole height the page has left. */
.status-tab-panel {
    display: none;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
}

.status-tab-panel.active {
    display: flex;
}

/* A card that states a fact rather than holding a list: it takes only its own
   height and leaves the rest of the panel to the scrolling card below it. The
   selector carries .bodyparts-card so it beats that card's own grow/min-height
   whichever of the two rules comes later in the sheet. */
.bodyparts-card.status-card-fixed {
    flex: 0 0 auto;
    min-height: 0;
    margin-bottom: 8px;
}

/* Passive abilities list: the class's signature passive and the trait ones. */
.status-passive-row {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    padding: 6px 4px;
    border-bottom: none;
}

.status-passive-row:last-child {
    border-bottom: none;
}

.status-passive-body {
    flex: 1 1 auto;
    min-width: 0;
}

.status-passive-name {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    font-family: var(--font-ui);
    font-size: 0.942em;
    font-weight: bold;
    color: var(--text-primary-hover);
    margin-bottom: 2px;
}

.status-passive-tag {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    font-weight: 600;
    color: var(--text-text-alt-4);
    background: transparent;
    border: 1px solid var(--border-success);
    border-radius: 4px;
    padding: 1px 7px;
}

.status-passive-desc {
    font-family: var(--font-ui);
    font-size: 0.856em;
    line-height: 1.35;
    color: var(--text-card-medium);
}

.status-empty-note {
    font-family: var(--font-ui);
    font-style: normal;
    text-align: center;
    color: var(--text-card-medium);
    padding: 12px;
    font-size: 0.892em;
}

/* Actions bar under the tab panels (Empathize). */
.status-actions {
    flex: 0 0 auto;
    display: flex;
    justify-content: center;
    gap: 10px;
    margin-top: 10px;
}

.status-actions:empty {
    display: none;
}

.status-actions .inspect-btn {
    font-size: 0.928em;
    padding: 5px 22px;
}

.status-trait-head {
    display: flex;
    align-items: center;
    gap: 8px;
    color: var(--text-primary-hover);
    font-weight: bold;
    font-size: 1.019em;
    border-bottom: none;
    padding-bottom: 4px;
    margin-bottom: 6px;
}

/* The name takes the row so the price badge sits against the right margin. */
.status-trait-name {
    flex: 1 1 auto;
}

/* What the whole set of traits cost, above the traits themselves. */
.status-trait-points {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    font-family: var(--font-ui);
    font-size: 0.928em;
    color: var(--text-card-medium);
    border-bottom: none;
    padding-bottom: 6px;
    margin-bottom: 4px;
}

.status-trait-desc {
    color: var(--text-card-medium);
    font-size: 0.892em;
    line-height: 1.35;
    margin-bottom: 8px;
}

.status-trait-row {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin-top: 6px;
}

.status-trait-row-label {
    flex: 0 0 auto;
    color: var(--text-primary-hover);
    font-size: 0.856em;
    font-weight: bold;
}

.status-trait-badges {
    flex: 1 1 auto;
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    justify-content: flex-end;
}

/* A chip is a small inventory slot: dark plate, hairline gold frame, the name in
   the bright value ink and the rank behind it in the caption ink. The old wash
   of gold under muted brown text was unreadable. */
.status-trait-badge {
    display: inline-flex;
    align-items: baseline;
    gap: 5px;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    padding: 3px 9px;
    font-size: 0.876em;
    line-height: 1.25;
    color: var(--text-success-active);
    font-weight: bold;
}

.status-trait-badge b {
    color: var(--text-caption-brown);
    font-weight: normal;
    font-size: 0.92em;
}

/* The specializations block is a left-aligned wrap of chips, not a right-flushed
   tail of a labelled row, so it reads as a list instead of a ragged column. */
.status-bio-section .status-trait-badges {
    justify-content: flex-start;
    gap: 5px;
}

.bodyparts-card {
    background: var(--bg-primary-hover-translucent-35);
    border: 2px solid var(--text-primary-hover);
    border-radius: 8px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
    min-height: 180px;
    box-shadow: 0 4px 8px var(--shadow-primary-hover-translucent-5);
}

/* The status sheet is read as a bare page: its cards carry no plate, no rule and
   no shadow, so only the type and the gauges sit on it. These two classes also
   dress the Biologic Simulation card, which is why the status reading is scoped
   here instead of flattened at the declaration above. */
#status-menu-container .bodyparts-card {
    background: transparent;
    border: none;
    box-shadow: none;
}

#status-menu-container .card-label {
    font-size: 0.964em;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--border-focus-hover);
    border-bottom: none;
    padding-bottom: 2px;
    margin-bottom: 7px;
}

.bodyparts-list {
    overflow-y: auto;
    flex-grow: 1;
    max-height: 420px;
    padding-right: 4px;
}

.bodyparts-list::-webkit-scrollbar {
    width: 5px;
}

.bodyparts-list::-webkit-scrollbar-track {
    background: var(--border-primary-hover-translucent-15);
}

.bodyparts-list::-webkit-scrollbar-thumb {
    background: var(--border-primary-hover-translucent-15);
    border-radius: 3px;
}

.bodypart-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 5px 6px;
    margin-bottom: 3px;
    border-radius: 4px;
    border: 1px solid transparent;
    transition: all 0.15s ease;
    cursor: pointer;
    user-select: none;
}

.bodypart-row:hover {
    background: var(--border-primary-hover-translucent-15);
}

.bodypart-row.selected {
    background: var(--border-primary-hover-translucent-15);
    border: 1px solid var(--text-primary-hover);
}

.bodypart-name {
    font-family: var(--font-ui);
    font-size: 0.892em;
    color: var(--text-text-alt-2);
    font-weight: bold;
}

.bodypart-hp-container {
    position: relative;
    width: 110px;
    height: 16px;
    background: var(--shadow-primary-hover-translucent-5);
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid var(--border-primary-hover-translucent-15);
    display: flex;
    justify-content: center;
    align-items: center;
}

.bodypart-bar {
    position: absolute;
    left: 0;
    top: 0;
    height: 100%;
    background: var(--gradient-12);
}

.bodypart-hp-val {
    position: relative;
    font-family: var(--font-ui);
    font-size: 0.82em;
    font-weight: bold;
    color: var(--text-warning-hover);
    text-shadow: 1px 1px 2px var(--shadow-heavy);
    z-index: 2;
}

.bodypart-row.destroyed {
    opacity: 0.6;
}

.bodypart-row.destroyed .bodypart-name {
    text-decoration: line-through;
    color: var(--text-secondary-active);
}

.bodypart-row.destroyed .bodypart-hp-container {
    border-color: var(--text-secondary-active);
}

.bodypart-row.destroyed .bodypart-hp-val {
    color: var(--text-text-alt-25);
}

/* Extracted from TunableRadio.js */
#skeuo-radio-frame {
    width: 620px;
    background: var(--bg-surface);
    border: 1px solid var(--text-primary-hover);
    border-radius: 4px;
    display: flex;
    flex-direction: column;
    padding: 18px 20px;
    box-sizing: border-box;
    position: relative;
    user-select: none;
    /* The panel is raised over the LIVE map, so it is kept off the map's own
       paint: nothing inside it may cost the world a frame. */
    contain: layout style paint;
}

#radio-cabinet-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 8px;
    margin-bottom: 14px;
}

#brand-logo {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-primary-hover);
    font-weight: bold;
    letter-spacing: 1.5px;
}

#power-toggle {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: transparent;
    border: 1px solid var(--text-primary-hover);
    cursor: pointer;
    transition: all 0.2s ease;
}

/* Picked out by its own ring, not by a plate: the page shows through. */
#power-toggle:hover {
    border-color: var(--accent-gold-pure);
    box-shadow: 0 0 6px var(--shadow-gold-amber-50);
}

#radio-main-grid {
    display: flex;
    gap: 20px;
    flex: 1;
    align-items: center;
}

#tuning-console {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

#dial-glass-face {
    height: 96px;
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 3px;
    position: relative;
    overflow: hidden;
    padding: 8px 12px;
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    box-sizing: border-box;
}

.dial-scale {
    height: 20px;
    position: relative;
    border-bottom: 1px solid var(--border-border-alt-6-translucent-25);
    margin-bottom: 2px;
}

.dial-scale-label {
    position: absolute;
    left: 0;
    top: 0;
    font-weight: bold;
    color: var(--text-text-alt-20);
    font-size: 0.82em;
    font-family: monospace;
}

#dial-needle {
    position: absolute;
    top: 0;
    /* Where on the dial the set is tuned: the plugin's own answer. */
    left: var(--radio-needle, 50%);
    width: 3px;
    height: 100%;
    background: var(--text-primary-hover);
    transition: left 0.15s cubic-bezier(0.25, 0.8, 0.25, 1);
    pointer-events: none;
    z-index: 100;
}

#digital-readout-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 4px;
}

#nixie-display {
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 2px;
    padding: 3px 10px;
    font-family: monospace;
    font-size: 1.2em;
    font-weight: bold;
    color: var(--text-primary-hover);
    letter-spacing: 1px;
}

#station-info-screen {
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 2px;
    padding: 6px 12px;
    color: var(--text-text-alt-21);
    font-family: monospace;
    font-size: 0.96rem;
    overflow: hidden;
    height: 46px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

#radio-control-deck {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 14px;
    margin-top: 14px;
}

.control-knob-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    width: 80px;
}

.knob-label {
    font-family: var(--font-ui);
    font-size: 0.915rem;
    color: var(--text-primary-hover);
    letter-spacing: 1px;
    font-weight: bold;
}

.knob-base {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: transparent;
    border: 1px solid var(--text-primary-hover);
    position: relative;
    transition: transform 0.1s ease-out;
}

.knob-pointer {
    width: 2px;
    height: 14px;
    background: var(--text-primary-hover);
    position: absolute;
    top: 3px;
    left: 50%;
    transform: translateX(-50%);
}

#band-push-buttons {
    display: flex;
    gap: 8px;
}

.band-btn,
.utility-btn {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    text-align: center;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 2px;
    color: var(--text-primary-hover);
    font-weight: bold;
    padding: 4px 10px;
    cursor: pointer;
    user-select: none;
    transition: all 0.2s ease;
}

.band-btn:hover,
.band-btn.active,
.utility-btn:hover,
.utility-btn.active,
.utility-btn.gold-star {
    color: var(--text-primary-hover);
    border-color: var(--text-primary-hover);
}

#action-deck-buttons {
    display: flex;
    gap: 8px;
}

/* Paste-a-web-radio: a card over the cabinet's own face, not over the map. */
.radio-modal {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--shadow-black-translucent-50);
    border-radius: 16px;
    /* Over the dial needle, which sits at 100 inside the same cabinet. */
    z-index: 200;
}

.radio-modal[hidden] {
    display: none;
}

.radio-modal-panel {
    width: min(520px, 88%);
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 18px 20px;
    background: var(--bg-surface);
    border: 1px solid var(--text-primary-hover);
    border-radius: 4px;
}

.radio-modal-title {
    font-size: 1.2rem;
    font-weight: bold;
    color: var(--radio-ivory);
}

.radio-modal-hint {
    font-size: 0.86rem;
    color: var(--radio-brass);
    line-height: 1.35;
}

.radio-modal-field {
    font-family: var(--font-ui);
    font-size: 1rem;
    padding: 8px 10px;
    color: var(--radio-lit);
    background: var(--shadow-black-translucent-50);
    border: 1px solid var(--border-border-alt-2);
    border-radius: 4px;
    user-select: text;
}

.radio-modal-error {
    min-height: 1.1em;
    font-size: 0.86rem;
    color: var(--radio-hiss);
}

.radio-modal-buttons {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
}

.radio-modal-buttons .utility-btn {
    border-color: var(--text-primary-hover);
}

/* Extracted from VehicleSystemRepair.js */
#parts-scroll-box::-webkit-scrollbar {
    width: 6px;
}

#parts-scroll-box::-webkit-scrollbar-track {
    background: var(--border-accent-hover-translucent-5);
    border-radius: 3px;
}

#parts-scroll-box::-webkit-scrollbar-thumb {
    background: var(--scroll-thumb-hover-translucent-60);
    border-radius: 3px;
}

#parts-scroll-box::-webkit-scrollbar-thumb:hover {
    background: var(--scroll-thumb-hover-translucent-60);
}

/* The strip the shared search bar is dropped into on the codex's wide page. It
   holds its height whether or not the bar has been built yet, so opening the
   search never shoves the tabs down. */
#help-search-slot {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    border-bottom: none;
    padding-bottom: 8px;
    margin-bottom: 20px;
    min-height: 40px;
    width: 100%;
}

/* Extracted from HelpMenu.js */
#help-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 100;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--gradient-1);
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    user-select: none;
    animation: fade-in 0.25s ease-out;
}

@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

/* The codex's category strip is the shared chip row, so the private .tabs-bar
   and .tab families it used to carry are gone: one tab in the game, one rule.
   The strip only needs its own air under it. */
#help-container .help-category-tabs {
    flex: 0 0 auto;
    margin-bottom: var(--sp-4);
}

/* The contents column. It scrolls inside itself, never pushing the header, the
   rail or the footer off the page. */
.topic-list-container {
    padding-right: var(--sp-3);
}

/* A row of contents draws no plate and no frame: rows are told apart by their
   spacing, and the one being read is marked by a gold hairline alone
   (docs/task/ui_fixing.md, rules 1 and 2). */
.topic-item {
    display: flex;
    align-items: center;
    padding: var(--sp-2) var(--sp-4);
    margin-bottom: var(--sp-1);
    border-radius: 4px;
    border: 1px solid transparent;
    background: transparent;
    cursor: pointer;
    transition: border-color 0.15s ease;
}

.topic-item:hover,
.topic-item.active,
.topic-item.focused {
    background: transparent;
    border-color: var(--text-primary-hover);
    outline: none;
}

/* The macrotopic rail. Same chips the backpack files its pockets with, kept
   short so a long manual does not push the list off the page. */
#help-container .help-group-chips {
    flex: 0 0 auto;
    max-height: 4.6em;
    overflow-y: auto;
    gap: 4px;
    margin-bottom: 10px;
    padding-bottom: 6px;
}

#help-container .help-group-chips .backpack-tab {
    font-size: var(--fs-chip);
    padding: 2px 8px;
}

/* The rule between two macrocategories of the manual (UI/HelpMenu.js). Not a
   row: nothing selects it, it only says which part of the book you are in. */
.topic-group-header {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    font-weight: bold;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text-secondary-active);
    padding: 4px 6px 3px 6px;
    margin: 14px 0 6px 0;
    border-bottom: none;
    opacity: 0.85;
}

.topic-group-header:first-child {
    margin-top: 0;
}

.topic-title-text {
    font-weight: bold;
    color: var(--text-success-active);
    font-size: var(--fs-body);
}

.topic-item.active .topic-title-text,
.topic-item.focused .topic-title-text {
    color: var(--text-primary-hover);
}

/* The entry pane. It is the shared .ui-detail-scroll; all it adds is the one
   hairline that says the reader has stepped into the page. */
.help-content {
    line-height: 1.6;
    border: 1px solid transparent;
    border-radius: 4px;
}

.help-content.focused {
    outline: none;
    background: transparent;
    border-color: var(--text-primary-hover);
}

.help-title {
    font-family: var(--font-ui);
    color: var(--text-primary-hover);
    margin: 0;
    text-align: left;
}

.help-body {
    text-align: left;
}

/* A manual page is prose: the column wraps it, the source never does
   (UI/HelpMenu.js turns blank lines into paragraphs and "- " into bullets). */
.help-body p {
    margin: 0 0 0.9em 0;
}

.help-body p:last-child {
    margin-bottom: 0;
}

.help-list {
    margin: 0 0 0.9em 0;
    padding-left: 1.4em;
    text-align: left;
}

.help-list li {
    margin-bottom: 0.25em;
}

.help-image {
    max-width: 80%;
    height: auto;
    margin: var(--sp-5) auto 0 auto;
    display: block;
    border-radius: 4px;
    border: 1px solid var(--border-primary-hover-translucent-15);
}

.help-image--missing {
    display: none;
}

.placeholder-message {
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-style: normal;
    color: var(--text-text-alt-9-translucent-50);
    text-align: center;
    padding: 40px;
    font-size: 16px;
}

.hints-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 30px 20px;
    border: none;
    border-radius: 6px;
    background: var(--bg-primary-hover-translucent-35);
    margin-top: 40px;
}

.hints-label {
    font-family: var(--font-ui);
    font-size: 1.238em;
    color: var(--text-secondary-active);
    margin-bottom: 10px;
    text-align: center;
}

.hints-desc {
    font-size: 0.892em;
    color: var(--text-info);
    text-align: center;
    margin-bottom: 25px;
    max-width: 320px;
    line-height: 1.4;
}

.toggle-switch {
    position: relative;
    width: 160px;
    height: 48px;
    background: var(--bg-backdrop);
    border: 2px solid var(--border-muted-focus);
    border-radius: 24px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 16px;
    box-sizing: border-box;
    font-weight: bold;
    font-family: var(--font-ui);
    font-size: 0.964em;
    transition: all 0.3s ease;
}

.toggle-switch.active {
    background: var(--text-secondary-active);
    color: var(--text-highlight-active);
    border-color: var(--text-primary-hover);
}

.toggle-switch.focused {
    outline: 3px solid var(--border-muted-focus);
    outline-offset: 2px;
}

.toggle-knob {
    position: absolute;
    top: 2px;
    left: 2px;
    width: 40px;
    height: 40px;
    background: var(--text-highlight-active);
    border: 2px solid var(--border-muted-focus);
    border-radius: 50%;
    transition: all 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    box-shadow: 0 2px 5px var(--shadow-primary-hover-translucent-5);
}

.toggle-switch.active .toggle-knob {
    left: 114px;
    background: var(--text-highlight-active);
    border-color: var(--text-primary-hover);
}

.toggle-text {
    flex: 1;
    text-align: center;
    color: var(--text-disabled);
    z-index: 1;
    pointer-events: none;
}

.toggle-switch.active .toggle-text {
    color: var(--text-highlight-active);
}


.tab-item {
    font-family: var(--font-ui);
    font-size: 0.892em;
    padding: 4px 10px;
    background: var(--border-primary-hover-translucent-15);
    border: 1px solid var(--border-primary-hover-translucent-15);
    color: var(--text-primary-hover);
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.2s ease;
}

.tab-item:hover,
.tab-item.active {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    border-color: var(--chip-active-fg);
}

.recipe-thumb-container {
    width: 38px;
    height: 38px;
    border: 1px solid var(--text-primary-hover);
    background: var(--bg-secondary-hover);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    overflow: hidden;
    position: relative;
}

.recipe-thumb {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
}

/* The skill atlas' school grid (CharacterCreation/SkillMaster.js). Three across
   with the backpack: the left page is 58% of a wide screen and two columns of
   short cards left a third of it empty. The scene walks it with a cursor, so
   SM_CATEGORY_COLS in the plugin follows this track count. */
.category-grid,
.sm-school-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: var(--sp-3);
    overflow-y: auto;
    flex-grow: 1;
    padding-right: 4px;
    align-content: start;
    box-sizing: border-box;
}

/* A school draws no plate and no frame: eight bordered boxes are eight boxes,
   not a list (docs/task/ui_fixing.md, rules 1 and 2). The ground is the page,
   and the one school being read is marked by a gold hairline alone. */
.category-card {
    background: transparent;
    border: 1px solid transparent;
    justify-self: center;
    width: 100%;
    max-width: 190px;
    border-radius: 4px;
    padding: var(--sp-3) var(--sp-2);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    gap: var(--sp-2);
    cursor: pointer;
    transition: border-color 0.15s ease;
    min-height: 84px;
    box-sizing: border-box;
    user-select: none;
    font-family: var(--font-ui);
}

.category-card:hover,
.category-card.focused,
.category-card.selected {
    background: transparent;
    border-color: var(--text-primary-hover);
    box-shadow: none;
}

.category-card-icon {
    transform: scale(1.35);
    flex-shrink: 0;
    image-rendering: pixelated;
}

.category-card-name,
.category-card-title {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    line-height: 1.2;
    color: var(--text-success-active);
    font-weight: bold;
    letter-spacing: 0.3px;
}

.category-card.focused .category-card-name,
.category-card.selected .category-card-name,
.category-card.selected .category-card-title {
    color: var(--text-primary-hover);
}

/* The KP multiplier a school is worth to this pupil. A filled chip never
   carries muted ink, so the affinity chips take the bright inversion and the
   foreign mark stays transparent with the label ink. */
.sm-school-badge {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    background: var(--text-secondary-active);
    color: var(--bg-secondary-hover);
    padding: 1px 5px;
    font-weight: bold;
    letter-spacing: 0.5px;
}

.sm-school-badge--foreign {
    background: transparent;
    color: var(--text-text-alt-4);
    border: 1px solid var(--border-primary-hover-translucent-15);
}

.sm-pupil-line {
    font-family: var(--font-ui);
    font-size: var(--fs-label);
    color: var(--text-text-alt-4);
    text-align: center;
    margin-top: var(--sp-2);
}

.sm-pupil-line strong {
    color: var(--text-success-active);
}

/* Extracted from Health_BiologicSimulation.js */
#biologic-container {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: var(--gradient-4), var(--bg-bg-alt-1-translucent-70);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
}

/* The shared .right-page is overflow:hidden; the biology sheet is taller than
   the page, so it scrolls here and shows the bar it scrolls with. */
/* The right page holds the anatomy list and only that; the pane inside it is
   what scrolls. */
#biologic-container .right-page {
    overflow: hidden;
    justify-content: flex-start;
    scrollbar-width: thin;
    scrollbar-color: var(--text-primary-hover) var(--shadow-primary-hover-translucent-5);
}

.right-page::-webkit-scrollbar {
    width: 10px;
}

.right-page::-webkit-scrollbar-track {
    background: var(--shadow-primary-hover-translucent-5);
    border-radius: 5px;
}

.right-page::-webkit-scrollbar-thumb {
    background: var(--text-primary-hover);
    border-radius: 5px;
    border: 2px solid transparent;
    background-clip: padding-box;
}

.right-page::-webkit-scrollbar-thumb:hover {
    background: var(--text-primary-hover);
    background-clip: padding-box;
    opacity: 1;
}

/* The party selector, wherever it is drawn. It says whose hands the page is in
   and nothing more, so it is written as a line of names rather than a rail of
   filled chips: no plate, no glow, the open one inked and underlined
   (docs/task/ui_fixing.md, rules 1 and 2). */
.companion-tabs-row {
    display: flex;
    justify-content: center;
    align-items: baseline;
    gap: 2px;
    margin-bottom: 2px;
    border-bottom: none;
    padding-bottom: 2px;
}

.companion-tab {
    font-family: var(--font-ui);
    font-size: 0.94em;
    padding: 2px 8px;
    margin: 0;
    color: var(--text-text-alt-4);
    cursor: pointer;
    background: none;
    border: none;
    border-bottom: 1px solid transparent;
    border-radius: 0;
    opacity: 0.6;
    transition: color 0.15s ease, opacity 0.15s ease, border-color 0.15s ease;
    user-select: none;
}

.companion-tab.selected {
    background: none;
    color: var(--text-primary-hover);
    border-bottom-color: var(--text-primary-hover);
    box-shadow: none;
    font-weight: bold;
    opacity: 1;
}

.companion-tab:not(.selected):hover {
    background: none;
    color: var(--text-primary-hover);
    opacity: 0.85;
}

/* The right page's smaller heading: the same ink and the same dashed rule as
   .title, one step down in size, so both pages of a spread are plainly the
   same hand. */
.right-title {
    font-family: var(--font-ui);
    font-size: 1.333em;
    color: var(--text-primary-hover);
    margin: 0 0 12px 0;
    text-align: center;
    border-bottom: none;
    padding-bottom: 4px;
}

.status-bust-wrapper {
    position: relative;
    width: 100%;
    max-width: 560px;
    /* The portrait keeps its aspect ratio and shrinks with the page, filling the
       wrapper instead of spilling over the gauges. */
    /* Gives up its height to the gauge block below rather than the other way
       round, so the bars are never squeezed into the page foot. */
    flex: 1 1 auto;
    min-height: 180px;
    max-height: 52vh;
    margin: 0 auto 10px auto;
    background: transparent;
    border: none;
    box-shadow: none;
    overflow: hidden;
}

#biologic-bust {
    width: 100%;
    height: 100%;
    display: block;
    background: transparent;
    border-radius: 0;
}

.category-index {
    display: flex;
    flex-direction: column;
    gap: 5px;
    margin-top: auto;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 8px;
    padding: 8px;
    max-height: 240px;
    overflow-y: auto;
}

.category-tab {
    font-family: var(--font-ui);
    font-size: 1.048em;
    padding: 6px 14px;
    color: var(--text-primary-hover);
    cursor: pointer;
    border-radius: 4px;
    border-left: 3px solid transparent;
    transition: all 0.2s ease;
    user-select: none;
}

.category-tab:hover {
    background: var(--border-primary-hover-translucent-15);
}

.category-tab.selected {
    background: var(--border-primary-hover-translucent-15);
    border-left: 3px solid var(--text-primary-hover);
    font-weight: bold;
    color: var(--text-muted-hover);
}

/* Horizontal tab strip pinned to the top of the right page (Biologics) */
.category-tabs-top {
    position: sticky;
    top: 0;
    z-index: 5;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 4px 6px;
    padding: 2px 0 8px 0;
    margin-bottom: 14px;
    background: var(--gradient-34), var(--gradient-26);
    border-bottom: 2px solid var(--border-primary-hover-translucent-15);
}

.category-tab-top {
    font-family: var(--font-ui);
    font-size: 0.942em;
    padding: 4px 10px;
    color: var(--text-primary-hover);
    cursor: pointer;
    border-radius: 4px 4px 0 0;
    border-bottom: 2px solid transparent;
    transition: all 0.2s ease;
    user-select: none;
    white-space: nowrap;
}

.category-tab-top:hover {
    background: var(--border-primary-hover-translucent-15);
}

.category-tab-top.selected {
    background: var(--border-primary-hover-translucent-15);
    border-bottom: 2px solid var(--text-primary-hover);
    font-weight: bold;
    color: var(--text-muted-hover);
}

.card {
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 8px;
    padding: 14px;
    margin-bottom: 14px;
}

.card-header {
    font-family: var(--font-ui);
    font-size: 1.238em;
    color: var(--text-primary-hover);
    font-weight: bold;
    border-bottom: none;
    padding-bottom: 4px;
    margin-bottom: 10px;
}

.grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.grid-3 {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
}

.metric-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-ui);
    font-size: 0.928em;
    padding: 4px 0;
    color: var(--text-muted-hover);
}

.metric-label {
    font-weight: bold;
    color: var(--text-primary-hover);
}

.metric-value {
    font-weight: bold;
}

.badge {
    font-family: var(--font-ui);
    font-size: 0.856em;
    font-weight: bold;
    border: 1px solid var(--border-muted-focus);
    padding: 2px 8px;
    background: var(--border-secondary-hover-translucent-15);
    color: var(--text-success-active);
}

.badge.success {
    background: var(--bg-bg-alt-9-translucent-15);
    color: var(--text-text-alt-18);
    border: 1px solid var(--bg-bg-alt-9-translucent-15);
}

.badge.warning {
    background: var(--bg-bg-alt-5-translucent-15);
    color: var(--text-text-alt-23);
    border: 1px solid var(--bg-bg-alt-5-translucent-15);
}

.badge.danger {
    background: var(--shadow-soft-active-translucent-25);
    color: var(--text-secondary-active);
    border: 1px solid var(--shadow-soft-active-translucent-25);
}

.badge.info {
    background: var(--bg-bg-alt-6-translucent-12);
    color: var(--text-text-alt-16);
    border: 1px solid var(--bg-bg-alt-6-translucent-12);
}

.gauge-container {
    margin-top: 4px;
}

.gauge-outer {
    width: 100%;
    height: 8px;
    background: var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid var(--border-primary-hover-translucent-15);
}

.gauge-inner {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s ease;
}

.gauge-inner.hp {
    background: var(--gradient-3);
}

.gauge-inner.mp {
    background: var(--gradient-2);
}

.gauge-inner.magic {
    background: var(--gradient-13);
}

/* Orgone charge reads as bioenergetic azure, distinct from the violet magic
   bar it used to share a class with. */
.gauge-inner.orgone {
    background: linear-gradient(90deg, #1b6fb5 0%, #2f9fe0 55%, #7fd4ff 100%);
    box-shadow: 0 0 6px rgba(47, 159, 224, 0.55);
}

.bodypart-cell {
    background: transparent;
    border: none;
    border-bottom: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 0;
    padding: 5px 2px;
    display: flex;
    flex-direction: column;
}

.bodypart-cell.destroyed {
    opacity: 0.65;
}

.bodypart-cell-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-ui);
    font-size: 0.842em;
    font-weight: bold;
    margin-bottom: 4px;
}

.bodypart-cell-hp {
    font-size: 0.82em;
    color: var(--text-text-alt-4);
}

.bodypart-vital-lbl {
    font-family: var(--font-ui);
    font-size: 0.842em;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.bodypart-vital-val {
    font-family: var(--font-ui);
    font-size: 0.842em;
    font-weight: bold;
    font-variant-numeric: tabular-nums;
}

.bodypart-vital-bar {
    height: 6px;
    background: var(--bg-panel);
    border-radius: 3px;
    overflow: hidden;
    margin-top: 4px;
    border: 1px solid var(--border-primary-hover-translucent-15);
}

.bodypart-vital-bar-fill {
    height: 100%;
    transition: width 0.3s ease;
}

.brain-region-card {
    background: transparent;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 6px;
    padding: 10px;
    margin-bottom: 8px;
}

.brain-region-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-ui);
    font-size: 0.928em;
    font-weight: bold;
    margin-bottom: 4px;
    border-bottom: none;
    padding-bottom: 2px;
}

.brain-region-func {
    font-family: var(--font-ui);
    font-style: normal;
    font-size: 0.856em;
    color: var(--text-text-alt-4);
    margin-bottom: 6px;
}

.brain-region-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-ui);
    font-size: 0.827em;
}

.nt-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.nt-badge {
    background: var(--border-primary-hover-translucent-15);
    color: var(--text-primary-hover);
    padding: 1px 5px;
    font-size: 0.964em;
}

.inspect-btn,
.cc-profile-open-btn,
.cc-compact-btn,
.cc-sidebar-btn,
.cc-compact-edit-btn {
    font-family: var(--font-ui);
    font-size: 1.048em;
    text-align: center;
    background: var(--bg-secondary-hover);
    border: 2px solid var(--text-primary-hover);
    color: var(--text-primary-hover);
    padding: 8px 20px;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: bold;
    box-shadow: 0 3px 6px var(--shadow-primary-hover-translucent-5);
    box-sizing: border-box;
    user-select: none;
    margin-top: 10px;
}

/* Selected is hover, here as everywhere: a card's buttons are reached with the
   pad as often as with the mouse, so the two states are the one rule. */
/* The shared rule above sets the look; these say only how much room each of
   creation's buttons takes, which is all that differs between them. */
.cc-profile-open-btn,
.cc-compact-btn,
.cc-sidebar-btn,
.cc-compact-edit-btn {
    margin-top: 0;
    font-size: var(--fs-body);
    padding: 7px 14px;
}.cc-profile-open-btn--icon {
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    padding: 2px 8px;
}

.inspect-btn:hover,
.inspect-btn.selected,
.inspect-btn:focus-visible,
.cc-profile-open-btn:hover,
.cc-profile-open-btn.selected,
.cc-compact-btn:hover,
.cc-compact-btn.selected,
.cc-sidebar-btn:hover,
.cc-sidebar-btn.selected,
.cc-compact-edit-btn:hover,
.cc-compact-edit-btn.selected {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    box-shadow: 0 4px 8px var(--shadow-primary-hover-translucent-5);
}

/* Extracted from ItemSystemEquipment.js */
#equip-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 1000;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--gradient-1);
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
    user-select: none;
    animation: fade-in 0.25s ease-out;
}

@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

/* The one page heading of the whole book. It used to be written seven times
   over, each menu quietly redefining it until only the last copy in the file
   had any effect; this is those seven merged, inked and ruled exactly as the
   backpack's own heading is (ItemSystemInventoryUI.js). The rule under it is
   the dashed one .page-header-bar draws, in the same token, so a title that
   carries its own rule and one that sits in a header bar cannot read as two
   different books. */
.title {
    font-family: var(--font-ui);
    color: var(--text-primary-hover);
    font-weight: bold;
    text-align: center;
    border-bottom: none;
    padding-bottom: 8px;
    margin: 0 0 10px 0;
    font-size: 2.14em;
    letter-spacing: 1px;
    text-shadow: 1px 1px 1px var(--bg-primary-hover-translucent-35);
}

.actor-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}

.actor-nav-arrow {
    font-size: 1.285em;
    color: var(--text-secondary-active);
    cursor: pointer;
    padding: 0 8px;
    transition: transform 0.2s ease;
}

.actor-nav-arrow:hover {
    transform: scale(1.2);
}

.actor-meta {
    text-align: center;
}

.actor-name {
    font-family: var(--font-ui);
    font-size: 1.238em;
    font-weight: bold;
    color: var(--text-disabled);
}

.actor-class {
    font-size: 0.842em;
    font-style: normal;
    color: var(--text-info);
}

.actors-stack {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 15px;
    width: 100%;
}

.actor-stack-card {
    display: flex;
    align-items: center;
    background: var(--border-secondary-hover-translucent-15);
    border: 2px solid var(--border-secondary-hover-translucent-15);
    border-radius: 6px;
    padding: 8px 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    user-select: none;
    position: relative;
}

.actor-stack-card:hover {
    background: var(--border-secondary-hover-translucent-15);
    border-color: var(--border-secondary-hover-translucent-15);
    transform: translateX(2px);
}

.actor-stack-card.active {
    background: var(--shadow-soft-active-translucent-25);
    border-color: var(--text-secondary-active);
    box-shadow: inset 0 0 8px var(--shadow-soft-active-translucent-25), 0 3px 6px var(--shadow-soft-active-translucent-25);
}

.actor-stack-avatar {
    width: 56px;
    height: 56px;
    background-size: 224px 112px;
    /* 4 columns of 56px, 2 rows of 56px */
    border-radius: 50%;
    border: 2px double var(--border-muted-focus);
    margin-right: 12px;
    flex-shrink: 0;
}

.actor-stack-meta {
    display: flex;
    flex-direction: column;
    justify-content: center;
    flex-grow: 1;
}

.actor-stack-name {
    font-family: var(--font-ui);
    font-weight: bold;
    font-size: 19px;
    color: var(--text-disabled);
}

.actor-stack-card.active .actor-stack-name {
    color: var(--text-secondary-active);
}

.actor-stack-class {
    font-size: 0.842em;
    font-style: normal;
    color: var(--text-info);
}

.scaling-box {
    text-align: center;
    font-family: var(--font-ui);
    font-size: 0.964em;
    font-weight: bold;
    color: var(--text-secondary-active);
    background: var(--border-secondary-hover-translucent-15);
    border: 1px solid var(--border-secondary-hover-translucent-15);
    border-radius: 4px;
    padding: 4px 10px;
    margin-bottom: 14px;
}

.stats-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px 12px;
    margin-bottom: 14px;
}

.stats-grid--3col {
    grid-template-columns: 1fr 1fr 1fr;
}

.stats-grid--2col {
    grid-template-columns: 1fr 1fr;
}

.stat-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.892em;
    border-bottom: none;
    padding-bottom: 2px;
}

.stat-label {
    font-family: var(--font-ui);
    font-size: 0.892em;
    color: var(--text-disabled);
    font-weight: bold;
}

/* The base stat a currently equipped weapon scales its damage on, picked out
   in the theme accent (gold under Omega Tower, ink red under Archive
   Foundation) in place of the old separate "Scaling: STR" line. Label and
   number both, so the row reads as one highlighted entry. */
.stat-label--scaling,
.stat-val--scaling {
    color: var(--text-primary-hover);
    font-weight: 700;
}

.stat-row--scaling .stat-val-new {
    font-weight: 700;
}

/* Weapon proficiency grade (F to S), parenthesized right of the scaling
   stat's own abbreviation, e.g. "STR (S)". */
.stat-scaling-grade {
    font-size: 0.92em;
    opacity: 0.85;
}

.stat-val-container {
    display: flex;
    align-items: center;
    gap: 4px;
}

.stat-val {
    font-size: 0.964em;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.stat-val-new {
    font-weight: bold;
    color: var(--text-disabled);
}

.stat-diff {
    font-size: 0.798em;
    font-weight: bold;
    margin-left: 2px;
}

.stat-diff.positive {
    color: var(--text-text-alt-3);
}

.stat-diff.negative {
    color: var(--text-text-alt-10);
}

.alchemical-stats {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.custom-stat-row {
    display: flex;
    flex-direction: column;
}

.custom-stat-header {
    display: flex;
    justify-content: space-between;
    font-size: 0.842em;
    margin-bottom: 2px;
}

.custom-stat-label {
    font-family: var(--font-ui);
    font-weight: bold;
    color: var(--text-disabled);
}

.custom-stat-val {
    font-weight: bold;
    color: var(--text-muted-hover);
}

.progress-bar-bg {
    position: relative;
    width: 100%;
    height: 6px;
    background: var(--border-secondary-hover-translucent-15);
    border-radius: 3px;
    overflow: hidden;
}

.progress-bar-fill {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    border-radius: 3px;
}

.progress-bar-fill-preview {
    position: absolute;
    top: 0;
    height: 100%;
    border-radius: 3px;
}

.equip-commands {
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 6px;
    margin-bottom: 16px;
}

.equip-main-content {
    flex: 1;
    overflow-y: auto;
    padding-right: 8px;
}

.equip-main-content::-webkit-scrollbar {
    width: 6px;
}

.equip-main-content::-webkit-scrollbar-track {
    background: var(--border-secondary-hover-translucent-15);
    border-radius: 3px;
}

.equip-main-content::-webkit-scrollbar-thumb {
    background: var(--border-secondary-hover-translucent-15);
    border-radius: 3px;
}

.equip-slot-row {
    display: flex;
    align-items: center;
    padding: 6px 12px 6px 4px;
    margin-bottom: 2px;
    border-radius: 4px;
    border: none;
    background: transparent;
    cursor: pointer;
    position: relative;
    transition: all 0.2s ease;
    box-sizing: border-box;
    overflow: hidden;
}

.equip-slot-row:hover,
.equip-slot-row.active,
.equip-slot-row.focused {
    background: var(--bg-primary-hover-translucent-35);
    box-shadow: none;
}

.slot-label-col {
    width: 116px;
    font-family: var(--font-ui);
    font-weight: 700;
    color: var(--text-secondary-active);
    font-size: 0.842em;
    flex-shrink: 0;
    text-align: left;
    white-space: nowrap;
}

.slot-item-col {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.item-icon {
    width: 32px;
    height: 32px;
    margin-right: 12px;
    /* 16 columns of 32px */
    flex-shrink: 0;
    image-rendering: pixelated;
    background-size: 512px auto;
}

.item-icon-empty {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 21px;
    color: var(--text-text-alt-4);
    flex-shrink: 0;
}

.item-rarity-bar {
    width: 5px;
    align-self: stretch;
    flex-shrink: 0;
    margin-right: 10px;
    /* The bar carries the item's .rarity--* class, which inks color from the
       --rarity-* tokens; the fill takes that same ink through currentColor, so
       the stripe and the name it sits next to can never disagree. The equip
       bench used to paint it from the raw colorCode, which is a second, neon
       ladder the presets cannot reach. */
    background: currentColor;
}

.item-name {
    font-weight: 700;
    color: var(--text-pure-white);
    font-size: 1.238em;
    font-family: var(--font-ui);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.item-name-empty {
    font-family: var(--font-ui);
    font-style: normal;
    color: var(--text-disabled);
    font-size: 1.238em;
}

/* Weapon-proficiency badge on equip rows the character is not trained for */
.item-name-row {
    display: flex;
    align-items: baseline;
    gap: 6px;
    min-width: 0;
}

.item-proficiency-tag {
    font-family: var(--font-ui);
    font-size: 0.77em;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
    flex-shrink: 0;
    padding: 2px 7px;
    color: var(--text-text-alt-4);
    border: 1px solid var(--border-success);
    border-radius: 4px;
    background: transparent;
}

.inventory-header {
    font-family: var(--font-ui);
    font-size: 19px;
    color: var(--text-secondary-active);
    border-bottom: 1px solid var(--border-secondary-hover-translucent-15);
    padding-bottom: 4px;
    margin-bottom: 10px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.inventory-back-btn {
    font-family: var(--font-ui);
    font-size: 15px;
    font-weight: bold;
    background: transparent;
    border: 2px solid var(--text-primary-hover);
    color: var(--text-primary-hover);
    padding: 3px 12px;
    border-radius: 4px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: auto;
    flex: 0 1 auto;
}

/* Three-column variant, used by the equip picker */
.inventory-grid--3col {
    grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* The equip picker lists like the backpack does: no frame, no plate, just the
   rarity stripe and a heading per type (docs/task/ui_fixing.md, rule 2). The
   grid rules come from .backpack-grid; only the full-width remove row and the
   stat chips are the bench's own. */
.equip-pick-grid {
    margin-bottom: 0;
}

.equip-pick-row--full {
    grid-column: 1 / -1;
}

.equip-pick-row .item-icon-empty {
    margin-right: 12px;
}

.equip-pick-row .item-name-row {
    align-items: center;
}

.equip-pick-row .item-slot-meta {
    justify-content: flex-start;
}

/* Changed-stat chips under an equip candidate's name */
.equip-delta-row {
    display: flex;
    flex-wrap: wrap;
    gap: 2px 6px;
    justify-content: flex-start;
}

.equip-delta-chip {
    white-space: nowrap;
    font-family: var(--font-ui);
    font-weight: 700;
}

.equip-delta-chip.positive { color: var(--text-text-alt-4); }
.equip-delta-chip.negative { color: var(--text-danger-dark); }

/* Two-column inventory grid wrapper */
.inventory-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
    align-content: start;
}

.inventory-item-row {
    display: flex;
    align-items: center;
    padding: 5px 8px 5px 0;
    margin-bottom: 0;
    border-radius: 4px;
    border: 1px solid var(--border-primary-hover-translucent-15);
    background: var(--bg-primary-hover-translucent-35);
    cursor: pointer;
    position: relative;
    transition: all 0.2s ease;
    box-sizing: border-box;
    overflow: hidden;
    min-width: 0;
}

/* Remove / special rows span both columns */
.inventory-item-row.full-width {
    grid-column: 1 / -1;
}

.inventory-item-row:hover {
    background: transparent;
    border-color: var(--text-primary-hover);
    box-shadow: 0 2px 6px var(--shadow-shadow-alt-2-hover-translucent-8);
}

.inventory-item-row.focused {
    background: transparent;
    border-color: var(--text-primary-hover);
    box-shadow: 0 2px 6px var(--shadow-shadow-alt-2-hover-translucent-8);
}

.inventory-item-row.focused::after {
    /* Feather quill (IconSet 225) instead of an emoji marker. */
    content: '';
    position: absolute;
    right: 8px;
    width: 16px;
    height: 16px;
    background-image: url('../img/system/IconSet.png');
    background-size: 256px auto;
    background-position: -16px -224px;
    image-rendering: pixelated;
    top: 50%;
    transform: translateY(-50%);
    filter: drop-shadow(1px 1px 1px var(--shadow-primary-hover-translucent-5));
}

.item-details {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
}

.item-meta-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.842em;
    color: var(--text-text-alt-4);
    margin-top: 1px;
    min-width: 0;
    overflow: hidden;
}

.item-meta-row > span {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
}

.item-meta-row > span:first-child:not(:last-child) {
    flex-shrink: 0;
    margin-right: 4px;
}

/* ── ItemSystemEquipment UI additions ── */

/* The header bar uses the shared .page-header-bar + .back-button pair with no
   scoped overrides. There used to be an #equip-container .back-button block that
   re-declared everything but font-family, at a larger font-size and thinner
   border, which made this one Back button read as a different control from every
   other screen's. */

/* Command bar row (commands + companion tabs side by side) */
.equip-command-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 15px;
    border-bottom: none;
    padding-bottom: 8px;
}

/* The rail sits inside the command bar, which already draws the dashed rule and
   the spacing under it, so the block itself keeps none of its own. The chip
   shape is the shared one above. */
#equip-container .equip-commands {
    margin-bottom: 0;
    padding-bottom: 0;
    border: none;
}

#equip-container .equip-commands .backpack-tab {
    min-width: 0;
}

/* Companion tabs, equip-scene variant (centered on the right page, no bottom border) */
#equip-container .companion-tabs-row {
    justify-content: center;
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

#equip-container .companion-tab {
    font-family: var(--font-ui);
    font-size: 1.0rem;
    padding: 2px 9px;
    margin: 0;
    color: var(--text-primary-hover);
    cursor: pointer;
    background: none;
    border: none;
    border-bottom: 1px solid transparent;
    border-radius: 0;
    opacity: 0.6;
    transition: color 0.15s ease, opacity 0.15s ease, border-color 0.15s ease;
    user-select: none;
    font-weight: normal;
}

#equip-container .companion-tab.selected {
    background: none;
    color: var(--text-primary-hover) !important;
    border-bottom-color: var(--text-primary-hover);
    box-shadow: none;
    font-weight: bold;
    opacity: 1;
}

#equip-container .companion-tab:not(.selected):hover {
    background: none;
    opacity: 0.85;
}

/* The equip bench's own text (js/plugins/ItemSystem/ItemSystemEquipmentUI.js).
   These used to be written out inline on every render, each with an opacity of
   its own dimming an already muted ink; they read the ladder instead, so the
   damage type, the description and the lore are the same three weights here as
   on the backpack's inspect page. */
.equip-stat-mod {
    font-size: 0.78em;
    color: var(--text-cost-ok);
}

.equip-stat-diff {
    font-size: 0.72rem;
    margin-left: 3px;
}

.equip-damage-type {
    margin-top: 6px;
    font-size: 1.15em;
    font-family: var(--font-ui);
    color: var(--text-secondary-active);
}

.equip-damage-type-label {
    color: var(--text-card-medium);
}

.equip-damage-type-wtype {
    font-size: 0.9em;
    color: var(--text-card-medium);
}

.equip-desc {
    margin-top: 6px;
    font-family: var(--font-ui);
    line-height: 1.35;
}

.equip-lore {
    font-style: normal;
    margin-top: 6px;
    font-family: var(--font-ui);
    line-height: 1.35;
    color: var(--text-card-medium);
}

.item-details--inset {
    margin-left: 8px;
}

#equip-companion-switcher {
    flex: 0 0 auto;
    justify-content: center;
    min-height: 26px;
    margin-bottom: 8px;
}

/* The shop counter's own furniture (js/plugins/ItemSystem/ItemSystemShop.js).
   The section rules and the stat keys were written out inline at every call
   site, each carrying a parchment brown as a literal that no preset could
   reach. */
.shop-sec-hdr {
    border-bottom: none;
    padding-bottom: 4px;
    margin-bottom: 10px;
    font-weight: bold;
    font-size: 15px;
}

.shop-sec-hdr--split {
    display: flex;
    justify-content: space-between;
    gap: 10px;
}

.shop-stat-key {
    font-weight: 500;
    width: 70px;
}

.shop-plate {
    background: var(--bg-subtle-translucent-5);
    border: 1px solid var(--border-subtle-translucent-18);
    border-radius: 4px;
    padding: 10px 14px;
}

/* The equip bench turns the spread around: the slot list is the short page and
   the bench itself the wide one, so the pieces are shown as large as the screen
   allows. The crease moves with them. */
#equip-container .left-page {
    width: 58%;
}

#equip-container .book-spread::before {
    left: 58.5%;
}

/* Right page layout. The companion switcher sits above this block in the
   normal flow, so the content area takes what is left rather than the full
   page height, which used to push the weapon preview under the tabs. */
#equip-container .right-content-area {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    height: auto;
    min-height: 0;
}

#equip-container .right-page {
    width: 42%;
    justify-content: flex-start;
}

.equip-right-content {
    display: flex;
    flex-direction: column;
    height: 100%;
    gap: 0;
}

/* Under the preview the page reads downwards, not across: the stats first,
   then the prose. Set side by side on the narrow page the two columns ran
   into each other and the description printed over the numbers. */
.bottom-stats-block {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    width: 100%;
    flex: 0 1 auto;
    min-height: 0;
    overflow-y: auto;
}

/* The twelve stats, two pairs across and tight. */
.equip-stats-col {
    flex: 0 0 auto;
    min-width: 0;
}

/* Damage type, description and lore, ruled off from the numbers above. */
.equip-lore-col {
    flex: 0 0 auto;
    min-width: 0;
    border-top: 1px solid var(--border-secondary-hover-translucent-15);
    padding-top: 8px;
}

.equip-lore-col:empty {
    border-top: none;
    padding-top: 0;
}

.equip-right-content .scaling-box {
    margin-bottom: 0;
}

.equip-right-content .stats-grid {
    margin-bottom: 0;
    gap: 4px 12px;
}

.equip-right-content .alchemical-stats {
    gap: 4px;
}

/* Weapon preview container */
.weapon-previews-container {
    display: flex;
    justify-content: center;
    gap: 20px;
    align-items: stretch;
    width: 100%;
    flex: 1;
    min-height: 300px;
    margin-bottom: 10px;
    background: none;
    border: none;
    border-radius: 8px;
    padding: 0;
    box-sizing: border-box;
    overflow: hidden;
    position: relative;
}

/* The card's ground is the battleground of the map the party stands on, set as
   an inline background-image by the scene; the wash under it is what shows when
   no battleback can be found. */
.weapon-preview-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    position: relative;
    border-radius: 6px;
    background-color: var(--bg-white-translucent-25);
    background-position: center bottom;
    background-size: cover;
    background-repeat: no-repeat;
    border: none;
    padding: 0;
    box-sizing: border-box;
    overflow: hidden;
}

/* The pieces have to read against a photograph, so the ground is dimmed to the
   depth the rest of the pane is inked at. */
.weapon-preview-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--shadow-black-translucent-50);
    border-radius: 6px;
    pointer-events: none;
    z-index: 1;
}

.weapon-preview-card--single { width: 100%; }
.weapon-preview-card--half   { width: 48%; }

.weapon-preview-card canvas {
    width: 100%;
    flex: 1;
    display: block;
    cursor: grab;
    z-index: 2;
}

.weapon-preview-icon-wrapper {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
}

.weapon-preview-icon-circle {
    width: 96px;
    height: 96px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--text-highlight-active);
    /* The ring is the item's rarity. The element carries the .rarity--* class,
       which inks color from the --rarity-* tokens, and the border takes that
       same ink through currentColor, so ring and name can never disagree. */
    border: 2.5px solid currentColor;
    box-sizing: border-box;
    border-radius: 50%;
    box-shadow: 0 6px 12px var(--shadow-black-translucent-15);
    overflow: hidden;
}

.weapon-preview-icon-circle .item-icon {
    transform: scale(2.4);
    transform-origin: center;
}

/* Remove-item option name color */
.inventory-remove-name {
    color: var(--text-text-alt-10);
}

/* Extracted from FastTravelSystem.js */
#travel-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: var(--gradient-1);
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    user-select: none;
    animation: fade-in 0.3s ease-out;
}

/* The picker is a book spread like every other screen: the frame, the ground
   and the paper come from the shared .travel-book-spread selector at the head
   of this file, so nothing is restated here but the split. The list is short
   rows and the map is the content, so the wide half is the map's: 58/42 the
   other way round, and the binding spine moves with it. */
.travel-book-spread {
    overflow: hidden;
}

.travel-book-spread::before {
    left: 42%;
}

.travel-left-page {
    width: 42%;
    justify-content: flex-start;
}

.travel-right-page {
    width: 58%;
    padding: 0;
    justify-content: flex-start;
}

/* The two faces of the left page: the list, and the confirmation that replaces
   it. Both fill the page; the plugin swaps which one is shown. */
.travel-list-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    width: 100%;
    min-height: 0;
}

.ui-detail.travel-confirm-panel {
    display: none;
    width: 100%;
    animation: fade-in 0.25s ease-out;
}

.travel-transport-info {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--sp-3);
    background: none;
    border: none;
    padding: 0 0 var(--sp-3) 0;
    margin-bottom: var(--sp-3);
}

.travel-transport-name {
    font-family: var(--font-ui);
    font-size: var(--fs-heading);
    font-weight: bold;
    color: var(--text-primary-hover);
}

.travel-transport-rate {
    font-size: var(--fs-label);
    color: var(--text-text-alt-4);
}

.travel-dest-list {
    flex-grow: 1;
    overflow-y: auto;
    padding-right: 8px;
    display: flex;
    flex-direction: column;
    gap: var(--sp-1);
}

.travel-dest-list::-webkit-scrollbar {
    width: 6px;
}

.travel-dest-list::-webkit-scrollbar-track {
    background: var(--border-primary-hover-translucent-15);
    border-radius: 3px;
}

.travel-dest-list::-webkit-scrollbar-thumb {
    background: var(--border-focus-hover);
    border-radius: 3px;
}

/* A destination is a row on the page, not a card: no plate under it and no
   frame around it. The only mark it carries is the left rule that says what
   kind of place it is. */
.travel-dest-item {
    display: flex;
    flex-direction: column;
    padding: 6px 10px;
    background: none;
    border: 1px solid transparent;
    border-radius: 4px;
    cursor: pointer;
    user-select: none;
}

/* Destinations the transport network reaches, i.e. the entries that declare an
   arrival stop of their own. Declared before the hover/selected rule so
   selection still repaints the border on top of it; the inset stripe survives
   because selection never sets box-shadow. */
.travel-dest-item.is-hub {
    box-shadow: inset 3px 0 0 var(--accent-gold-pure);
}

/* The kind of place, from the entry's own "type". A village is the plain row;
   the rest carry a left rule of their own, which the gold hub stripe overrides
   where a place is both. */
.travel-dest-item.travel-kind-city {
    box-shadow: inset 3px 0 0 var(--text-primary-hover);
}

.travel-dest-item.travel-kind-dungeon {
    box-shadow: inset 3px 0 0 var(--text-danger-hover);
}

.travel-dest-item.travel-kind-gasstation {
    box-shadow: inset 3px 0 0 var(--text-success-active);
}

.travel-dest-item.is-hub.travel-kind-city,
.travel-dest-item.is-hub.travel-kind-dungeon,
.travel-dest-item.is-hub.travel-kind-gasstation {
    box-shadow: inset 3px 0 0 var(--accent-gold-pure);
}

.travel-dest-hub {
    display: inline-block;
    margin-left: 8px;
    padding: 0;
    border: none;
    background: none;
    color: var(--accent-gold-pure);
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    font-style: normal;
    font-weight: bold;
    letter-spacing: 0.04em;
    vertical-align: middle;
}

/* One appearance for hover and for selection, the same as everywhere else: a
   gold hairline and nothing behind it. */
.travel-dest-item:hover,
.travel-dest-item.selected {
    background: none;
    border-color: var(--text-primary-hover);
}

.travel-dest-name {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-primary-hover);
    font-weight: bold;
}

.travel-dest-meta {
    display: flex;
    justify-content: space-between;
    font-size: var(--fs-label);
    color: var(--text-text-alt-4);
    font-style: normal;
    margin-top: 2px;
}

.travel-dest-cost {
    font-weight: bold;
    color: var(--text-success-active);
}

.travel-dest-item.disabled {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
}

/* The confirmation that replaces the list: the place, then the four facts of
   the journey, then the button strip at the foot of the page. */
.travel-confirm-dest {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-title);
    color: var(--text-detail-heading);
    text-align: center;
    margin-bottom: var(--sp-5);
    font-weight: bold;
}

/* The plate of the place, between its name and its numbers. Always 4:3, never
   wider than the page, and it keeps its box so the facts under it do not jump
   as one destination is picked after another. */
.travel-confirm-picture {
    width: 100%;
    max-width: 320px;
    aspect-ratio: 4 / 3;
    margin: 0 auto var(--sp-4) auto;
    border: 1.5px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    overflow: hidden;
    background: var(--bg-surface);
}

.travel-confirm-plate {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

/* The four facts are read as a block, not as four bars spanning the page: the
   grid is centred and only as wide as its own text, so label and value stay
   next to each other instead of at opposite edges. */
.travel-confirm-details {
    display: grid;
    grid-template-columns: auto auto;
    justify-content: center;
    align-content: start;
    column-gap: var(--sp-4);
    row-gap: var(--sp-1);
    flex-grow: 0;
}

.travel-confirm-details .inspect-spec-row {
    display: contents;
}

.travel-confirm-details .inspect-spec-value {
    text-align: right;
}

/* One button, centred, sized to its label. */
.travel-confirm-actions {
    align-items: center;
    margin-top: var(--sp-5);
}

.travel-confirm-actions .inspect-btn {
    min-width: 180px;
    width: auto;
    padding-left: var(--sp-5);
    padding-right: var(--sp-5);
}

.travel-map-viewer {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: var(--bg-surface);
    cursor: grab;
}

.travel-map-wrapper {
    position: absolute;
    top: 0;
    left: 0;
    width: 1232px;
    height: 1039px;
    transform-origin: 0 0;
}

.travel-map-img {
    position: absolute;
    top: 0;
    left: 0;
    width: 1232px;
    height: 1039px;
    pointer-events: none;
    user-select: none;
}

/* After the impact there is no Europe to draw: the right page becomes the
   space the Earth used to occupy, with the Omega Tower hanging at the middle
   of it. Painted rather than loaded, so no asset is needed for it and the
   starfield never fails to arrive (FastTravelSystem, earthLost). */
.travel-map-space {
    position: absolute;
    top: 0;
    left: 0;
    width: 1232px;
    height: 1039px;
    pointer-events: none;
    user-select: none;
    background:
        radial-gradient(circle at 22% 28%, rgba(90, 70, 160, 0.20), transparent 46%),
        radial-gradient(circle at 74% 68%, rgba(40, 90, 140, 0.18), transparent 52%),
        radial-gradient(2px 2px at 12% 18%, #fff, transparent),
        radial-gradient(2px 2px at 37% 62%, #dfe8ff, transparent),
        radial-gradient(1px 1px at 58% 12%, #fff, transparent),
        radial-gradient(2px 2px at 81% 34%, #ffe9c0, transparent),
        radial-gradient(1px 1px at 26% 81%, #fff, transparent),
        radial-gradient(1px 1px at 66% 88%, #cfe0ff, transparent),
        radial-gradient(2px 2px at 92% 74%, #fff, transparent),
        radial-gradient(1px 1px at 45% 41%, #fff, transparent),
        #05060c;
}

/* The tower itself: a thin black lance with gold along its edge, standing at
   the centre of the page where the marker for it is placed. */
.travel-space-tower {
    position: absolute;
    width: 14px;
    height: 190px;
    margin-left: -7px;
    margin-top: -150px;
    background: linear-gradient(180deg,
        transparent 0%,
        #c9a03c 3%,
        #0b0b10 9%,
        #0b0b10 88%,
        #1a1a22 100%);
    clip-path: polygon(50% 0%, 62% 12%, 78% 100%, 22% 100%, 38% 12%);
    box-shadow: 0 0 26px rgba(201, 160, 60, 0.45), 0 0 70px rgba(201, 160, 60, 0.18);
}

.travel-svg-layer {
    position: absolute;
    top: 0;
    left: 0;
    width: 1232px;
    height: 1039px;
    pointer-events: none;
    z-index: 5;
}

.travel-route-line {
    stroke: var(--text-primary-hover);
    stroke-width: 4px;
    stroke-linecap: round;
    stroke-dasharray: 8, 8;
    fill: none;
    animation: route-dash 30s linear infinite;
}

@keyframes route-dash {
    to {
        stroke-dashoffset: -1000;
    }
}

.travel-route-line-bg {
    stroke: var(--accent-gold-translucent-40);
    stroke-width: 8px;
    stroke-linecap: round;
    fill: none;
}

.travel-marker {
    position: absolute;
    width: 10px;
    height: 10px;
    margin-left: -5px;
    margin-top: -5px;
    border-radius: 50%;
    background: var(--text-disabled);
    border: 1.25px solid var(--text-danger-hover);
    box-shadow: 0 2px 5px var(--shadow-glow-active-translucent-40);
    cursor: pointer;
    z-index: 10;
    transition: all 0.2s ease;
}

/* The SHAPE of a pin says what kind of place it is, from the entry's own "type"
   in Destinations.json. A village keeps the plain disc above; a city is a
   larger square, a delve a diamond, a roadside stop a narrow upright pill.
   Colour is a separate question, answered by .is-hub below. */
.travel-marker.travel-kind-city {
    width: 13px;
    height: 13px;
    margin-left: -6.5px;
    margin-top: -6.5px;
    border-radius: 2px;
}

.travel-marker.travel-kind-dungeon {
    width: 13px;
    height: 13px;
    margin-left: -6.5px;
    margin-top: -6.5px;
    border-radius: 0;
    /* The border is clipped away with the corners, so the fill has to carry the
       shape on its own. */
    clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
    background: var(--text-danger-hover);
}

.travel-marker.travel-kind-gasstation {
    width: 7px;
    height: 12px;
    margin-left: -3.5px;
    margin-top: -6px;
    border-radius: 2px;
}

/* Places the transport network actually reaches read bigger and in gold, every
   other stop stays grey. Declared before hover/selected so the selected state
   keeps winning on colour while the larger size persists. */
.travel-marker.is-hub {
    width: 14px;
    height: 14px;
    margin-left: -7px;
    margin-top: -7px;
    background: var(--accent-gold-pure);
    border-width: 2px;
    /* A hub is the pin that has to stay readable and clickable where the map
       crowds: it is drawn over every plain stop it overlaps. */
    z-index: 11;
}

.travel-marker.is-hub.travel-kind-city {
    width: 17px;
    height: 17px;
    margin-left: -8.5px;
    margin-top: -8.5px;
}

.travel-marker.is-hub.travel-kind-gasstation {
    width: 9px;
    height: 15px;
    margin-left: -4.5px;
    margin-top: -7.5px;
}

.travel-marker:hover,
.travel-marker.selected {
    transform: scale(1.3);
    background: var(--text-primary-hover);
    border-color: var(--text-text-alt-14-hover);
    box-shadow: 0 4px 10px var(--shadow-shadow-alt-4-hover-translucent-60);
}

.travel-marker-tooltip {
    position: absolute;
    bottom: 16px;
    left: 50%;
    transform: translateX(-50%);
    background: #000000;
    color: var(--text-primary-hover);
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    padding: 4px 8px;
    border-radius: 4px;
    border: 1px solid var(--text-primary-hover);
    white-space: nowrap;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s ease;
    z-index: 20;
    box-shadow: 0 4px 8px var(--shadow-glow-active-translucent-40);
}

.travel-marker:hover .travel-marker-tooltip {
    opacity: 1;
}

.travel-player-marker {
    position: absolute;
    width: 20px;
    height: 20px;
    margin-left: -10px;
    margin-top: -10px;
    z-index: 15;
    pointer-events: none;
}

.travel-player-pulse {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    background: var(--bg-bg-alt-7-translucent-12);
    border: 2px solid var(--text-text-alt-3);
    animation: player-ring 1.8s ease-out infinite;
    box-sizing: border-box;
}

.travel-player-dot {
    position: absolute;
    top: 6px;
    left: 6px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--text-text-alt-3);
    border: 1.5px solid var(--text-warning-hover);
    box-shadow: 0 0 8px var(--text-text-alt-3);
}

@keyframes player-ring {
    0% {
        transform: scale(0.6);
        opacity: 1;
    }

    100% {
        transform: scale(1.8);
        opacity: 0;
    }
}

.travel-zoom-controls {
    position: absolute;
    bottom: 20px;
    right: 20px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    z-index: 100;
}

.travel-zoom-btn {
    width: 40px;
    height: 40px;
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    border: 2px solid var(--border-subtle);
    border-radius: 4px;
    font-family: var(--font-ui);
    font-size: var(--fs-heading);
    font-weight: bold;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: 0 4px 8px var(--shadow-glow-active-translucent-40);
    transition: all 0.2s ease;
}

.travel-zoom-btn:hover {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    border-color: var(--chip-active-fg);
    transform: translateY(-2px);
}

.travel-edit-toolbar {
    position: absolute;
    top: 12px;
    left: 12px;
    display: flex;
    gap: 6px;
    z-index: 100;
}

/* No plate behind a control and no grey on it (ui_fixing rules 1 and 4): the
   danger is said in the ink and the hairline, the ground stays the page. */
.travel-edit-btn {
    padding: 6px 14px;
    background: transparent;
    color: var(--text-blood-red);
    border: 1px solid var(--text-blood-red);
    border-radius: 4px;
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    font-weight: bold;
    cursor: pointer;
    box-shadow: 0 2px 6px var(--border-subtle-translucent-25);
    transition: all 0.15s ease;
}

.travel-edit-btn:hover {
    background: var(--border-subtle);
    color: var(--text-danger-hover);
}

.travel-edit-btn.active {
    background: var(--bg-danger-dark);
    color: var(--text-danger-hover);
    border-color: var(--border-danger-dark);
}

.travel-map-viewer.edit-mode .travel-marker {
    cursor: move;
}

@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

/* Extracted from ItemSystemShop.js */
#shop-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 100;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--gradient-1);
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
    user-select: none;
    animation: fade-in 0.22s ease-out;
}

@keyframes fade-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.shop-left,
.shop-right {
    flex: 1;
    padding: 10px 20px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    height: 100%;
}

.shop-left {
    border-right: none;
}

.shop-right {
    padding-left: 30px;
}

/* The head of either page: Back pinned left, title centred, ruled off from the
   list under it. It used to carry its colours inline, so the rule and the Back
   button stayed parchment-brown on every theme. */
.shop-funds {
    font-family: var(--font-ui);
    font-size: 20px;
    font-weight: bold;
    text-align: center;
    letter-spacing: 0.5px;
    margin-top: -10px;
    margin-bottom: 12px;
    color: var(--text-inverse);
}

.shop-funds-value {
    color: var(--text-cost-ok);
}

.shop-title {
    font-family: var(--font-ui);
    font-size: 2.14em;
    color: var(--text-secondary-active);
    border-bottom: 2px solid var(--border-muted-focus);
    padding-bottom: 6px;
    margin: 0 0 16px 0;
    text-align: center;
    letter-spacing: 1px;
    position: relative;
}

.shop-back-btn {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.892em;
    font-family: var(--font-ui);
    background: var(--border-secondary-hover-translucent-15);
    border: 1.5px solid var(--border-muted-focus);
    border-radius: 4px;
    padding: 4px 10px;
    cursor: pointer;
    color: var(--text-secondary-active);
    transition: all 0.2s ease;
    user-select: none;
    line-height: 1.2;
}

.shop-back-btn:hover {
    background: var(--chip-active-bg) !important;
    color: var(--chip-active-fg) !important;
    border-color: var(--chip-active-fg) !important;
}

.shop-tabs {
    display: flex;
    border-bottom: 1px solid var(--border-secondary-hover-translucent-15);
    padding-bottom: 2px;
    margin-bottom: 14px;
    gap: 8px;
}

.shop-tab {
    flex: 1;
    font-family: var(--font-ui);
    font-size: 0.964em;
    text-align: center;
    padding: 6px 4px;
    cursor: pointer;
    color: var(--text-inverse);
    transition: all 0.2s ease;
}

.shop-tab.active {
    color: var(--text-secondary-active);
    font-weight: bold;
    border-bottom: 2px solid var(--text-secondary-active);
}

/* "TAB" / "L1 R1" chip in front of the two tabs: names the only button that
   flips between Acquire and Liquidate. Not clickable, so it is skipped by
   every focus ring, and it never grows at the tabs' expense. */
.shop-tab-hint {
    flex: 0 0 auto;
    align-self: center;
    padding: 3px 8px;
    font-size: 0.8em;
    font-weight: bold;
    letter-spacing: 0.06em;
    color: var(--text-inverse);
    border: none;
    border-radius: 4px;
    user-select: none;
    -webkit-user-select: none;
    pointer-events: none;
    white-space: nowrap;
}

/* The shop's category chips. They are the backpack's own tabs (.backpack-tab),
   so both pages of the book read the same; only the row's own spacing, and the
   ring that shows the cursor is standing on the row, belong to the shop. */
.shop-chips {
    margin-bottom: 12px;
}

.shop-chips.focused {
    outline: 2px solid var(--text-secondary-active);
    outline-offset: 2px;
}

.catalog-viewport {
    flex: 1;
    overflow-y: auto;
    padding-right: 4px;
}

/* A line the player has done nothing with carries no fill of its own: the only
   cards that light up are the one under the cursor and the ones on the
   counter, so a long list reads as a list rather than a wall of plates. */
/* The counter carries no plates and no frames: a line is a line of text, and
   the cursor and the counter are marked by ink alone. */
.item-card {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 5px 12px;
    margin-bottom: 4px;
    background: transparent;
    border: none;
    cursor: pointer;
    transition: color 0.2s ease;
}

#shop-container .item-card:hover .item-card-name,
#shop-container .item-card.focused .item-card-name {
    color: var(--text-secondary-active) !important;
    text-decoration: underline;
}

.item-card-left {
    display: flex;
    align-items: center;
    gap: 10px;
}

.item-card-icon {
    width: 32px;
    height: 32px;
}

.item-card-info {
    display: flex;
    flex-direction: column;
}

.item-card-name {
    font-size: 1.05em;
    font-weight: bold;
}

.item-card-sub {
    font-size: 0.842em;
    color: var(--text-inverse);
    margin-top: 2px;
}

.item-card-right {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
}

.item-card-price {
    font-size: 0.964em;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.item-card-stock {
    font-size: 0.842em;
    color: var(--text-secondary-active);
    font-weight: bold;
}

/* A sell line the player has put on the counter: it keeps its own quantity and
   subtotal, so several lines can be trimmed before the one sale goes through. */
.item-card.selected {
    background: transparent;
    border: none;
}

#shop-container .item-card.selected .item-card-name {
    color: var(--text-cost-ok) !important;
}

.sell-qty {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 4px;
}

.sell-qty-step {
    width: 22px;
    height: 22px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 3px;
    font-weight: bold;
    cursor: pointer;
    background: transparent;
    color: var(--text-primary-hover);
    border: 1px solid var(--border-gold-amber-30);
    box-sizing: border-box;
    transition: all 0.15s ease;
}

.sell-qty-step:hover {
    background: var(--chip-active-bg);
    border-color: var(--chip-active-fg);
}

.sell-qty-val {
    min-width: 28px;
    text-align: center;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.sell-qty-total {
    font-size: 0.892em;
    font-weight: bold;
    color: var(--text-cost-ok);
}

/* A line in the basket is money going out, not coming in. */
.sell-qty-total.cost {
    color: var(--text-cost-bad);
}

/* Nothing on the shelf, or nothing in the bag: one bracketed word, centred. */
.shop-empty-note {
    font-family: var(--font-ui);
    text-align: center;
    color: var(--text-brown-medium);
    margin-top: 40px;
}

.shop-selection-bar {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 0;
    margin-bottom: 10px;
    border: none;
    background: transparent;
}

.shop-selection-bar .selection-summary {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
    font-family: var(--font-ui);
}

.shop-selection-bar .selection-count {
    font-size: 0.842em;
    color: var(--text-inverse);
}

.shop-selection-bar .selection-value {
    font-size: 1.095em;
    font-weight: bold;
    color: var(--text-cost-ok);
}

.shop-selection-bar .selection-value.cost {
    color: var(--text-cost-bad);
}

.shop-selection-bar .selection-actions {
    display: flex;
    gap: 8px;
    flex: 1;
}

.shop-selection-bar .action-btn {
    padding: 6px 10px;
    font-size: 0.842em;
}

/* The band that opens a category, on either side of the counter. It is a press
   of its own - it takes the whole category onto the counter - so it carries a
   box saying how much of it is already there. */
.shop-cat-header {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 10px;
    margin: 10px 0 6px;
    border-radius: 4px;
    cursor: pointer;
    background: transparent;
    border: none;
    transition: all 0.15s ease;
}

.shop-cat-header:first-child {
    margin-top: 0;
}

.shop-cat-header:hover {
    background: transparent;
}

.shop-cat-header.some,
.shop-cat-header.all {
    background: transparent;
}

.shop-cat-box {
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--text-secondary-active);
    border-radius: 3px;
    font-size: 0.842em;
    font-weight: bold;
    line-height: 1;
    color: var(--text-cost-ok);
}

.shop-cat-name {
    flex: 1;
    min-width: 0;
    font-size: 1.024em;
    font-weight: bold;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--text-secondary-active);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.shop-cat-meta {
    font-size: 0.842em;
    color: var(--text-inverse);
    white-space: nowrap;
}

/* The dossier scrolls; the BUY/SELL button under it is a sibling and never
   does, so a long item sheet can no longer push the one press off the page. */
.detail-scroll {
    background: var(--bg-secondary-hover);
    border: 1px solid var(--border-secondary-hover-translucent-15);
    border-radius: 6px;
    box-shadow: inset 0 0 20px var(--border-secondary-hover-translucent-15);
    padding: 20px;
    flex: 1 1 auto;
    min-height: 0;
    box-sizing: border-box;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

/* The shop's own sheet carries no plate: the panel is the page. Other menus
   share .detail-scroll and keep theirs. */
#shop-container .detail-scroll {
    background: transparent;
    border: none;
    box-shadow: none;
    padding: 20px 0;
}

#detail-viewport > #right-action-btn {
    flex: none;
    flex-shrink: 0;
}

.detail-header {
    display: flex;
    align-items: center;
    gap: 14px;
    border-bottom: none;
    padding-bottom: 12px;
    margin-bottom: 16px;
}

.detail-name {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-title);
    color: var(--text-detail-heading);
    font-weight: bold;
}

.detail-spec-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
    margin-bottom: 16px;
}

.detail-spec-badge {
    background: transparent;
    border: none;
    padding: 6px 10px;
    font-size: var(--fs-detail-body);
    display: flex;
    justify-content: space-between;
}

.badge-lbl {
    color: var(--text-inverse);
    font-size: 0.842em;
}

.badge-val {
    font-weight: bold;
    color: var(--text-disabled);
}

/* The counter's quote for the line under the cursor: what one copy costs (or
   fetches) today, and how far the day's OIL/SOUL index moved it off the
   sticker. It is the price the till uses, so it is set as the loudest number
   on the panel. */
.detail-price-box {
    border: none;
    border-radius: 0;
    padding: 10px 0;
    margin-bottom: 14px;
    background: transparent;
}

.detail-price-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    font-size: var(--fs-detail-body);
    margin-top: 6px;
}

.detail-price-row:first-child {
    margin-top: 0;
}

.detail-price-lbl {
    color: var(--text-detail-label);
    font-size: var(--fs-detail-heading);
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.detail-price-main .detail-price-val {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-title);
    font-weight: bold;
}

.detail-price-val.cost {
    color: var(--text-cost-bad);
}

.detail-price-val.gain {
    color: var(--text-cost-ok);
}

/* The sticker the market moved away from: present for the comparison, never
   competing with the price that is actually charged. */
.detail-price-sub {
    font-size: var(--fs-detail-heading);
    color: var(--text-detail-label);
}

.market-tag {
    font-family: var(--font-ui);
    font-weight: bold;
    font-size: 0.88em;
    padding: 2px 8px;
    white-space: nowrap;
    border: none;
    padding-left: 0;
    padding-right: 0;
}

/* Green when the day's index is in the player's favour and red when it is not
   - which way that runs depends on the side of the counter, so a squeeze on
   SOUL reads green on the sell page and red on the buy page. */
.market-tag.good {
    color: var(--text-cost-ok);
    background: transparent;
}

.market-tag.bad {
    color: var(--text-cost-bad);
    background: transparent;
}

/* The item's own prose: the longest, smallest-set text on the page, so it is
   inked at full body contrast rather than the muted tone it used to borrow. */
.detail-desc {
    color: var(--text-success-active);
    font-size: var(--fs-detail-prose);
    line-height: 1.6;
    background: transparent;
    border-radius: 0;
    padding: 10px 0;
    margin-bottom: 10px;
    border: none;
    max-width: 68ch;
}

.detail-lore {
    color: var(--text-success-active);
    font-style: normal;
    font-size: var(--fs-detail-prose);
    max-width: 68ch;
    line-height: 1.55;
    padding: 0 4px;
    margin-bottom: 16px;
}

/* A cure-all carries two dozen effects, so they wrap as chips instead of
   running down the page one line each. */
.detail-effect-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.detail-effect-chip {
    font-size: var(--fs-detail-heading);
    line-height: 1.2;
    padding: 3px 8px;
    background: transparent;
    border: none;
    color: var(--text-success-active);
    white-space: nowrap;
}

.gauges-section {
    margin-bottom: 16px;
}

.gauge-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
    font-size: 0.892em;
}

.modal-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--shadow-glow-active-translucent-40);
    backdrop-filter: blur(1.5px);
    z-index: 1000;
    display: flex;
    justify-content: center;
    align-items: center;
    animation: fade-in 0.15s ease-out;
}

.quantity-box {
    width: 380px;
    padding: 20px;
    text-align: center;
}

.quantity-title {
    font-family: var(--font-ui);
    font-size: 1.238em;
    color: var(--text-primary-hover);
    margin-bottom: 14px;
}

.quantity-slider-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 16px 0;
    gap: 12px;
}

.qty-arrow {
    width: 36px;
    height: 36px;
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 1.238em;
    cursor: pointer;
    transition: all 0.15s ease;
}

.qty-arrow:hover {
    background: var(--chip-active-bg);
    box-shadow: 0 0 8px var(--shadow-gold-amber-50);
}

.qty-val-display {
    font-size: 1.76em;
    font-weight: bold;
    color: var(--text-muted-hover);
}

.quantity-actions {
    display: flex;
    gap: 12px;
    margin-top: 20px;
}

.action-btn.confirm {
    background: var(--text-secondary-active);
    color: var(--bg-secondary-hover);
    border: 1px solid var(--text-primary-hover);
}

.action-btn.confirm:hover,
.action-btn.confirm.selected {
    background: var(--text-primary-hover);
    color: var(--bg-secondary-hover);
    box-shadow: 0 3px 10px var(--shadow-gold-amber-50);
    filter: brightness(1.06);
}

.action-btn.cancel {
    background: var(--bg-primary-hover-translucent-35);
    color: var(--text-success-active);
    border: 1px solid var(--border-muted-focus);
}

.action-btn.cancel:hover,
.action-btn.cancel.selected {
    background: var(--bg-tertiary-focus-translucent-45);
    border-color: var(--text-primary-hover);
}

/* Extracted from AnimatedTarotReading.js */
.tarot-altar {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    height: 480px;
    position: relative;
    margin-top: 15px;
    box-sizing: border-box;
}

.tarot-card-container {
    perspective: 1000px;
    width: 150px;
    height: 230px;
    cursor: pointer;
    position: relative;
    transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), z-index 0.1s;
    margin-bottom: -110px;
    /* Overlap beautifully inside single column */
}

.tarot-card-container:hover {
    transform: scale(1.06) translateY(-10px);
}

.tarot-card-container.selected {
    transform: scale(1.08) translateY(-14px);
    filter: drop-shadow(0 0 15px var(--border-success));
}

.tarot-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    text-align: center;
    transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    transform-style: preserve-3d;
}

.tarot-card-container.flipped .tarot-card-inner {
    transform: rotateY(180deg);
}

.tarot-card-front,
.tarot-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: 8px;
    box-shadow: 0 6px 12px var(--shadow-primary-hover-translucent-5);
    box-sizing: border-box;
}

.tarot-card-back {
    background: var(--gradient-5);
    border: 3px double var(--border-success);
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: inset 0 0 15px var(--shadow-text-glow-hover-translucent-35);
}

.tarot-card-back-pattern {
    width: 82%;
    height: 85%;
    border: none;
    border-radius: 4px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: var(--text-text-alt-4);
}

.tarot-card-front {
    transform: rotateY(180deg);
    border: 2px solid var(--text-primary-hover);
    background: var(--bg-secondary-hover);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.tarot-card-front img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.tarot-card-container.reversed .tarot-card-front img {
    transform: rotate(180deg);
}

.prophecy-pane {
    background: var(--border-primary-hover-translucent-15);
    border: none;
    border-radius: 4px;
    padding: 12px 18px;
    margin-top: 15px;
    min-height: 110px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: center;
    animation: fadeIn 0.4s ease;
}

.choices-scroll {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 10px;
}

.choice-card {
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-primary-hover-translucent-15);
    padding: 12px 16px;
    cursor: pointer;
    font-family: var(--font-ui);
    font-size: 0.928em;
    color: var(--text-success-active);
    transition: all 0.2s ease;
    box-sizing: border-box;
    text-align: left;
}

.choice-card:hover,
.choice-card.selected {
    background: var(--border-primary-hover-translucent-15);
    border-color: var(--text-primary-hover);
    box-shadow: 0 3px 8px var(--shadow-shadow-alt-2-hover-translucent-8);
    color: var(--text-primary-hover);
}

.choice-card.selected::before {
    /* Crystal Ball (IconSet 307) instead of an emoji marker. */
    content: '';
    display: inline-block;
    vertical-align: middle;
    margin-right: 8px;
    width: 18px;
    height: 18px;
    background-image: url('../img/system/IconSet.png');
    background-size: 288px auto;
    background-position: -54px -342px;
    image-rendering: pixelated;
}

.choice-card.choice-correct {
    border-color: var(--text-text-alt-11) !important;
    background: var(--bg-bg-alt-8-translucent-15) !important;
    color: var(--text-text-alt-11) !important;
    box-shadow: 0 0 10px var(--bg-bg-alt-8-translucent-15) !important;
}

.choice-card.choice-wrong {
    border-color: var(--text-text-alt-5-hover) !important;
    background: var(--shadow-shadow-alt-1-hover-translucent-25) !important;
    color: var(--text-text-alt-5-hover) !important;
    box-shadow: 0 0 10px var(--shadow-shadow-alt-1-hover-translucent-25) !important;
}

.alchemical-gauge-outer {
    width: 100%;
    height: 16px;
    background: var(--text-success-active);
    border: 2px solid var(--text-info);
    border-radius: 8px;
    box-shadow: inset 0 2px 4px var(--shadow-glow-active-translucent-40);
    overflow: hidden;
    position: relative;
    margin-top: 5px;
}

.alchemical-gauge-fill {
    height: 100%;
    width: 0%;
    transition: width 0.5s cubic-bezier(0.25, 1, 0.5, 1);
    background: var(--gradient-21);
    box-shadow: 0 0 10px var(--shadow-shadow-alt-12-translucent-50);
    position: relative;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(5px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}




.tab-icon {
    font-size: 1.552rem;
}

.option-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--sp-3) var(--sp-4);
    background: transparent;
    border: 1px solid transparent;
    cursor: pointer;
    transition: border-color 0.12s ease;
    box-sizing: border-box;
}

/* Hover, focus and selection are the one appearance: a gold hairline and
   nothing behind it. A page of settings is a list, not eight filled boxes. */
.option-row:hover,
.option-row.active {
    background: transparent;
    border-color: var(--text-primary-hover);
}

/* The setting is the thing being read; its value is the answer beside it. The
   label used to be inked muted and the value bright gold, which put the row's
   weight on the answer and made a page of settings read as a page of values. */
.option-name {
    font-family: var(--font-ui);
    font-weight: 600;
    color: var(--text-success-active);
    font-size: var(--fs-body);
}

.option-row.active .option-name {
    color: var(--text-primary-hover);
}

.option-status-toggle {
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    font-weight: bold;
    letter-spacing: 0.5px;
    padding: 2px var(--sp-3);
    background: transparent;
}

/* One of these sits on every row: the ink alone says on or off, so neither
   state carries a plate. */
.option-status-toggle.enabled {
    color: var(--text-primary-hover);
}

.option-status-toggle.disabled {
    color: var(--text-text-alt-4);
}

.option-slider-bar {
    width: 100%;
    height: 10px;
    background: var(--bg-card-translucent-5);
    border-radius: 4px;
    overflow: hidden;
    position: relative;
    cursor: pointer;
    margin-top: 4px;
}

.option-slider-fill {
    height: 100%;
    background: var(--gradient-25);
    border-radius: 4px;
    transition: width 0.05s linear;
}

.pockets-scroll::-webkit-scrollbar {
    width: 6px;
}

.pockets-scroll::-webkit-scrollbar-track {
    background: var(--bg-card-translucent-5);
    border-radius: 4px;
}

.pockets-scroll::-webkit-scrollbar-thumb {
    background: var(--border-primary-hover-translucent-15);
    border-radius: 4px;
}

.pockets-scroll::-webkit-scrollbar-thumb:hover {
    background: var(--shadow-shadow-alt-4-hover-translucent-60);
}

.calligraphy-btn {
    font-family: var(--font-ui);
    background: var(--bg-secondary-hover);
    border: 2px solid var(--text-primary-hover);
    color: var(--text-primary-hover);
    border-radius: 4px;
    font-size: 1.095em;
    font-weight: bold;
    cursor: pointer;
    box-shadow: 0 2px 5px var(--shadow-primary-hover-translucent-5);
    transition: all 0.2s ease;
    box-sizing: border-box;
}

.calligraphy-btn:hover {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    box-shadow: 0 4px 10px var(--border-primary-hover-translucent-15);
}

/* GameOptions spec rework, parchment options menu (scoped to #menu-container) */
#menu-container .backpack-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.opt-row-icon {
    image-rendering: pixelated;
    flex: 0 0 auto;
}

/* Inspect panel: settings preview illustration */
#menu-container .opt-inspect-img-wrap {
    width: 100%;
    margin: 0 0 var(--sp-4) 0;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    background: transparent;
    overflow: hidden;
    box-sizing: border-box;
}

#menu-container .opt-inspect-img {
    display: block;
    width: 100%;
    max-height: 340px;
    object-fit: contain;
}

#options-list.pockets-scroll {
    flex: 1;
    overflow-y: auto;
    padding-right: var(--sp-3);
    display: flex;
    flex-direction: column;
    gap: var(--sp-3);
}

/* The settings list reads a step larger than the rest of the spread: a row here
   is one sentence and one answer, never a dense grid, so it can afford the room
   and it is the screen players read at arm's length from a couch. Sizes stay on
   the six type tokens, one step up each. */
#options-list .option-row {
    padding: var(--sp-4) var(--sp-5);
}

#options-list .option-name {
    font-size: var(--fs-heading);
}

#options-list .option-status-toggle,
#options-list .option-value,
#options-list .option-select-val {
    font-size: var(--fs-body);
}

#options-list .option-select-val {
    min-width: 110px;
}

#options-list .option-slider-bar {
    height: 12px;
}

.option-row--slider {
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
}

.option-row-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
}

.option-label {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.option-value {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    font-weight: bold;
    color: var(--text-success-active);
}

.option-select {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--sp-3);
    background: transparent;
    color: var(--text-success-active);
}

.option-select-val {
    min-width: 90px;
    text-align: center;
}

.option-select .arrow-btn {
    cursor: pointer;
    padding: 2px 8px;
    user-select: none;
}

.option-select .arrow-btn:hover {
    color: var(--text-primary-hover);
}

/* ==========================================================================
   Preferences / Settings menu (GameOptions.js), lean two-page rework
   Left page: the option rows carried a faint card fill; drop it so rows sit
   flat on the page (border still marks the focused/hovered row). Right page:
   `.inspect-lore` is a shared, flex-grow "lore plate" reused by many other
   menus; here it just held a short bullet list and stretched into a large,
   mostly-empty translucent box. Settings has no prose to frame, so strip the
   card chrome entirely and let the bullets/spec rows sit directly on the page.
   ========================================================================== */
/* The right page: a value that has to be pointed out (a restart is needed, a
   warning, the state a select is actually in) is gold; nothing else is. */
#options-inspect .opt-note,
#options-inspect .opt-state-on,
#options-inspect .opt-inspect-kind {
    color: var(--border-focus-hover);
}

#options-inspect .opt-note {
    font-weight: bold;
}

#options-categories .backpack-tab {
    background: transparent;
    font-size: var(--fs-body);
    padding: var(--sp-3) var(--sp-4);
}

/* The flat-tab rule above outranks `.backpack-tab.active` (id + class beats two
   classes), so the active tab lost its gold fill but kept the dark-on-gold text
   colour, leaving the current tab's label unreadable. Restate the focused and
   active looks at the same specificity: gold text on a faint fill, marked by the
   border rather than by inverting the colours. */
/* The flat-tab rule above outranks `.backpack-tab.active` (id + class beats two
   classes), so the active look has to be restated at the same specificity. It
   is the same gold hairline every other selected thing wears, with the label
   inked gold rather than the tab inverted. */
#options-categories .backpack-tab.active,
#options-categories .backpack-tab.selected {
    background: transparent;
    color: var(--text-primary-hover) !important;
    border-color: var(--text-primary-hover);
}

/* Keyboard focus sits on the tab strip and the option list separately, so the
   focused tab keeps a gold underline to read apart from the merely active one
   once the cursor has moved down into the list. */
#options-categories .backpack-tab.selected {
    box-shadow: inset 0 -2px 0 var(--text-primary-hover);
}

#options-inspect .inspect-lore {
    background: transparent;
    border: none;
    box-shadow: none;
    flex-grow: 0;
}

/* Preferences spread: the option list needs less room than the inspect page,
   which carries the illustration, so the left sheet is the narrower of the two.
   The pair still adds up to the whole spread, keeping the binding centred. */
.book-spread.options-spread .left-page {
    width: 42%;
}

.book-spread.options-spread .right-page {
    width: 58%;
}

/* Reset to defaults is the one header-bar button that is NOT the way out, so it
   sits opposite Back on the right of the same bar instead of under it. */
#opt-reset-btn {
    left: auto;
    right: 0;
}

/* Folded spread: an option with no illustration and no explanation gets no right
   page at all, so the list takes the whole sheet instead of sitting beside an
   empty half. The binding spine goes with it, there being nothing to bind. */
.book-spread.options-solo .right-page {
    display: none;
}

.book-spread.options-solo::before {
    display: none;
}

.book-spread.options-solo .left-page {
    width: 100%;
}

/* Widening the page does not widen the rows: a label at one edge and its answer
   at the other, a screen apart, is not a row anyone reads. The column keeps the
   measure it had on the spread and centres in the sheet. */
.book-spread.options-solo .page-header-bar,
.book-spread.options-solo #options-categories,
.book-spread.options-solo #options-list {
    max-width: 980px;
    width: 100%;
    margin-left: auto;
    margin-right: auto;
}

/* An illustration that turns out to be missing or a blank stub takes its frame
   with it (the <img> handlers add this rather than writing an inline style). */
#menu-container .opt-inspect-img-wrap.is-hidden {
    display: none;
}

/* Extracted from PlantGrowthSystem.js */
#plant-sprite-canvas,
#plant-preview-canvas {
