/* Extracted from SaveSystem.js */
#save-menu-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: auto;
    font-family: var(--font-ui);
    background: var(--shadow-glow-active-translucent-40);
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
}

.save-book-spread::before {
    content: '';
    position: absolute;
    top: 0;
    left: 38%;
    width: 30px;
    height: 100%;
    background: var(--gradient-28);
    pointer-events: none;
    z-index: 10;
    transform: translateX(-50%);
}

.save-left-page {
    position: relative;
    width: 38%;
    height: 100%;
    padding: 25px 30px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    z-index: 2;
}

.save-right-page {
    position: relative;
    width: 62%;
    height: 100%;
    padding: 30px 40px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    z-index: 2;
}

.save-title {
    font-family: var(--font-ui);
    font-size: 1.98rem;
    color: var(--text-primary-hover);
    text-align: center;
    border-bottom: none;
    padding-bottom: 8px;
    margin-top: 0;
    margin-bottom: 20px;
    width: 100%;
    letter-spacing: 1px;
}

.save-list {
    flex: 1 1 auto;
    /* The hairline under each slot is the separator now, so the list needs no
       gap of its own. */
    /* Allow the flex item to shrink below its content size so it scrolls
       inside the page instead of overflowing it */
    min-height: 0;
    overflow-y: auto;
    padding-right: 8px;
    display: flex;
    flex-direction: column;
    gap: 0;
}

.save-list::-webkit-scrollbar {
    width: 6px;
}

.save-list::-webkit-scrollbar-track {
    background: var(--border-primary-hover-translucent-15);
    border-radius: 3px;
}

.save-list::-webkit-scrollbar-thumb {
    background: var(--border-focus-hover);
    border-radius: 3px;
}

/* A slot reads as one line of the ledger: the identity of the party on the
   left, the party itself laid out beside it. Header and roster used to be
   stacked full width, which centred a one-member party half a page away from
   the slot it names. */
.save-item {
    display: grid;
    grid-template-columns: minmax(150px, 30%) 1fr;
    align-items: center;
    column-gap: 18px;
    flex-shrink: 0;
    padding: 8px 10px 8px 12px;
    background: none;
    border: none;
    border-left: 2px solid transparent;
    border-bottom: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 0;
    cursor: pointer;
    transition: background 0.2s ease, border-color 0.2s ease;
    user-select: none;
}

/* Slot name over its playtime: the pair is one block, not two ends of a bar. */
.save-item-header {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 1px;
    min-width: 0;
    width: 100%;
}

.save-item:hover,
.save-item.selected {
    background: var(--border-primary-hover-translucent-15);
    border-left-color: var(--text-primary-hover);
    transform: none;
}

.save-item.selected .save-id {
    color: var(--text-primary-hover);
    font-weight: bold;
}

/* Other parties of the world while saving: browsable, but not writable. */
.save-item.locked {
    opacity: 0.62;
}

.save-item.locked .save-summary {
    font-style: normal;
}

.save-id {
    font-family: var(--font-ui);
    font-size: 1.1rem;
    line-height: 1.25;
    color: var(--border-focus-hover);
    transition: color 0.2s ease;
}

.save-summary {
    font-size: 0.85rem;
    color: var(--text-success-active);
    font-style: normal;
    opacity: 0.85;
}

.save-details-card {
    flex-grow: 1;
    background: none;
    border: none;
    border-radius: 0;
    padding: 10px 0 0 0;
    display: flex;
    flex-direction: column;
    gap: 15px;
    box-sizing: border-box;
    overflow-y: auto;
}

.detail-title {
    font-family: var(--font-ui);
    font-size: 1.495rem;
    color: var(--text-primary-hover);
    margin: 0;
    border-bottom: none;
    padding-bottom: 5px;
}

.detail-row {
    display: flex;
    justify-content: space-between;
    font-size: 1.08rem;
    color: var(--text-success-active);
    margin-bottom: 4px;
}

.detail-label {
    font-weight: bold;
    color: var(--border-focus-hover);
}

.party-characters {
    display: flex;
    gap: 6px;
    justify-content: flex-start;
    background: none;
    border: none;
    padding: 2px 0 0 0;
    margin-top: 0;
}

.char-sprite-canvas {
    background: none;
    border: none;
    border-radius: 0;
    image-rendering: pixelated;
    /* The canvas resolution is the sprite's native frame, which is rarely
       square: contain keeps its proportions inside the box instead of
       squashing it flat and stretching it sideways. */
    object-fit: contain;
    width: 36px;
    height: 42px;
    margin: 0;
}

/* Detailed party roster inside each save slot */
/* The party of a slot reads as ONE row of members, however many there are:
   each is a narrow column of sprite, name, class and gauges. */
.party-members-list {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 14px;
    margin-top: 0;
    min-width: 0;
    width: 100%;
}

/* Members sit at the head of their column and keep a fixed width, so a party
   of one and a party of four both start under the same rule. */
.save-member {
    flex: 0 1 118px;
    max-width: 118px;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 2px;
    background: none;
    border: none;
    padding: 0;
}

.save-member .char-sprite-canvas {
    flex-shrink: 0;
    width: 64px;
    height: 76px;
    margin: 0;
}

.save-member-body {
    width: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1px;
}

.save-member-head {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    width: 100%;
    min-width: 0;
}

.save-member-name {
    font-family: var(--font-ui);
    font-size: 0.94rem;
    max-width: 100%;
    font-weight: bold;
    color: var(--text-primary-hover);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.save-member-meta {
    font-size: 0.76rem;
    font-style: normal;
    color: var(--text-success-active);
    white-space: nowrap;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* World Map Segment & Party Pin in Save/Load Menu */
.save-map-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 8px 0;
}

.save-map-meta-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    font-size: 0.95rem;
    color: var(--text-success-active);
}

.save-map-meta-item {
    display: flex;
    align-items: center;
    gap: 6px;
}

.save-coords-badge,
.save-sector-badge {
    font-variant-numeric: tabular-nums;
    color: var(--text-primary-hover);
    font-weight: bold;
}

.save-map-segment-frame {
    position: relative;
    width: 100%;
    max-height: 420px;
    aspect-ratio: 4 / 3;
    border: 1px solid var(--border-accent-hover-translucent-5);
    border-radius: 2px;
    overflow: hidden;
    background: none;
}

.save-map-segment-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    filter: sepia(0.12) contrast(1.02);
}

.save-map-pin {
    position: absolute;
    /* Where on the chart the party is standing: the only thing about this pin
       the menu knows and the sheet cannot. */
    left: var(--ui-at-x, 0);
    top: var(--ui-at-y, 0);
    transform: translate(-50%, -50%);
    z-index: 5;
    pointer-events: auto;
    display: flex;
    flex-direction: column;
