}

.save-pin-pulse {
    position: absolute;
    top: 6px;
    left: 50%;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: rgba(229, 57, 53, 0.4);
    transform: translate(-50%, -50%);
    animation: dndPulse 1.8s infinite ease-in-out;
    pointer-events: none;
}

.save-pin-dot {
    width: 12px;
    height: 12px;
    background: #e53935;
    border: 2px solid #ffffff;
    border-radius: 50%;
    box-shadow: 0 0 6px rgba(0, 0, 0, 0.8);
    flex-shrink: 0;
}

.save-pin-dot.adjacent {
    background: #1e88e5;
