}

.save-pin-label.adjacent {
    color: var(--text-primary-hover);
    font-size: 0.72rem;
    border-color: var(--text-primary-hover);
    background: rgba(10, 16, 24, 0.82);
}

.save-detail-rows {
    margin-top: 10px;
