    flex-direction: column;
    gap: 8px;
}

.save-party-title {
    margin: 15px 0 5px 0;
    font-family: var(--font-ui);
    color: var(--text-primary-hover);
    border-bottom: none;
    padding-bottom: 3px;
}

.save-empty-card {
    display: flex;
    align-items: center;
    justify-content: center;
}

.save-empty-text {
    font-family: var(--font-ui);
    font-size: 0.964em;
    color: var(--text-primary-hover);
    font-style: normal;
    background: none;
    border: none;
    padding: 25px;
    border-radius: 4px;
    line-height: 1.6;
    text-align: center;
}

.save-title-left {
    border: none;
    margin: 0;
    padding: 0;
    text-align: center;
}

.save-title-right {
    margin-bottom: 20px;
}

.actions-bar {
    display: flex;
    gap: 15px;
    margin-top: auto;
    justify-content: center;
}

/* Outlined by default. Every action button used to be stamped as a solid gold
   plate, so a row of four of them was four gold plates and nothing in the row
   said which one the page wanted. The fill is kept for .confirm below, which is
   the one button on a page that has earned it. */
.action-btn {
    font-family: var(--font-ui);
    font-size: 1.08rem;
    background: transparent;
    border: 1.5px solid var(--border-gold-amber-30);
    color: var(--text-primary-hover);
    padding: 8px 16px;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
    flex: 0 1 auto;
    font-weight: bold;
    text-align: center;
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    user-select: none;
}

/* Hovered, focused and selected are the same stamp. They were three rules in
   three places, two of which the cascade never reached, so a stamp picked out
   with the pad read weaker than the same stamp under the mouse. */
.action-btn:hover,
.action-btn.selected:not(.disabled),
.action-btn:focus-visible {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    border-color: var(--chip-active-fg);
    box-shadow: 0 0 6px var(--shadow-shadow-alt-4-hover-translucent-60);
}

.action-btn.disabled {
    opacity: 0.35;
    pointer-events: none;
    cursor: not-allowed;
    border-color: var(--text-text-alt-8);
    color: var(--text-text-alt-8);
    background: var(--bg-bg-alt-3);
}

/* Controller / keyboard focus ring for the save-load screen's Save / Load /
   Delete buttons (UIFileInputManager toggles .focused on them). It is the same
   swap hover paints, so Save does not sit in a ring of its own while its two
   neighbours stay flat. */
#save-menu-container .inspect-btn.focused {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    box-shadow: 0 4px 8px var(--shadow-primary-hover-translucent-5);
}

/* The Back stamp is vertically centred in its header bar by the shared rule, so
   its focus ring keeps that transform instead of replacing it. */
#save-menu-container .back-button.focused {
    outline: 2px solid var(--text-primary-hover);
    outline-offset: 2px;
    box-shadow: 0 0 12px var(--shadow-gold-amber-50);
}

/* ==========================================================================
   Extracted Inline Styles from CharacterCreationCreature.js
   ========================================================================== */

.cc-page-centered {
    align-items: center;
    justify-content: center;
}

.cc-text-desc.cc-spaced {
    margin-top: 16px;
    font-size: 1.288rem;
}

.cc-tube-container {
    margin-top: 24px;
    position: relative;
    width: 140px;
    height: 220px;
    border: 4px solid var(--text-disabled);
    border-radius: 70px 70px 10px 10px;
    background: var(--bg-bg-alt-25-translucent-8);
    overflow: hidden;
    box-shadow: inset 0 0 20px var(--shadow-primary-hover-translucent-5);
}

.cc-tube-fluid {
    position: absolute;
    bottom: 0;
    width: 100%;
    height: 60%;
    background: var(--gradient-8);
    animation: cc-bubble-rise 3s infinite ease-in-out;
}

.cc-tube-label {
    position: absolute;
    top: 20px;
    left: 50%;
    transform: translateX(-50%);
    font-family: monospace;
    font-size: 1.02rem;
    color: var(--text-disabled);
}

.cc-select-grid.cc-spaced {
    grid-template-columns: 1fr;
    gap: 16px;
    margin-top: 24px;
}

@keyframes cc-bubble-rise {
    0% {
        transform: translateY(5px);
        opacity: 0.8;
    }

    50% {
        transform: translateY(-5px);
        opacity: 1;
    }

    100% {
        transform: translateY(5px);
        opacity: 0.8;
    }
}

/* CharacterCreation, settings panel: single-column .option-row list that
   mirrors the parchment options menu left page (rows styled by .option-row /
   .option-select in the GameOptions block). */
.cc-settings-list { display: flex; flex-direction: column; gap: 10px; flex: 1; align-content: start; min-height: 0; }
.cc-settings-img-stack { display: flex; flex-direction: column; gap: 10px; width: 100%; align-items: center; margin-top: 6px; }
.cc-settings-img-entry { display: flex; flex-direction: column; align-items: center; width: 100%; }
.cc-settings-preview-img { width: 100%; max-width: 460px; height: auto; border-radius: 4px; border: 1px solid var(--border-settings-preview); display: block; }
.cc-settings-img-caption { font-size: 1.334rem; color: var(--text-card-dark); text-align: center; margin-top: 8px; font-style: normal; line-height: 1.35; max-width: 460px; }
/* What the highlighted setting actually does, on the preview page. It is the one
   piece of prose on a page that is otherwise a title, a picture and a caption,
   and it was set smaller than the caption under the picture beside it , read
   from creation distance, on a page with room to spare, it was the smallest text
   on screen for the thing the player is being asked to decide. Sized between the
   subheader above it and the caption below, with a measure that keeps the lines
   short enough to scan rather than running the full width of the page. */
/* The settings page belongs to the whole party, so it is given the board on its
   own: the character sidebar is put away and the spread runs the full width. */
.cc-unified-layout.cc-settings-mode .cc-sidebar-slot {
    display: none;
}

.cc-unified-layout.cc-settings-mode .cc-content-pane {
    width: 100%;
}

.cc-settings-detail {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    background: transparent;
    border: none;
    box-shadow: none;
    padding: 12px;
}

.cc-settings-detail-title {
    text-align: center;
    color: var(--text-primary-hover);
    font-size: 1.45rem;
}

/* A glyph standing in for a setting that has no picture. */
.cc-settings-glyph {
    text-align: center;
    font-size: 4.081rem;
    margin: 16px 0;
    color: var(--text-primary-hover);
}

.cc-settings-value {
    text-align: center;
    font-size: 1.585rem;
    font-weight: bold;
    margin: 8px 0;
    color: var(--text-card-dark);
}

.cc-settings-desc {
    font-size: 1.18rem;
    line-height: 1.55;
    color: var(--text-card-dark);
    text-align: center;
    max-width: 26em;
    margin: 0 auto 10px;
}
.cc-settings-hint {
    font-size: 1.104rem; color: var(--text-card-medium); text-align: center;
    margin-top: 8px; font-style: normal; line-height: 1.4;
}

/* The rows themselves are the options menu's (.option-row et al, GameOptions
   block). Creation is read from further back than the pause menu is, so the
   labels and values are scaled up here rather than in the shared rules, which
   the in-game options screen keeps at its own size. */
#character-creation-container .option-row { padding: 14px 18px; }
#character-creation-container .option-name { font-size: 1.288rem; }
#character-creation-container .option-status-toggle { font-size: 1.15rem; }
#character-creation-container .option-select-val { min-width: 116px; }
#character-creation-container .option-select .arrow-btn { padding: 2px 10px; }

/* ==========================================================================
   Fullscreen Font Scaling and UI Overrides
   ========================================================================== */

/* The workshop's title bar, on the shared title token like every other page.
   The em-chain overrides this screen used to carry (fourteen rules, every one
   of them !important, several of them for markup it no longer draws) are gone
   with the markup: the six type tokens settle it. */
#blacksmith-container .title {
    font-family: var(--font-ui);
    font-size: var(--fs-title);
    margin: 0;
    letter-spacing: 1px;
}

#blacksmith-container .category-name { font-size: var(--fs-body); }
#blacksmith-container .category-count { font-size: var(--fs-chip); }
#blacksmith-container .blueprint-name { font-size: var(--fs-body); }
#blacksmith-container .category-trade { font-size: var(--fs-caption); }
#blacksmith-container .forge-mat-state,
#blacksmith-container .forge-tier-need,
#blacksmith-container .forge-quality-mark { font-size: var(--fs-chip); }

/* ==========================================================================
   Eris: the court and the date
   (Economy/ErisTrial.js, Economy/ErisDateSystem.js)

   One kit, two screens. The hearing, the brief, the reverse hearing and the
   date are the same spread with a different sheet on the right page, so
   everything they share is written once here. The label/value rows, the chips,
   the headings and the action strips are the shared kit's own classes
   (docs/task/ui_fixing.md); only the transcript, the meter, the odds bars and
   the verdict stamp are Eris's, because nothing else in the game draws them.

   No option carries a plate or a frame: a choice is marked by a gold hairline
   and nothing else. Every size is one of the six type tokens and every colour
   is a theme token.
   ========================================================================== */

/* A page that stacks from the top rather than pushing its parts to the two
   corners: a transcript over its choices, a sheet over its meters. Replaces
   the style="justify-content:flex-start" the four Eris spreads passed in. */
.book-spread .page-top {
    justify-content: flex-start;
}

/* An IconSet glyph inline in a sentence or a chip. The frame is a computed
   offset, so it arrives as custom properties rather than as paint. */
.eris-icon {
    display: inline-block;
    vertical-align: middle;
    flex-shrink: 0;
    width: var(--icon-size, 20px);
    height: var(--icon-size, 20px);
    background-image: url('../img/system/IconSet.png');
    background-repeat: no-repeat;
    background-size: calc(var(--icon-size, 20px) * 16) auto;
    background-position: var(--icon-x, 0px) var(--icon-y, 0px);
    image-rendering: pixelated;
}

/* --------------------------------------------------------------------------
   The transcript (left page)
   -------------------------------------------------------------------------- */

/* The log owns the scroll, so the title above it and the choices below it
   never leave the page however long the hearing runs. */
.eris-dialogue-log {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: var(--sp-3);
    padding-right: var(--sp-2);
    margin-bottom: var(--sp-4);
}

.eris-dialogue-log::-webkit-scrollbar { width: 5px; }
.eris-dialogue-log::-webkit-scrollbar-track { background: var(--shadow-primary-hover-translucent-5); }
.eris-dialogue-log::-webkit-scrollbar-thumb { background: var(--scroll-thumb-hover-translucent-60); border-radius: 3px; }

/* One line of the hearing: plain text on the page, held to a measure, with a
   hairline down the speaker's side instead of a bubble. */
.eris-dialogue-entry {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    line-height: 1.55;
    max-width: 68ch;
    padding: var(--sp-1) var(--sp-4);
    background: transparent;
    animation: erisEntryFadeIn 0.3s ease both;
}

/* The other voices sit inset from the page edge rather than hard against it,
   so the transcript reads as one column of talk instead of two far apart. */
.eris-dialogue-entry.eris {
    align-self: flex-start;
    margin-left: 18%;
    color: var(--text-primary-hover);
    border-left: 1px solid var(--border-focus-hover);
}

.eris-dialogue-entry.player {
    align-self: flex-end;
    color: var(--text-success-active);
    border-right: 1px solid var(--border-success);
    text-align: right;
}

/* Stage direction: the room, not a voice in it. */
.eris-dialogue-entry.narrator {
    align-self: center;
    margin-left: 12%;
    color: var(--text-card-medium);
    text-align: center;
    padding: 2px var(--sp-4);
}

.eris-dialogue-entry .eris-speaker {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    letter-spacing: 0.5px;
    display: block;
    margin-bottom: 2px;
    color: var(--text-text-alt-4);
}

@keyframes erisEntryFadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* The mark under the newest line saying the transcript is waiting on the
   reader. It is a caret, not a key legend: the game names no keys. */
.eris-continue-hint {
    flex: 0 0 auto;
    align-self: flex-end;
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    line-height: 1;
    color: var(--text-primary-hover);
    opacity: 0.28;
    padding: 0 var(--sp-1) 2px 0;
}

.eris-continue-hint.ready {
    opacity: 0.65;
    /* The transcript itself advances on a click, so the armed caret is a
       button in everything but name. */
    cursor: pointer;
    animation: erisContinueBlink 1.1s ease-in-out infinite;
}

@keyframes erisContinueBlink {
    0%, 100% { opacity: 0.28; }
    50%      { opacity: 0.85; }
}

/* The court is running itself: a steadier, slower pulse than the waiting one,
   so the page reads as moving rather than as waiting to be told to. */
.eris-continue-hint.auto {
    animation: erisAutoPulse 1.6s ease-in-out infinite;
}

@keyframes erisAutoPulse {
    0%, 100% { opacity: 0.45; }
    50%      { opacity: 0.9; }
}

/* --------------------------------------------------------------------------
   The choices
   -------------------------------------------------------------------------- */

/* Answers belong to the player, so they stack on the player's side of the
   page, under the player's own lines. */
.eris-choices-panel {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: var(--sp-2);
    padding-top: var(--sp-3);
    flex: 0 0 auto;
}

.eris-choice-btn {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-success-active);
    background: transparent;
    border: 1px solid transparent;
    border-radius: 4px;
    padding: var(--sp-2) var(--sp-4);
    cursor: pointer;
    transition: border-color 0.15s ease, color 0.15s ease;
    text-align: right;
    max-width: 68ch;
}

/* The lawyer list is a table of names and fees, not a line of talk: it keeps
   the full width of the page and its own left aligned reading. */
.eris-choices-panel > .eris-lawyer-row {
    align-self: stretch;
    text-align: left;
    max-width: none;
}

.eris-choice-btn:hover,
.eris-choice-btn.selected,
.eris-choice-btn:focus-visible {
    border-color: var(--text-primary-hover);
    color: var(--text-primary-hover);
    outline: none;
}

/* The spread on its way out. The four Eris pages set this from script rather
   than each writing the same two properties into an element's style. */
.eris-fading {
    transition: opacity 0.2s ease-out;
    opacity: 0;
}

/* --------------------------------------------------------------------------
   The sheet (right page)
   -------------------------------------------------------------------------- */

/* A column of .inspect-spec-row facts that gives up its height before the
   totals under it do. */
.eris-rows {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 0 1 auto;
    min-height: 0;
    overflow-y: auto;
    padding-right: var(--sp-1);
}

/* The one line on the sheet that is a sum rather than a fact. */
.eris-total {
    display: flex;
    justify-content: space-between;
    gap: var(--sp-3);
    flex: 0 0 auto;
    font-family: var(--font-ui);
    font-size: var(--fs-detail-heading);
    color: var(--text-detail-label);
    border-top: 1px solid var(--border-primary-hover-translucent-15);
    padding-top: var(--sp-3);
    margin-top: var(--sp-3);
}

.eris-total span:last-child {
    color: var(--text-success-active);
    font-weight: bold;
}

/* The fee the party cannot cover. */
.eris-total.eris-fee-short span:last-child {
    color: var(--text-danger-dark);
}

/* A meter: the court's chaos, her opinion. The fill is a computed width, so it
   comes in as a custom property and the stylesheet draws it. */
.eris-meter {
    flex: 0 0 auto;
    margin-top: var(--sp-4);
}

.eris-meter .meter-label {
    display: flex;
    align-items: center;
    gap: var(--sp-1);
    font-family: var(--font-ui);
    font-size: var(--fs-detail-body);
    color: var(--text-detail-label);
    margin-bottom: var(--sp-1);
}

.eris-meter-track {
    width: 100%;
    height: 8px;
    background: var(--shadow-primary-hover-translucent-5);
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    overflow: hidden;
}

.eris-meter-fill {
    height: 100%;
    width: var(--fill, 0%);
    border-radius: 4px;
    background: var(--bg-bg-alt-14);
    transition: width 0.4s ease;
}

/* --------------------------------------------------------------------------
   The verdict
   -------------------------------------------------------------------------- */

.eris-verdict-stamp {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(-12deg) scale(0);
    font-family: var(--font-ui);
    font-size: var(--fs-display);
    letter-spacing: 6px;
    text-transform: uppercase;
    padding: 10px 40px;
    border: 3px solid;
    border-radius: 6px;
    pointer-events: none;
    z-index: 20;
    opacity: 0;
    animation: erisStampSlam 0.5s 0.1s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards;
}

.eris-verdict-stamp.guilty {
    color: var(--text-text-alt-10);
    border-color: var(--border-danger-active);
}

.eris-verdict-stamp.innocent {
    color: var(--text-text-alt-22);
    border-color: var(--text-text-alt-22);
}

@keyframes erisStampSlam {
    0%   { transform: translate(-50%, -50%) rotate(-12deg) scale(3); opacity: 0; }
    70%  { transform: translate(-50%, -50%) rotate(-12deg) scale(0.95); opacity: 0.9; }
    100% { transform: translate(-50%, -50%) rotate(-12deg) scale(1); opacity: 1; }
}

/* --------------------------------------------------------------------------
   The brief: retaining a defence before the hearing opens. The same spread,
   so only the roster row, the dossier card and the odds bars are new.
   -------------------------------------------------------------------------- */

.eris-lawyer-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: var(--sp-4);
}

.eris-lawyer-cost {
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    color: var(--text-success-active);
    white-space: nowrap;
}

/* Priced out of reach: still visible, still inspectable, not selectable. */
.eris-lawyer-row.eris-row-poor,
.eris-lawyer-row.eris-row-poor .eris-lawyer-cost {
    color: var(--text-danger-dark);
}

.eris-lawyer-card {
    display: flex;
    flex-direction: column;
    gap: var(--sp-3);
    flex: 1 1 auto;
    min-height: 0;
}

.eris-lawyer-sprite {
    flex-shrink: 0;
    border-radius: 4px;
    background-repeat: no-repeat;
    /* The canvas keeps its own 64x64 backing box, so the frame drawn into it at
       its true proportions is never scaled back out of shape. */
    image-rendering: pixelated;
}

.eris-lawyer-sprite-empty {
    width: 64px;
    height: 64px;
    background-image: none;
}

.eris-lawyer-name {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-title);
    color: var(--text-detail-heading);
}

.eris-lawyer-title {
    font-family: var(--font-ui);
    font-size: var(--fs-detail-body);
    color: var(--text-detail-label);
}

/* Projected outcome: what it is called, how likely it is, and the number. */
.eris-odds-list {
    display: flex;
    flex-direction: column;
    gap: var(--sp-2);
}

.eris-odds-row {
    display: flex;
    align-items: center;
    gap: var(--sp-3);
    font-family: var(--font-ui);
    font-size: var(--fs-detail-body);
    color: var(--text-detail-label);
}

.eris-odds-label {
    flex: 0 0 42%;
}

.eris-odds-track {
    flex: 1;
    height: 8px;
    border-radius: 4px;
    background: var(--shadow-primary-hover-translucent-5);
    border: 1px solid var(--border-primary-hover-translucent-15);
    overflow: hidden;
}

.eris-odds-fill {
    display: block;
    height: 100%;
    width: var(--fill, 0%);
    border-radius: 4px;
    transition: width 0.25s ease;
}

.eris-odds-fill.good { background: var(--text-text-alt-22); }
.eris-odds-fill.warn { background: var(--text-text-alt-20); }
.eris-odds-fill.bad  { background: var(--border-danger-active); }
.eris-odds-fill.ban  { background: var(--text-text-alt-19); }

.eris-odds-value {
    flex: 0 0 3.2em;
    text-align: right;
    font-family: var(--font-ui);
    font-size: var(--fs-detail-body);
    font-weight: bold;
    color: var(--text-success-active);
}

/* --------------------------------------------------------------------------
   The date sheet: everything above, plus her portrait and her pulse.
   -------------------------------------------------------------------------- */

.eris-date-portrait-frame {
    display: flex;
    justify-content: center;
    /* The portrait gives up its height to the readings under it, never the
       other way round. */
    flex: 1 1 auto;
    min-height: 0;
    margin-bottom: var(--sp-4);
}

.eris-date-portrait {
    max-height: 100%;
    max-width: 100%;
    width: auto;
    object-fit: contain;
    padding: 4px;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
}

/* She is not there any more: the picture stops agreeing with itself. */
@keyframes erisEldritchFlicker {
    0%, 100% { filter: invert(1) hue-rotate(120deg) saturate(2.2) contrast(1.15); }
    43%      { filter: invert(1) hue-rotate(160deg) saturate(3) contrast(1.3); }
    47%      { filter: invert(0) hue-rotate(300deg) saturate(0.3) brightness(0.5); }
    52%      { filter: invert(1) hue-rotate(90deg) saturate(2.6) contrast(1.4); }
    56%      { filter: invert(1) hue-rotate(120deg) saturate(2.2) contrast(1.15); }
}

.eris-eldritch-portrait {
    animation: erisEldritchFlicker 4.3s steps(1) infinite;
}

/* A heart beating at the rate it is reporting. The rate is the reading, so it
   arrives as a custom property. */
@keyframes erisHeartPulse {
    0%   { transform: scale(1); }
    30%  { transform: scale(1.35); }
    60%  { transform: scale(1); }
    100% { transform: scale(1); }
}

.eris-pulse-icon {
    display: inline-block;
    animation: erisHeartPulse var(--pulse-rate, 1s) ease-in-out infinite;
}

/* Her opinion, filled in the one colour in the game that is not the gold. */
.eris-meter-fill.eris-opinion-fill {
    background: linear-gradient(90deg, var(--eris-accent-deep), var(--eris-accent), var(--eris-accent-light));
    transition: width 0.5s ease;
}

/* ==========================================================================
   Apiary Scene
   ========================================================================== */

#apiary-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 100;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--gradient-1);
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    user-select: none;
}

#apiary-container .left-page {
    width: 58%;
    flex: none;
    padding: 28px 40px 28px 45px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    height: 100%;
    border-right: 1px solid var(--border-secondary-hover-translucent-15);
}

#apiary-container .right-page {
    width: 42%;
    flex: none;
    padding: 28px 45px 28px 40px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    height: 100%;
}

#apiary-container .title {
    font-family: var(--font-ui);
    font-size: 1.95em;
    color: var(--text-secondary-active);
    border-bottom: 2px solid var(--border-muted-focus);
    padding-bottom: 6px;
    margin: 0 0 14px 0;
    text-align: center;
    letter-spacing: 1px;
}

.apiary-content-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 24px;
    flex: 1;
    overflow-y: auto;
    align-content: start;
    min-height: 0;
}

.apiary-content-grid > div {
    min-width: 0;
}

.apiary-section {
    margin-bottom: 12px;
}

.apiary-section-title {
    font-family: var(--font-ui);
    font-size: 0.952rem;
    color: var(--border-focus-hover);
    text-transform: uppercase;
    border-bottom: none;
    margin-bottom: 6px;
    padding-bottom: 2px;
    font-weight: bold;
    letter-spacing: 0.5px;
}

/* The hive in cross section (Farming/ApiarySystem.js). The canvas cannot
   inherit an ink, so the palette is declared here and read back off this
   element with getComputedStyle: the two presets paint the same comb in their
   own colours, and the plugin names no colour of its own. */
.apiary-hive {
    --apiary-air: var(--bg-panel);
    --apiary-wood: var(--text-brown-medium);
    --apiary-wax: var(--border-gold-amber-30);
    --apiary-empty: var(--bg-focus-hover-translucent-18);
    --apiary-honey: var(--border-focus-hover);
    --apiary-pollen: var(--accent-amber-light);
    --apiary-brood: var(--accent-cream-warm);
    --apiary-queen: var(--text-cost-ok);
}

.apiary-hive-mount {
    display: block;
    border: 1px solid var(--border-gold-amber-30);
    border-radius: 4px;
    overflow: hidden;
    background: var(--bg-panel);
}

#apiary-hive-canvas {
    display: block;
    width: 100%;
    height: auto;
    image-rendering: pixelated;
}

.apiary-hive-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 14px;
    margin-top: 5px;
    font-family: var(--font-ui);
    font-size: 0.84rem;
    color: var(--text-text-alt-4);
}

.apiary-hive-legend span { display: inline-flex; align-items: center; gap: 5px; }

.apiary-key {
    display: inline-block;
    width: 9px;
    height: 9px;
    border: 1px solid var(--border-gold-amber-30);
    border-radius: 2px;
}

.apiary-key-brood { background: var(--accent-cream-warm); }
.apiary-key-pollen { background: var(--accent-amber-light); }
.apiary-key-honey { background: var(--border-focus-hover); }
.apiary-key-empty { background: var(--bg-focus-hover-translucent-18); }

.apiary-stat-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.984rem;
    margin-bottom: 3px;
    font-family: var(--font-ui);
    color: var(--text-text-alt-4);
}

.apiary-stat-row span:last-child {
    font-weight: bold;
    color: var(--text-success-active);
}

.apiary-pop-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.apiary-pop-row {
    display: flex;
    justify-content: space-between;
    font-size: 0.96rem;
    font-family: var(--font-ui);
    padding: 1px 0;
}

.apiary-pop-label { color: var(--text-text-alt-4); }
.apiary-pop-value { font-weight: bold; color: var(--text-success-active); }

.apiary-resources {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 14px;
}

.apiary-resource-header {
    display: flex;
    justify-content: space-between;
    font-size: 0.96rem;
    font-family: var(--font-ui);
    color: var(--text-text-alt-4);
    margin-bottom: 3px;
}

.apiary-resource-bar {
    height: 6px;
    background: var(--bg-focus-hover-translucent-18);
    border-radius: 3px;
    overflow: hidden;
}

.apiary-resource-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--border-focus-hover), #d4af37);
    border-radius: 3px;
    transition: width 0.35s ease;
}

.apiary-warning {
    color: var(--text-text-alt-10);
    font-weight: bold;
    font-size: 0.984rem;
    margin: 4px 0;
    font-family: var(--font-ui);
}

.apiary-threats {
    font-family: var(--font-ui);
    font-size: 0.96rem;
    color: var(--text-text-alt-10);
    margin: 8px 0;
    padding: 5px 10px;
    border: 1px solid var(--border-danger-translucent-35);
    border-radius: 4px;
    background: var(--bg-danger-translucent-5);
}

.apiary-threats.safe {
    color: var(--text-text-alt-3);
    border-color: var(--border-success-medium-35);
    background: var(--bg-success-medium-5);
}

.apiary-feedback {
    font-family: var(--font-ui);
    font-size: 0.984rem;
    color: var(--text-info-blue);
    margin: 8px 0;
    padding: 5px 10px;
    border: 1px solid var(--border-info-blue-35);
    border-radius: 4px;
    background: var(--bg-info-blue-5);
    animation: fade-in 0.2s ease-out;
}

.apiary-actions {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    margin-top: auto;
    padding-top: 16px;
}

.apiary-action-btn {
    font-family: var(--font-ui);
    font-size: 1.056rem;
    padding: 9px 16px;
    border: 1.5px solid var(--border-success);
    border-radius: 4px;
    cursor: pointer;
    text-align: center;
    color: var(--text-disabled);
    background: var(--bg-warm-cream-25);
    transition: all 0.15s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.apiary-action-btn:hover,
.apiary-action-btn.focused {
    background: var(--bg-focus-hover-translucent-18);
    border-color: var(--border-focus-hover);
    color: var(--text-success-active);
    transform: translateX(4px);
}

/* ==========================================================================
   Brewing System
   ========================================================================== */

#brewery-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 100;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--gradient-1);
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    box-sizing: border-box;
    user-select: none;
}

#brewery-container .left-page {
    width: 55%;
    flex: none;
    padding: 28px 36px 28px 45px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    height: 100%;
    border-right: 1px solid var(--border-secondary-hover-translucent-15);
}

#brewery-container .right-page {
    width: 45%;
    flex: none;
    padding: 28px 45px 28px 36px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    height: 100%;
}

#brewery-container .title {
    font-family: var(--font-ui);
    font-size: 1.95em;
    color: var(--text-secondary-active);
    border-bottom: 2px solid var(--border-muted-focus);
    padding-bottom: 6px;
    margin: 0 0 14px 0;
    text-align: center;
    letter-spacing: 1px;
}

.brewery-recipe-row {
    padding: 7px 10px;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.12s, transform 0.12s;
    margin-bottom: 5px;
    border: 1px solid transparent;
}

.brewery-recipe-row:hover {
    background: var(--bg-focus-hover-translucent-10);
    border-color: var(--border-parchment-30);
}

.brewery-recipe-row.focused {
    background: var(--bg-focus-hover-translucent-18);
    border-color: var(--border-success);
    transform: translateX(3px);
}

.brewery-recipe-name {
    font-family: var(--font-ui);
    font-size: 1.02rem;
    font-weight: bold;
    color: var(--text-success-active);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
}

.brewery-recipe-time {
    font-size: 0.903rem;
    color: var(--text-brown-medium);
    font-weight: normal;
    margin-left: auto;
    white-space: nowrap;
}

.brewery-recipe-meta {
    font-size: 0.903rem;
    color: var(--text-text-alt-4);
    margin-top: 2px;
    padding-left: 2px;
}

.brewery-recipe-output {
    font-size: 0.891rem;
    color: var(--text-brown-medium);
    margin-top: 2px;
    padding-left: 2px;
    font-style: normal;
}

.brewery-stage-bar {
    height: 8px;
    background: var(--bg-focus-hover-translucent-18);
    border-radius: 4px;
    overflow: hidden;
}

.brewery-stage-fill {
    height: 100%;
    background: linear-gradient(to right, #c0873f, #d4aa1f, var(--text-text-alt-3));
    border-radius: 4px;
    transition: width 0.4s ease;
}

.brewery-ingredient-check {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.964rem;
    font-family: var(--font-ui);
    margin: 3px 0;
}

/* ==========================================================================
   HistorySimulator, Scene_History DOM overlay
   ========================================================================== */

#history-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--gradient-1);
    z-index: 1000;
    display: flex;
    justify-content: center;
    align-items: center;
    font-family: var(--font-ui);
    color: var(--text-muted-hover);
    overflow: hidden;
    user-select: none;
    box-sizing: border-box;
}

.hs-button-focused {
    outline: 2px solid var(--text-primary-hover);
    outline-offset: 2px;
}

/* The archive is Shape A on the shared kit: the .book-spread, the .ui-list of
   .item-slot entries and the .item-inspect cards do all the drawing. What is
   left here is the one thing this screen has that no other does - a century
   filed into years and months. */
#history-timeline-list {
    overflow-y: auto;
    padding-right: 8px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

/* A decade rail over the list: the jump a hundred years of entries cannot be
   scrolled to. Chips, so it reads as the tab strip above it does. */
.hist-rail {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-bottom: 12px;
    flex: 0 0 auto;
}
.hist-decade {
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    color: var(--text-text-alt-4);
    padding: 2px 8px;
    border: 1px solid transparent;
    border-radius: 3px;
    cursor: pointer;
}
.hist-decade:hover,
.hist-decade:focus {
    border-color: var(--text-primary-hover);
    color: var(--text-primary-hover);
    outline: none;
}

/* A year, and the months inside it. The year rides the top of the list as it
   scrolls, so a reader always knows which one they are in. */
.hist-year { display: flex; flex-direction: column; }
.hist-year-hdr {
    position: sticky;
    top: 0;
    z-index: 1;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 8px;
    padding: 6px 0 4px;
    background: var(--gradient-1);
}
.hist-year-num {
    font-family: var(--font-ui);
    font-size: var(--fs-heading);
    font-weight: bold;
    letter-spacing: 0.08em;
    color: var(--text-primary-hover);
}
.hist-year-count {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    color: var(--text-text-alt-4);
}
.hist-month { display: flex; flex-direction: column; }
.hist-month-hdr {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--text-text-alt-4);
    padding: 6px 0 2px 2px;
}

/* One entry. The day is the key on the left, the sentence is the entry, the
   category is a word under it: no plate, no frame, no accent bar. */
.hist-row { align-items: flex-start; gap: 10px; }
.hist-day {
    flex: 0 0 auto;
    min-width: 2.4ch;
    text-align: right;
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-text-alt-4);
    padding-top: 1px;
}
.hist-line {
    white-space: normal;
    line-height: 1.35;
}
.hist-cat {
    font-size: var(--fs-caption);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-right: 10px;
}

/* The six bands a chronicle category is read in. The ink is a token in all
   three theme files; this screen names no colour of its own. */
.hist-cat--war      { color: var(--hist-cat-war); }
.hist-cat--state    { color: var(--hist-cat-state); }
.hist-cat--trade    { color: var(--hist-cat-trade); }
.hist-cat--people   { color: var(--hist-cat-people); }
.hist-cat--arcane   { color: var(--hist-cat-arcane); }
.hist-cat--science  { color: var(--hist-cat-science); }
.hist-cat--other    { color: var(--text-text-alt-4); }

.hist-delta-up   { color: var(--text-cost-ok); }
.hist-delta-down { color: var(--text-cost-bad); }

.hist-detail {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
}
.hist-empty {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-text-alt-4);
    text-align: center;
    margin-top: 40px;
}

/* ==========================================================================
   DialogueSystem, Parchment message & choice overlays
   ========================================================================== */

#html-msg-overlay {
    position: fixed;
    display: none;
    z-index: 500;
    pointer-events: none;
    box-sizing: border-box;
    overflow: hidden;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
}

#html-msg-name {
    position: fixed;
    display: none;
    white-space: nowrap;
    z-index: 500;
    font-family: var(--font-ui);
    font-weight: bold;
    color: var(--text-primary-hover);
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 4px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -5px;
    padding: 2px 14px;
    text-shadow: none;
}

#html-msg-text {
    font-family: var(--font-ui);
    font-weight: bold;
    color: var(--text-pure-white);
    line-height: 1.55;
    white-space: pre-wrap;
    /* The reveal cuts the line into two spans at the character the typewriter
       has reached, so the split usually falls inside a word. `word-break` opens
       a break opportunity anywhere and lets the browser wrap there, cutting the
       word in half; `overflow-wrap` only breaks a word that cannot fit a line
       on its own, which is all this box ever needed. */
    overflow-wrap: break-word;
    word-break: normal;
    text-shadow: none;
}

/* The word the typewriter is in the middle of: two elements, one word. It is
   held on one line so the box can never wrap between the half already typed
   and the half still hidden. */
#html-msg-text .msg-split {
    white-space: nowrap;
}

/* The part of the line the typewriter has not reached yet. It is laid out with
   the rest so the box wraps once, off the finished line, and no word moves as
   the text is read out; it is simply not painted until its turn comes. */
#html-msg-text .msg-unrevealed {
    visibility: hidden;
}

/* A [Keyword] the party can ask about: the only gold in the line. */
#html-msg-text .msg-keyword {
    color: var(--text-primary-hover);
}

#html-choice-overlay {
    position: fixed;
    display: none;
    z-index: 501;
    pointer-events: auto;
    box-sizing: border-box;
    padding: 8px 6px;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
}

.html-choice-item {
    font-family: var(--font-ui);
    font-weight: bold;
    padding: 5px 18px;
    border: 2px solid transparent;
    transition: background 0.1s;
    white-space: nowrap;
    user-select: none;
    line-height: 1.45;
    color: var(--accent-orange);
}
.html-choice-item.disabled {
    color: rgba(255, 204, 102, 0.38);
}
.html-choice-item.selected {
    background: rgba(255, 204, 102, 0.12);
    border-color: var(--accent-orange);
}

/* The Ask / Tell board (NPC/DialogueSystem.js): the same parchment choice list
   laid out as a grid, one heading per bank - the topics that are always there
   and the ones this place brings up - with Cancel on its own line under both. */
#html-choice-overlay.story-ask-grid {
    max-width: 72vw;
    padding: 10px 14px 12px;
}
#html-choice-overlay.story-ask-grid .html-choice-rows {
    display: grid;
    gap: 2px 14px;
}
#html-choice-overlay.story-ask-grid .html-choice-group {
    font-family: var(--font-ui);
    font-weight: bold;
    font-size: 0.72em;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--text-disabled);
    opacity: 0.85;
    padding: 6px 18px 3px;
    border-bottom: 1px solid var(--border-subtle-translucent-40);
    margin-bottom: 4px;
}
#html-choice-overlay.story-ask-grid .html-choice-group:first-child {
    padding-top: 0;
}
#html-choice-overlay.story-ask-grid .html-choice-item {
    white-space: normal;
}
#html-choice-overlay.story-ask-grid .html-choice-item.html-choice-tail {
    margin-top: 8px;
    border-top: 1px solid var(--border-subtle-translucent-40);
    padding-top: 8px;
}

/* ==========================================================================
   VEHICLE STATUS CARD (Vehicle/VehicleSystem.js)
   --------------------------------------------------------------------------
   Fuel and condition of the vehicle whose action menu is open, drawn at the
   top of the screen for as long as the choices are. The choice list anchors
   itself to the message window at the bottom, and the map info card owns the
   bottom-right, so the top strip is the one place the card never covers what
   it is explaining.
   ========================================================================== */

#vehicle-status-card {
    position: fixed;
    top: 18px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 502;
    pointer-events: none;
    box-sizing: border-box;
    min-width: 320px;
    font-family: var(--font-ui);
    background: var(--bg-secondary-hover);
    border: 3px double var(--text-primary-hover);
    border-radius: 6px;
    box-shadow: 0 10px 28px var(--shadow-black-translucent-55);
    padding: 12px 20px;
}
#vehicle-status-card .vsc-title {
    font-size: 21px;
    font-weight: 600;
    color: var(--text-primary-hover);
    letter-spacing: 0.4px;
    text-align: center;
    padding-bottom: 8px;
}
#vehicle-status-card .vsc-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding-top: 6px;
}
#vehicle-status-card .vsc-lbl {
    flex: 0 0 auto;
    min-width: 96px;
    font-size: 17px;
    font-weight: 600;
    color: var(--text-success-active);
}
/* Same track as the map info card's need bars, so a fuel gauge reads the same
   whichever card it is on. */
#vehicle-status-card .vsc-bar {
    flex: 1 1 auto;
    height: 10px;
    border-radius: 5px;
    overflow: hidden;
    background: var(--shadow-black-translucent-55);
}
#vehicle-status-card .vsc-fill {
    height: 100%;
    border-radius: 5px;
    transition: width 0.2s ease-out;
}
#vehicle-status-card .vsc-green { background: #6bbf59; }
#vehicle-status-card .vsc-amber { background: #e8c840; }
#vehicle-status-card .vsc-red   { background: var(--text-blood-red); }
#vehicle-status-card .vsc-val {
    flex: 0 0 auto;
    min-width: 104px;
    text-align: right;
    font-size: 16px;
    font-weight: 700;
    color: var(--text-primary-hover);
}
#vehicle-status-card .vsc-warn {
    padding-top: 9px;
    text-align: center;
    font-size: 16px;
    font-weight: 700;
    color: var(--text-blood-red);
}

/* ==========================================================================
   Scene_GameEnd, parchment DOM overlay (matches html-choice-overlay style)
   ========================================================================== */

#game-end-parchment {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 501;
    pointer-events: auto;
    box-sizing: border-box;
    padding: 8px 6px;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
    min-width: 180px;
}

.game-end-parchment-item {
    font-family: var(--font-ui);
    font-weight: bold;
    font-size: 24px;
    padding: 5px 18px;
    border-radius: 4px;
    border: 2px solid transparent;
    transition: background 0.1s;
    white-space: nowrap;
    user-select: none;
    color: var(--text-primary-hover);
    cursor: pointer;
}

/* ==========================================================================
   VisualNovelBustSystem, HTML character name label
   ========================================================================== */

#vn-name-overlay {
    position: fixed;
    display: none;
    z-index: 501;
    pointer-events: none;
    white-space: nowrap;
    box-sizing: border-box;
    font-family: var(--font-ui);
    font-weight: bold;
    color: var(--text-primary-hover);
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 4px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -5px;
    padding: 3px 14px;
}

/* ==========================================================================
   MapLevelDisplay, HTML map name overlay
   ========================================================================== */

#html-map-name-overlay {
    position: fixed;
    display: none;
    z-index: 490;
    pointer-events: none;
    box-sizing: border-box;
    overflow: hidden;
    white-space: nowrap;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
    color: var(--text-primary-hover);
    font-family: var(--font-ui);
    font-weight: bold;
    box-shadow: 0 4px 10px var(--shadow-black-translucent-25);
}

/* ==========================================================================
   CrimeSystem, crime notification content (rendered inside a ParchmentToast)
   ========================================================================== */

.crime-notif-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 16px;
}

.crime-notif-name {
    color: var(--text-text-alt-10);
}

.crime-notif-bounty {
    color: var(--text-gold-dark);
}

.crime-notif-total {
    text-align: center;
    color: var(--text-primary-hover);
    opacity: 0.85;
}

/* ==========================================================================
   NPCEmpathize, NPC dialogue book overlay
   ========================================================================== */

/* Suppress book-spread entry animation inside this overlay (uses own opacity fade) */
.npc-empathize-overlay .book-spread {
    animation: none;
}

/* ── Left page ────────────────────────────────────────────────────────────── */
.npc-dlg-left {
    border-right: none;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    padding: 16px 18px 14px;
    background: var(--bg-primary-hover-translucent-35);
    overflow: hidden;
    box-sizing: border-box;
}

/* ── Right page ───────────────────────────────────────────────────────────── */
.npc-dlg-right {
    padding: 16px 22px 16px 32px;
    overflow-y: auto;
    justify-content: flex-start;
    box-sizing: border-box;
}

/* ── Header (portrait + name) ─────────────────────────────────────────────── */
.npc-dlg-hdr {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 10px;
    flex-shrink: 0;
}
.npc-dlg-portrait {
    width: 96px;
    height: 96px;
    flex-shrink: 0;
    border-radius: 4px;
    border: 1.5px solid var(--border-focus-hover);
    overflow: hidden;
    background: var(--bg-subtle-translucent-10);
}
.npc-dlg-portrait img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: top center;
    image-rendering: pixelated;
    display: block;
}
.npc-dlg-ident {
    flex: 1;
    min-width: 0;
}
.npc-dlg-name {
    font-size: var(--fs-title);
    font-weight: bold;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.npc-dlg-subline {
    font-size: var(--fs-caption);
    color: var(--text-text-alt-4);
    margin-top: 2px;
}

/* ── Separators ───────────────────────────────────────────────────────────── */
.npc-dlg-sep {
    border: none;
    border-top: 1px solid var(--border-subtle-translucent-30);
    margin: 8px 0;
    flex-shrink: 0;
}
.npc-dlg-r-sep {
    border: none;
    border-top: 1px solid var(--border-subtle-translucent-25);
    margin: 12px 0 8px;
}

/* ── Chat area ────────────────────────────────────────────────────────────── */
.npc-dlg-chat {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 4px 2px;
    margin-bottom: 8px;
    min-height: 60px;
}
.npc-dlg-bubble {
    max-width: 92%;
    padding: 6px 10px;
    border-radius: 8px;
    font-size: var(--fs-body);
    line-height: 1.45;
    word-break: break-word;
}
.bubble-player {
    align-self: flex-end;
    background: var(--bg-white-translucent-45);
    border: 1px solid var(--border-focus-hover);
    border-radius: 8px 8px 2px 8px;
}
.bubble-npc {
    align-self: flex-start;
    background: var(--shadow-black-translucent-6);
    border: 1px solid var(--border-subtle-translucent-18);
    border-radius: 8px 8px 8px 2px;
}
.bubble-npc-name {
    display: block;
    font-size: var(--fs-caption);
    font-weight: bold;
    opacity: 0.6;
    margin-bottom: 2px;
}
.npc-dlg-typing {
    font-style: normal;
    opacity: 0.55;
    font-size: var(--fs-caption);
    animation: dlg-blink 0.9s step-end infinite;
}
@keyframes dlg-blink {
    0%, 100% { opacity: .55; }
    50%       { opacity: .15; }
}

/* ── Chat input ───────────────────────────────────────────────────────────── */
.npc-dlg-input-row {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
    margin-bottom: 8px;
}
.npc-dlg-input {
    flex: 1;
    padding: 6px 10px;
    border-radius: 4px;
    border: 1.5px solid var(--border-focus-hover);
    background: var(--bg-white-translucent-40);
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-primary-hover);
    outline: none;
}
.npc-dlg-input:focus {
    border-color: var(--border-subtle);
    background: var(--bg-white-translucent-72);
}
.npc-dlg-send-btn {
    padding: 6px 12px;
    background: var(--border-focus-hover);
    color: var(--text-danger-hover);
    border: 1px solid var(--border-subtle);
    border-radius: 4px;
    font-family: var(--font-ui);
    font-weight: bold;
    cursor: pointer;
    font-size: var(--fs-body);
    user-select: none;
    flex-shrink: 0;
}
.npc-dlg-send-btn:hover {
    filter: brightness(1.12);
}

/* ── Action button grid ───────────────────────────────────────────────────── */
.npc-dlg-actions {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    justify-items: center;
    gap: 3px;
    flex-shrink: 0;
}
.npc-dlg-action-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 8px;
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    font-weight: bold;
    color: var(--text-primary-hover);
    background: var(--bg-subtle-translucent-5);
    border: 1px solid transparent;
    border-left: 3px solid transparent;
    border-radius: 3px;
    cursor: pointer;
    user-select: none;
    transition: background 0.1s;
}
.npc-dlg-action-btn:hover,
.npc-dlg-action-btn.focused {
    border-color: var(--text-primary-hover);
}
.npc-dlg-action-btn.disabled {
    opacity: 0.35;
    cursor: default;
    pointer-events: none;
}
.npc-dlg-action-btn .btn-icon {
    width: 20px;
    text-align: center;
    flex-shrink: 0;
}

/* ── Join feedback banner ─────────────────────────────────────────────────── */
.npc-dlg-join-msg {
    padding: 6px 10px;
    margin-bottom: 4px;
    border-radius: 4px;
    font-size: var(--fs-label);
    font-style: normal;
    line-height: 1.4;
    flex-shrink: 0;
}
.npc-dlg-join-msg.accept {
    background: var(--bg-success-green-15);
    color: var(--text-forest-green);
}
.npc-dlg-join-msg.reject {
    background: var(--bg-danger-medium-10);
    color: var(--text-blood-red);
}

/* ── Right page, profile rows ────────────────────────────────────────────── */
.npc-dlg-row {
    display: flex;
    align-items: center;
    gap: 9px;
    font-size: var(--fs-label);
    margin-bottom: 6px;
}
.npc-dlg-sec-hdr {
    font-size: var(--fs-label);
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    color: var(--text-text-alt-4);
    margin-bottom: 6px;
}

/* ── Tags ─────────────────────────────────────────────────────────────────── */
.npc-dlg-tags-wrap {
    display: flex;
    flex-wrap: wrap;
}
.npc-dlg-tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    font-weight: 600;
    color: var(--text-text-alt-4);
    background: transparent;
    border: 1px solid var(--border-success);
    border-radius: 4px;
    padding: 2px 8px;
    margin: 3px 3px 0 0;
}

/* ── Vitals bars ──────────────────────────────────────────────────────────── */
.npc-dlg-vitals {
    font-size: var(--fs-caption);
    margin-bottom: 4px;
    opacity: 0.85;
}
.npc-dlg-vital-bar {
    height: 6px;
    border-radius: 3px;
    display: inline-block;
    vertical-align: middle;
    margin-top: 2px;
    max-width: 100px;
}

/* ── Stats rows ───────────────────────────────────────────────────────────── */
.npc-dlg-stats-row {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: var(--fs-label);
    flex-wrap: wrap;
    margin-bottom: 6px;
}
.npc-dlg-custom-stats-row {
    display: flex;
    align-items: center;
    gap: 9px;
    font-size: var(--fs-caption);
    opacity: 0.8;
    flex-wrap: wrap;
    margin-bottom: 6px;
}

/* ── Opinion / thoughts ───────────────────────────────────────────────────── */
.npc-dlg-opinion-note {
    font-size: var(--fs-label);
    margin-top: 4px;
    opacity: 0.65;
    font-style: normal;
}
.npc-dlg-thought {
    font-size: var(--fs-label);
    font-style: normal;
    margin-top: 6px;
    opacity: 0.75;
    border-left: 2px solid var(--border-subtle-translucent-30);
    padding-left: 8px;
}

/* ── Money label ──────────────────────────────────────────────────────────── */
.npc-dlg-money-label {
    font-size: var(--fs-label);
}

/* ── EXP bar ──────────────────────────────────────────────────────────────── */
.npc-dlg-exp-section {
    margin-top: 5px;
}
.npc-dlg-exp-label {
    font-size: var(--fs-caption);
    opacity: 0.6;
    margin-bottom: 2px;
}
.npc-dlg-exp-track {
    height: 4px;
    background: var(--bg-subtle-translucent-15);
    border-radius: 2px;
    overflow: hidden;
}
.npc-dlg-exp-fill {
    height: 100%;
    background: var(--border-focus-hover);
    border-radius: 2px;
    transition: width 0.3s;
}

/* ── Panel header (social web / steal mode) ───────────────────────────────── */
.npc-dlg-panel-hdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}
.npc-dlg-panel-hdr .npc-dlg-sec-hdr {
    margin: 0;
}
.npc-dlg-back-link {
    font-size: var(--fs-body);
    opacity: 0.65;
    cursor: pointer;
    padding: 3px 8px;
    border: 1px solid var(--border-subtle-translucent-30);
    border-radius: 3px;
}
.npc-dlg-back-link:hover {
    opacity: 1;
    border-color: var(--text-primary-hover);
}

/* ── Steal list items ─────────────────────────────────────────────────────── */
.npc-dlg-steal-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px;
    border: 1px solid transparent;
    border-radius: 3px;
    background: transparent;
    cursor: pointer;
}
.npc-dlg-steal-item:hover {
    border-color: var(--text-primary-hover);
}
.npc-dlg-steal-item.done {
