    pointer-events: none;
}

/* ── Social web legend ────────────────────────────────────────────────────── */
.npc-dlg-web-legend {
    display: flex;
    gap: 14px;
    flex-wrap: wrap;
    font-size: var(--fs-caption);
    opacity: 0.72;
    margin-top: 2px;
}
.npc-dlg-legend-item {
    display: flex;
    align-items: center;
    gap: 5px;
}
.npc-dlg-legend-line {
    width: 18px;
    display: inline-block;
}
.npc-dlg-legend-line--single {
    height: 2px;
    background: var(--bg-npc-bark);
}
.npc-dlg-legend-line--multi {
    height: 4px;
    background: var(--text-forest-green);
}

/* ── Right-page portrait header (large bust) ──────────────────────────────── */
.npc-dlg-profile-hdr {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-bottom: 12px;
}
.npc-dlg-portrait-lg {
    width: 288px;
    height: 288px;
    border-radius: 6px;
    border: 2px solid var(--border-focus-hover);
    overflow: hidden;
    background: var(--bg-subtle-translucent-10);
    flex-shrink: 0;
    margin-bottom: 8px;
}
.npc-dlg-portrait-lg img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: top center;
    image-rendering: pixelated;
    display: block;
}
.npc-dlg-name--center  { text-align: center; white-space: normal; }
.npc-dlg-subline--center { text-align: center; }

/* ── HP / MP bars ─────────────────────────────────────────────────────────── */
.npc-dlg-hpmp {
    font-size: var(--fs-caption);
    margin-top: 4px;
    opacity: 0.9;
}
.npc-dlg-hpmp-val {
    font-size: var(--fs-label);
    font-weight: bold;
}
.npc-dlg-vital-bar--hp { background: var(--bg-hp-bar); }
.npc-dlg-vital-bar--mp { background: var(--bg-mp-bar); }

/* ── Per-actor predisposition bars ───────────────────────────────────────── */
.npc-dlg-pred-list {
    display: flex;
    flex-direction: column;
    gap: 5px;
    margin-top: 2px;
}
.npc-dlg-pred-row {
    display: flex;
    align-items: center;
    gap: 7px;
    font-size: var(--fs-caption);
}
.npc-dlg-pred-name {
    width: 72px;
    flex-shrink: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-weight: bold;
    color: var(--text-text-alt-4);
}
.npc-dlg-pred-track {
    flex: 1;
    height: 7px;
    background: var(--bg-subtle-translucent-15);
    border-radius: 4px;
    overflow: hidden;
}
.npc-dlg-pred-fill {
    height: 100%;
    border-radius: 4px;
    transition: width 0.3s;
}
.npc-dlg-pred-val {
    width: 32px;
    flex-shrink: 0;
    text-align: right;
    font-weight: bold;
    font-size: var(--fs-label);
}

/* ==========================================================================
   NPCEmpathize Panel Styles
   ========================================================================== */

    /* ── The Empathize kit ─────────────────────────────────
       Empathize is five interfaces in one file (the panel, the chat modal,
       the social web, the entity wiki and the wiki index) and it used to
       carry more inline style attributes than any other screen in the game:
       an opacity here, a margin there, a bar colour computed from a score.
       They are all one of the classes below now. A plugin sets a class; a
       value that genuinely varies per row (a bar's length, an icon's cell)
       arrives as a custom property and the rule draws it. Nothing in the
       markup names a colour or a size any more. */

    /* Ink. The muted half of a label/value pair, and the caption below it.
       Both are warm, both sit on a transparent ground. */
    .npc-sub    { color: var(--text-text-alt-4); }
    .npc-faint  { color: var(--text-text-alt-4); opacity: 0.62; }
    .npc-bad    { color: var(--text-cost-bad); }
    .npc-good   { color: var(--text-cost-ok); }
    .npc-info   { color: var(--text-text-alt-19); }
    .npc-gold   { color: var(--text-gold-dark); }
    .npc-amber  { color: var(--text-amber-hint); }
    .npc-off    { color: var(--text-disabled); }
    .npc-em     { font-weight: bold; }
    /* A trailing aside on a row: "(x2)", "42%", "3 of the population". */
    .npc-note   { font-size: var(--fs-caption); color: var(--text-text-alt-4); }
    .npc-aside  { margin-left: var(--sp-2); }
    .npc-aside-sm { margin-left: var(--sp-1); }
    /* The one empty-state line every tab prints when it has nothing to say. */
    .npc-empty  { color: var(--text-text-alt-4); margin: var(--sp-4) 0 0; max-width: 68ch; }
    .npc-empty--inline {
      display: inline-block; padding: var(--sp-1) var(--sp-3);
      font-size: var(--fs-label); color: var(--text-text-alt-4);
    }
    .npc-empty--inline.npc-bad { color: var(--text-cost-bad); }

    /* Spacing. The scale is 4 / 6 / 8 / 12 / 18 / 24 and nothing between. */
    .npc-mt-1 { margin-top: var(--sp-1); }
    .npc-mt-2 { margin-top: var(--sp-2); }
    .npc-mt-3 { margin-top: var(--sp-3); }
    .npc-mt-4 { margin-top: var(--sp-4); }
    .npc-mb-0 { margin-bottom: 0; }
    .npc-mb-1 { margin-bottom: var(--sp-1); }
    .npc-mb-2 { margin-bottom: var(--sp-2); }
    .npc-mb-3 { margin-bottom: var(--sp-3); }
    .npc-my-1 { margin: var(--sp-1) 0; }
    .npc-para { margin: 0 0 var(--sp-3); max-width: 68ch; }

    /* Layout scraps that were written out as an attribute every time. */
    .npc-flex-1 { flex: 1; }
    .npc-top    { align-items: flex-start; }
    .npc-left   { text-align: left; }
    .npc-row-indent { margin: var(--sp-1) 0 0 24px; font-size: var(--fs-label); color: var(--text-text-alt-4); }
    .npc-row-full { flex-basis: 100%; font-size: var(--fs-label); color: var(--text-text-alt-4); margin: var(--sp-1) 0 -2px; }

    /* An IconSet cell. The sheet is 16 icons wide at 32px; the row and the
       column arrive as custom properties, the size as one more. */
    .npc-icon {
      display: inline-block; overflow: hidden; flex-shrink: 0; vertical-align: middle;
      width: var(--npc-icon-size, 22px); height: var(--npc-icon-size, 22px);
    }
    .npc-icon-cell {
      display: block; width: 32px; height: 32px;
      transform: scale(var(--npc-icon-scale, 1)); transform-origin: top left;
      background: url('../img/system/IconSet.png') var(--npc-icon-x, 0) var(--npc-icon-y, 0) no-repeat;
      image-rendering: pixelated;
    }

    /* Bars. Every meter in Empathize is a track with a fill, the fill's
       length is `--npc-w` and its colour is a BAND, never a literal: the
       plugin buckets the score and names the band, the stylesheet inks it. */
    .npc-vital-fill,
    .npc-pred-fill,
    .npc-exp-fill,
    .npc-animal-fill { width: var(--npc-w, 0%); }
    .npc-fill--ok    { background: var(--text-cost-ok); }
    .npc-fill--bad   { background: var(--text-cost-bad); }
    .npc-fill--warn  { background: var(--text-amber-hint); }
    .npc-fill--calm  { background: var(--text-caption-brown); }
    .npc-fill--info  { background: var(--text-text-alt-19); }
    .npc-fill--mp    { background: var(--bg-mp-bar-alt); }
    .npc-fill--green { background: var(--border-forest-green); }
    .npc-fill--bark  { background: var(--bg-npc-bark); }
    .npc-fill--muted { background: var(--text-brown-medium); }
    .npc-fill--good  { background: var(--text-cost-ok); }
    .npc-fill--warm  { background: var(--text-amber-hint); }
    /* The numeric column beside a bar. Three widths, because a percentage, a
       signed axis and a raw stat are three different measures. */
    .npc-vital-pct--num  { width: 44px; }
    .npc-vital-pct--wide { width: 74px; }
    .npc-vital-lbl--wide { width: 170px; }

    /* A score printed in its own band colour: predisposition, attraction,
       a steal chance, a morality reading. */
    .npc-score--good { color: var(--text-cost-ok); }
    .npc-score--warm { color: var(--text-amber-hint); }
    .npc-score--bad  { color: var(--text-cost-bad); }
    .npc-score--flat { color: var(--text-text-alt-4); }

    /* A severity dot in front of a disease. Same band names. */
    .npc-sev-dot {
      width: 10px; height: 10px; border-radius: 50%;
      margin-top: var(--sp-2); flex-shrink: 0;
    }

    /* The Kinsey scale's seven dots. */
    .npc-kinsey-row { margin: var(--sp-1) 0 0 2px; display: flex; align-items: center; }
    .npc-kinsey-dot {
      display: inline-block; width: 14px; height: 14px; margin-right: 3px;
      border-radius: 50%; border: 1px solid var(--border-subtle);
      background: var(--bg-subtle-translucent-15);
    }
    .npc-kinsey-dot.on { background: var(--text-cost-bad); }

    /* The one row in a list that is being pointed at. A gold hairline and
       nothing behind it, the same as every other list in the game. */
    .npc-pickable { cursor: pointer; border: 1px solid transparent; border-radius: 4px; }
    .npc-pickable.on { border-color: var(--text-primary-hover); }

    /* A hostile standing badge: the one filled plate on the page, so it takes
       the bright ink rather than the muted one. */
    .npc-need-badge--hostile {
      background: var(--bg-crime-dark-10);
      color: var(--text-cost-bad);
      border-color: var(--text-cost-bad);
    }
    .npc-dead-badge--ruling { background: var(--border-forest-green); }

    /* The whole panel when the NPC has gone: one centred notice. */
    .npc-unavailable {
      display: flex; align-items: center; justify-content: center;
      width: 100%; height: 100%;
    }
    .npc-unavailable-body {
      padding: 40px; text-align: center;
      font-family: var(--font-ui); color: var(--text-success-active);
    }
    .npc-unavailable-title { font-size: var(--fs-title); font-weight: bold; margin-bottom: var(--sp-3); }
    .npc-unavailable-sub   { font-size: var(--fs-body); color: var(--text-text-alt-4); }

    /* The social web's zoom: the sizer takes the scaled diameter, the svg the
       scale itself, both as custom properties. */

    /* Backdrop, full-screen dim, centres the inner panel */
    #menu-container.npc-empathize-overlay {
      position: fixed !important;
      top: 0 !important; left: 0 !important;
      transform: none !important;
      width: 100vw !important; max-width: 100vw !important;
      height: 100vh !important; max-height: 100vh !important;
      background: var(--shadow-black-translucent-50) !important;
      border: none !important; border-radius: 0 !important; box-shadow: none !important;
      font-family: var(--font-ui) !important;
      color: var(--text-primary-hover) !important;
      overflow: hidden !important;
      z-index: 9999 !important;
      display: flex !important;
      align-items: center !important; justify-content: center !important;
      padding: 20px !important; box-sizing: border-box !important;
      /* Opens dim; .npc-shown fades it in one frame later and .npc-closing
         fades it back out on the way to being removed. */
      opacity: 0;
      transition: opacity 0.22s ease-out !important;
      /* Dragging over the panel used to paint the whole UI blue. Selection is
         off everywhere except the places worth copying: the chat log and the
         text fields. */
      user-select: none !important;
      -webkit-user-select: none !important;
    }
    #menu-container.npc-empathize-overlay #npc-dlg-chat,
    #menu-container.npc-empathize-overlay input,
    #menu-container.npc-empathize-overlay textarea,
    #menu-container.npc-empathize-overlay [contenteditable="true"] {
      user-select: text !important;
      -webkit-user-select: text !important;
    }
    #menu-container.npc-empathize-overlay.npc-shown { opacity: 1; }
    #menu-container.npc-empathize-overlay.npc-closing { opacity: 0; pointer-events: none; }
    /* Inner panel, parchment aesthetic matching project design language */
    .npc-empathize-inner {
      position: relative;
      /* Deliberately NOT full-bleed, unlike the shared spread. Empathize is a
         modal raised over the map rather than a menu that replaces it: the
         backdrop above is a 50% dim, not an opaque page, and the panel is meant
         to sit inside it with the map still legible around the edges. Taking
         this to var(--ui-panel-w/h) covered the map completely and lost that. */
      width: min(1500px, 100%);
      height: min(940px, 100%);
      /* No frame at all: the panel is a plain dark field and the tabs above it
         stand out on the dim like the labels of a folder. */
      background: transparent;
      border: none;
      border-radius: 0;
      box-shadow: none;
      display: flex; flex-direction: column;
      overflow: hidden; box-sizing: border-box;
      /* Same reasoning as .book-spread: the page is already built when this
         starts, so the duration is pure waiting. Kept in step with it. */
      animation: paperRustle 0.22s cubic-bezier(0.16, 1, 0.3, 1);
    }
    /* Mouse-only close (X). Not part of keyboard/gamepad nav on purpose. */
    .npc-close-btn {
      position: absolute; top: 8px; right: 10px; z-index: 50;
      width: 30px; height: 30px;
      display: flex; align-items: center; justify-content: center;
      font-size: var(--fs-title); line-height: 1; font-weight: bold;
      color: var(--text-text-alt-4);
      background: var(--bg-primary-hover-translucent-35);
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 50%;
      cursor: pointer;
      user-select: none; -webkit-user-select: none;
      transition: background 0.12s, color 0.12s, border-color 0.12s;
    }
    .npc-close-btn:hover {
      color: var(--text-primary-hover);
      background: var(--bg-danger-medium-7);
      border-color: var(--border-focus-hover);
    }
    .npc-panel-body {
      display: flex; flex: 1; overflow: hidden; min-height: 0;
      background: var(--bg-secondary-hover);
      box-shadow: 0 30px 75px var(--shadow-black-translucent-45);
    }
    /* ── Left column ───────────────────────────────────── */
    /* The column scrolls as one piece. The vitals block used to be the only
       scroller (flex: 1 inside an unbounded flex chain), which meant that when
       the portrait, the name and the character switcher above it were tall
       enough, whatever fell past the bottom edge could not be reached at all. */
    .npc-left-col {
      width: 360px; flex-shrink: 0;
      display: flex; flex-direction: column;
      min-height: 0; overflow-y: auto; overflow-x: hidden;
      overscroll-behavior: contain;
      scrollbar-width: thin; scrollbar-color: var(--border-focus-hover) transparent;
      background: transparent;
      border-right: 1px solid var(--border-primary-hover-translucent-15);
    }
    .npc-portrait-wrap { height: 290px; flex-shrink: 0; overflow: hidden; }
    .npc-left-ident {
      flex-shrink: 0;
      padding: 8px 12px 6px;
      background: var(--bg-secondary-hover);
      border-top: 1px solid var(--border-primary-hover-translucent-15);
      text-align: center;
    }
    .npc-left-name {
      font-size: var(--fs-title); font-weight: bold; line-height: 1.15;
      color: var(--text-primary-hover);
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    .npc-left-meta {
      font-size: var(--fs-body); margin-top: 2px;
      color: var(--text-text-alt-4);
    }
    .npc-portrait-wrap img {
      width: 100%; height: 100%;
      object-fit: contain;
      object-position: center;
      display: block;
      background: var(--bg-secondary-hover);
    }
    /* A creature's frame: the Battler3D viewer's canvas, sized to the same
       290px box the bust fills so the panel below it never shifts. */
    .npc-portrait-3d {
      display: flex; align-items: center; justify-content: center;
      background: var(--bg-secondary-hover);
    }
    .npc-portrait-canvas {
      width: 100%; height: 100%;
      display: block;
    }
    .npc-vitals-footer {
      padding: 7px 10px 12px;
      background: var(--bg-secondary-hover);
      border-top: 1px solid var(--border-primary-hover-translucent-15);
      /* Natural height: the whole left column is the scroller now. */
      flex: 0 0 auto;
    }
    .npc-vital-row { display: flex; align-items: center; gap: 5px; margin-bottom: 4px; font-size: var(--fs-body); }
    .npc-vital-lbl { width: 88px; flex-shrink: 0; overflow: hidden; white-space: nowrap; color: var(--text-text-alt-4); }
    .npc-vital-track { flex: 1; height: 6px; background: var(--border-primary-hover-translucent-15); border-radius: 3px; overflow: hidden; }
    .npc-vital-fill { height: 100%; border-radius: 3px; }
    .npc-vital-pct { width: 36px; text-align: right; flex-shrink: 0; font-size: var(--fs-body); color: var(--text-text-alt-4); }
    .npc-need-badge { display: flex; align-items: center; gap: 4px; font-size: var(--fs-body); color: var(--text-text-alt-4); margin-top: 2px; }
    /* ── Livestock block (an `animal: true` NPC, see AnimalGrowthSystem) ── */
    .npc-animal-panel {
      margin-top: 8px; padding-top: 7px;
      border-top: 1px solid var(--border-primary-hover-translucent-15);
    }
    .npc-animal-head {
      font-size: var(--fs-body); color: var(--text-primary-hover);
      margin-bottom: 4px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
    }
    .npc-animal-line { font-size: var(--fs-body); color: var(--text-text-alt-4); margin-bottom: 3px; }
    .npc-animal-sub {
      font-size: var(--fs-label); color: var(--text-text-alt-4);
      opacity: 0.8; margin: -2px 0 4px 92px;
    }
    .npc-animal-row { display: flex; align-items: center; gap: 5px; margin-bottom: 4px; font-size: var(--fs-body); }
    .npc-animal-label {
      width: 88px; flex-shrink: 0; overflow: hidden; white-space: nowrap;
      text-overflow: ellipsis; color: var(--text-text-alt-4);
    }
    .npc-animal-track {
      flex: 1; height: 6px; border-radius: 3px; overflow: hidden;
      background: var(--border-primary-hover-translucent-15);
    }
    .npc-animal-fill { height: 100%; border-radius: 3px; background: var(--text-primary-hover); }
    .npc-animal-fill.is-ready { background: var(--text-cost-ok); }
    .npc-animal-fill.is-low   { background: var(--text-text-alt-10); }
    .npc-animal-note {
      width: 74px; text-align: right; flex-shrink: 0;
      font-size: var(--fs-label); color: var(--text-text-alt-4);
      overflow: hidden; white-space: nowrap;
    }
    /* ── Action rows (used in the More tab list) ───────── */
    .npc-action-row {
      display: flex; align-items: center; gap: 7px;
      padding: 7px 12px;
      cursor: pointer;
      border: 1px solid transparent;
      border-bottom: 1px solid var(--npc-option-border);
      font-size: var(--fs-heading);
      color: var(--npc-option-fg);
      user-select: none; -webkit-user-select: none;
      transition: background 0.1s;
    }
    .npc-action-row:hover,
    .npc-action-row.npc-action-focused {
      border-color: var(--text-primary-hover);
    }
    .npc-action-row.npc-action-disabled { opacity: 0.36; cursor: default; pointer-events: none; }
    .npc-action-label { flex: 1; }
    .npc-action-arrow { font-size: var(--fs-label); color: var(--border-focus-hover); opacity: 0.7; }
    /* ── Right panel ───────────────────────────────────── */
    .npc-right-panel {
      flex: 1; overflow-y: auto; padding: 12px 18px 28px; min-width: 0; min-height: 0;
      scrollbar-width: thin; scrollbar-color: var(--border-focus-hover) transparent;
      overscroll-behavior: contain;
    }
    /* The chat takes the whole right page and lays it out as a column: the
       log, the actions and the input row, none of which scroll the page. */
    .npc-right-panel--chat {
      padding: 0; overflow: hidden;
      display: flex; flex-direction: column;
    }
    .npc-profile-name { font-size: var(--fs-title); font-weight: bold; margin-bottom: 1px; line-height: 1.2; color: var(--text-primary-hover); }
    .npc-profile-sub { font-size: var(--fs-heading); color: var(--text-text-alt-4); margin-bottom: 6px; }
    .npc-badge-row { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 6px; }
    .npc-badge {
      display: inline-flex; align-items: center; gap: 3px;
      background: var(--bg-primary-hover-translucent-35);
      border: 1px solid var(--border-primary-hover-translucent-15);
padding: 2px 8px; font-size: var(--fs-heading);
      color: var(--text-text-alt-4);
    }
    .npc-r-sep { border: none; border-top: 1px solid var(--border-primary-hover-translucent-15); margin: 6px 0; }
    .npc-sec-hdr {
      font-size: var(--fs-heading); font-weight: bold; letter-spacing: 0.09em;
      text-transform: uppercase; color: var(--text-text-alt-4); margin-bottom: 4px;
    }
    .npc-ident-row { display: flex; align-items: center; gap: 6px; margin-bottom: 2px; font-size: var(--fs-heading); color: var(--text-primary-hover); }
    .npc-tag-wrap { display: flex; flex-wrap: wrap; gap: 3px 14px; }
    /* Plain text, no chip. A page of traits, specializations, equipment and
       skills is a long list of short labels, and boxing every one of them turned
       the profile into a wall of frames. */
    .npc-tag {
      display: inline-flex; align-items: center; gap: 3px;
      padding: 1px 0; font-size: var(--fs-heading);
      color: var(--text-text-alt-4);
    }
    /* Predisposition */
    .npc-pred-row { display: flex; align-items: center; gap: 6px; margin-bottom: 2px; font-size: var(--fs-heading); }
    .npc-pred-name { width: 72px; flex-shrink: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-primary-hover); }
    .npc-pred-track { flex: 1; height: 5px; background: var(--border-primary-hover-translucent-15); border-radius: 3px; overflow: hidden; }
    .npc-pred-fill { height: 100%; border-radius: 3px; }
    .npc-pred-val { width: 30px; text-align: right; flex-shrink: 0; font-size: var(--fs-body); }
    /* Status / opinion */
    .npc-opinion-note { font-size: var(--fs-heading); color: var(--text-text-alt-11); margin-top: 2px; }
    /* Narrative, so it takes the measure every prose block in the game takes. */
    .npc-thought { font-style: normal; font-size: var(--fs-heading); color: var(--text-text-alt-4); margin-top: 4px; max-width: 68ch; }
    /* Stats */
    .npc-stats-row { font-size: var(--fs-heading); line-height: 1.6; color: var(--text-primary-hover); }
    .npc-hpmp { display: flex; align-items: center; gap: 5px; font-size: var(--fs-heading); margin-top: 2px; }
    .npc-hpmp-bar { display: inline-block; height: 7px; border-radius: 3px; }
    .npc-hpmp-bar--hp { background: var(--text-text-alt-5-hover); }
    .npc-hpmp-bar--mp { background: var(--border-blue-medium); }
    .npc-hpmp-val { font-size: var(--fs-heading); color: var(--text-text-alt-4); }
    /* Character sheet numbers in the left column, two per line. */
    .npc-stat-grid {
      display: grid; grid-template-columns: 1fr 1fr;
      column-gap: 10px; row-gap: 1px;
      margin: 2px 0 1px;
    }
    .npc-stat-cell {
      display: flex; align-items: baseline; justify-content: space-between;
      gap: 6px; font-size: var(--fs-body); min-width: 0;
    }
    .npc-stat-lbl {
      color: var(--text-text-alt-4);
      overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
    }
    .npc-stat-val { color: var(--text-primary-hover); flex-shrink: 0; }
    .npc-exp-section { margin-top: 4px; }
    .npc-exp-label { font-size: var(--fs-heading); color: var(--text-text-alt-4); }
    .npc-exp-track { height: 4px; background: var(--border-primary-hover-translucent-15); border-radius: 2px; overflow: hidden; margin-top: 2px; }
    .npc-exp-fill { height: 100%; background: var(--text-text-alt-17); border-radius: 2px; }
    /* Feedback messages */
    .npc-join-msg--spaced { margin: var(--sp-3) 16px 0; }
    .npc-join-msg { flex: 0 0 auto; font-size: var(--fs-body); padding: 5px 8px; border-radius: 3px; margin-bottom: 8px; }
    .npc-join-msg.accept {
      background: var(--bg-success-medium-8); color: var(--text-text-alt-11);
      border: 1px solid var(--border-success-green-25);
    }
    .npc-join-msg.reject {
      background: var(--bg-danger-medium-7); color: var(--text-text-alt-5-hover);
      border: 1px solid var(--border-danger-medium-22);
    }
    /* ── Chat panel ────────────────────────────────────── */
    .npc-chat-panel { display: flex; flex-direction: column; flex: 1; min-height: 0; }
    .npc-chat-header {
      display: flex; justify-content: space-between; align-items: center;
      padding: 10px 16px 9px;
      border-bottom: none;
      flex-shrink: 0; font-weight: bold; font-size: var(--fs-heading);
      color: var(--text-primary-hover);
    }
    .npc-back-btn { font-size: var(--fs-heading); color: var(--text-text-alt-4); cursor: pointer; font-weight: normal; }
    .npc-back-btn:hover { color: var(--border-focus-hover); }
    .npc-chat-bubbles {
      flex: 1 1 0; min-height: 0; overflow-y: auto; overflow-x: hidden;
      padding: 10px 16px;
      display: flex; flex-direction: column; gap: 7px;
      overscroll-behavior: contain;
      /* The global 6px scrollbar is too thin to grab in a chat log, and Firefox's
         `scrollbar-width: thin` would suppress the ::-webkit- rules below, so this
         box opts back out of it and paints its own wider bar. */
      scrollbar-width: auto; scrollbar-color: var(--border-focus-hover) transparent;
    }
    /* Once _sizeChatLog has measured the panel it fixes the log at that height
       so the input row below it can never be pushed off the bottom edge. */
    .npc-chat-bubbles--sized {
      flex: 0 0 auto; box-sizing: border-box;
      height: var(--npc-chat-h, auto); min-height: 0; overflow-y: auto;
    }
    .npc-chat-bubbles::-webkit-scrollbar { width: 12px !important; }
    .npc-chat-bubbles::-webkit-scrollbar-track {
      background: var(--shadow-primary-hover-translucent-5) !important;
    }
    .npc-chat-bubbles::-webkit-scrollbar-thumb {
      background: var(--border-focus-hover) !important;
      border-radius: 6px !important;
      border: 3px solid transparent !important;
      background-clip: padding-box !important;
    }
    /* Bubbles must never be squeezed by the column flex layout, they have to
       overflow so the log scrolls instead of clipping the newest message. */
    .npc-bubble {
      flex: 0 0 auto;
      max-width: 84%; padding: 9px 13px; border-radius: 10px;
      font-size: var(--fs-body); line-height: 1.55; word-break: break-word;
    }
    /* The party's own line. It used to be stamped as a solid gold plate with
       black text, the loudest thing on the panel and the only place in the game
       a body of prose is printed inverted; it takes the quiet tint and the
       accent ink every other marked-out element wears. */
    .npc-bubble-player {
      align-self: flex-end;
      text-align: right;
      background: none;
      border: none;
      color: var(--chip-active-fg);
    }
    .npc-bubble-npc {
      align-self: flex-start;
      background: none;
      border: none;
      color: var(--text-primary-hover);
    }
    .npc-bubble-name { display: block; font-size: var(--fs-label); font-weight: bold; color: var(--text-text-alt-4); margin-bottom: 3px; }
    .npc-bubble-convo {
      align-self: stretch; max-width: 100%;
      background: none;
      border: none;
      color: var(--text-primary-hover);
      font-style: normal;
    }
    .npc-convo-line { margin-top: 3px; font-style: normal; }
    .npc-convo-speaker { font-weight: bold; font-style: normal; color: var(--text-text-alt-4); }
    .npc-convo-partner { cursor: pointer; text-decoration: underline; }
    .npc-typing { color: var(--text-text-alt-4); font-style: normal; }
    .npc-chat-input-row {
      display: flex; gap: 6px; padding: 8px 16px;
      border-top: none; flex-shrink: 0;
    }
    .npc-chat-elsewhere {
      padding: 10px 16px;
      border-top: none; flex-shrink: 0;
      font-style: normal; opacity: 0.6; text-align: center;
    }
    .npc-chat-input {
      flex: 1; padding: 7px 11px;
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px;
      background: var(--bg-primary-hover-translucent-35);
      font-family: var(--font-ui); font-size: var(--fs-body);
      color: var(--text-primary-hover); outline: none;
      pointer-events: auto;
      user-select: text !important;
      -webkit-user-select: text !important;
    }
    .npc-chat-input:focus { border-color: var(--border-focus-hover); background: var(--bg-white-translucent-72); }
    .npc-chat-send {
      padding: 7px 14px;
      background: var(--border-focus-hover); color: var(--bg-secondary-hover);
      border: none; border-radius: 4px;
      font-family: var(--font-ui); cursor: pointer; font-size: var(--fs-body);
      pointer-events: auto;
    }
    .npc-chat-send:hover { opacity: 0.85; }
    /* ── "Type something" launcher button (opens the chat modal) ─────────── */
    .npc-chat-open-modal {
      flex: 1; display: flex; align-items: center; gap: 8px;
      padding: 9px 12px;
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px;
      background: var(--bg-primary-hover-translucent-35);
      font-family: var(--font-ui); font-size: var(--fs-body);
      color: var(--text-text-alt-4); cursor: text; text-align: left;
      pointer-events: auto; transition: border-color 0.12s, background 0.12s;
    }
    .npc-chat-open-modal:hover {
      border-color: var(--border-focus-hover);
      background: var(--bg-white-translucent-72);
      color: var(--text-primary-hover);
    }
    .npc-chat-open-modal-icon { flex-shrink: 0; opacity: 0.8; }
    .npc-chat-open-modal-label { flex: 1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
    /* ── Chat text-entry modal ──────────────────────────────────────────── */
    .npc-chat-modal-backdrop {
      position: absolute; top: 0; right: 0; bottom: 0; left: 0; z-index: 40;
      display: flex; align-items: center; justify-content: center;
      background: var(--shadow-black-translucent-50);
      animation: paperRustle 0.2s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .npc-chat-modal {
      width: min(560px, 82%);
      background: var(--bg-secondary-hover);
      border: 4px double var(--text-primary-hover);
      border-radius: 5px;
      box-shadow: 0 24px 60px var(--shadow-black-translucent-45);
      padding: 16px 18px 14px;
      display: flex; flex-direction: column; gap: 12px;
    }
    .npc-chat-modal-title {
      font-size: var(--fs-title); font-weight: bold;
      color: var(--text-primary-hover);
      border-bottom: none; padding-bottom: 8px;
    }
    .npc-chat-modal-input {
      width: 100%; box-sizing: border-box; resize: none;
      padding: 10px 12px; min-height: 84px;
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px;
      background: #000;
      font-family: var(--font-ui); font-size: var(--fs-heading); line-height: 1.4;
      color: #fff; outline: none;
      pointer-events: auto;
      user-select: text !important; -webkit-user-select: text !important;
    }
    .npc-chat-modal-input:focus { border-color: var(--border-focus-hover); }
    .npc-chat-modal-btns { display: flex; justify-content: flex-end; gap: 10px; }
    .npc-chat-modal-cancel, .npc-chat-modal-send {
      padding: 8px 18px; border-radius: 4px;
      font-family: var(--font-ui); font-size: var(--fs-body); cursor: pointer;
      pointer-events: auto; border: 1px solid var(--border-primary-hover-translucent-15);
    }
    .npc-chat-modal-cancel {
      background: transparent; color: var(--text-text-alt-4);
    }
    .npc-chat-modal-cancel:hover { color: var(--text-primary-hover); border-color: var(--border-focus-hover); }
    .npc-chat-modal-send {
      background: var(--border-focus-hover); color: var(--bg-secondary-hover); border: none;
    }
    .npc-chat-modal-send:hover { opacity: 0.85; }
    /* ── Shared top-header for sub-panels ──────────────── */
    .npc-panel-top-hdr { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
    /* ── Social web (inline SVG graph, fullscreen on the right page) ───── */
    /* The wrapper is a flex column filling the right panel's own height, so
       the stage (the only element allowed to grow) takes up whatever is left
       once the title and legend have taken their own space. Zooming in grows
       the sizer past the stage, which is what makes scrollLeft/scrollTop (i.e.
       dragging, the wheel, or L2/R2) a real pan; see NPCEmpathizeUI.js. */
    .npc-web-fullscreen { display: flex; flex-direction: column; height: 100%; }
    .npc-web-stage {
      flex: 1; min-height: 240px; width: 100%;
      border: 2px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px;
      background: transparent;
      overflow: auto;
      cursor: grab;
      scrollbar-width: thin; scrollbar-color: var(--border-focus-hover) transparent;
      overscroll-behavior: contain;
    }
    .npc-web-stage--dragging { cursor: grabbing; }
    /* The zoom arrives as a custom property, so the stylesheet still owns
       every declaration the stage and its svg are drawn with. */
    .npc-web-sizer { position: relative; margin: auto; width: var(--npc-web-w, 0px); height: var(--npc-web-h, 0px); }
    .npc-web-svg { display: block; transform-origin: 0 0; transform: scale(var(--npc-web-zoom, 1)); }
    .npc-web-zoom-controls { display: flex; align-items: center; gap: 4px; margin-left: auto; }
    .npc-web-zoom-btn {
      display: flex; align-items: center; justify-content: center;
      width: 22px; height: 22px; border-radius: 4px; cursor: pointer;
      border: 1px solid var(--border-primary-hover-translucent-15);
      color: var(--text-text-alt-4); font-weight: bold; user-select: none;
    }
    .npc-web-zoom-btn:hover { border-color: var(--border-focus-hover); color: var(--text-primary-hover); }
    .npc-web-node { cursor: pointer; }
    .npc-web-node--center { cursor: default; }
    .npc-web-disc { fill: var(--bg-secondary-hover); }
    .npc-web-rim  { fill: none; stroke: var(--border-primary-hover-translucent-15); stroke-width: 2; }
    .npc-web-node--center .npc-web-rim { stroke: var(--border-focus-hover); stroke-width: 3; }
    .npc-web-node:hover .npc-web-rim   { stroke: var(--border-focus-hover); stroke-width: 3; }
    .npc-web-initial {
      fill: var(--text-primary-hover); font-family: var(--font-ui); font-weight: bold;
      text-anchor: middle; dominant-baseline: central;
    }
    .npc-web-label {
      fill: var(--text-primary-hover); font-family: var(--font-ui); font-size: var(--fs-label);
      text-anchor: middle; pointer-events: none;
    }
    .npc-web-node--center .npc-web-label { font-weight: bold; fill: var(--border-focus-hover); }
    .npc-web-tally circle {
      fill: var(--bg-secondary-hover); stroke: var(--border-primary-hover-translucent-15); stroke-width: 1;
    }
    .npc-web-tally text {
      fill: var(--text-text-alt-4); font-family: var(--font-ui); font-size: var(--fs-caption);
      text-anchor: middle; dominant-baseline: central;
    }
    /* Web legend */
    .npc-web-legend { display: flex; flex-shrink: 0; gap: 14px; font-size: var(--fs-label); color: var(--text-text-alt-4); margin-top: 6px; }
    .npc-web-legend > .npc-web-zoom-controls:first-child { margin-left: auto; }
    .npc-legend-item { display: flex; align-items: center; gap: 5px; }
    .npc-legend-line { display: inline-block; width: 22px; height: 3px; border-radius: 2px; }
    .npc-legend-line--single { background: transparent; border-top: 1px solid var(--border-primary-hover-translucent-15); }
    .npc-legend-line--multi  { background: var(--text-primary-hover); }
    /* Steal / Gift / Bribe items */
    .npc-steal-item {
      display: flex; align-items: center; gap: 7px;
      padding: 8px 11px;
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px; margin-bottom: 4px;
      cursor: pointer; font-size: var(--fs-body);
      color: var(--text-primary-hover);
      background: var(--bg-primary-hover-translucent-35);
    }
    .npc-steal-item:hover { border-color: var(--border-focus-hover); }
    .npc-steal-item.done { opacity: 0.42; cursor: default; pointer-events: none; }
    .npc-action-disabled { opacity: 0.36; cursor: default; pointer-events: none; }
    /* Routine / Life History rows */
    .npc-routine-row, .npc-life-row {
      display: flex; align-items: center; gap: 8px;
      padding: 4px 0;
      border: none;
      border-radius: 0; margin-bottom: 1px;
      font-size: var(--fs-body);
      color: var(--text-primary-hover);
      background: none;
    }
    /* Timeline rows read as a list, not a stack of cards: no frame, no fill. */
    .npc-life-row { border: none; background: none; padding: 4px 0; border-radius: 0; }
    /* A power's roll of leaders is a list, not a stack of cards: no frame and
       no fill, so the names carry it. */
    /* The eight parameters on a leader's sheet, laid out the way the status
       screen lays them out rather than as eight more bars. */
    .npc-param-grid {
      display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
      gap: 2px 14px; margin: 4px 0 6px;
    }
    .npc-param-cell {
      display: flex; justify-content: space-between; align-items: baseline;
      gap: 8px; font-size: var(--fs-body); color: var(--text-primary-hover);
    }
    /* The sentence under a platform's policy: what that position means. */
    .npc-policy-desc {
      font-size: var(--fs-label); color: var(--text-text-alt-4);
      margin: 0 0 6px 23px;
    }
    .npc-life-row--plain {
      border: none; background: none; padding: 2px 0; border-radius: 0;
    }
    .npc-routine-row.past   { opacity: 0.68; }
    .npc-routine-row.now    {
      border-color: var(--border-focus-hover);
      border-left: 4px solid var(--border-focus-hover);
      opacity: 1; font-weight: bold;
      box-shadow: 0 0 6px var(--border-primary-hover-translucent-15);
    }
    .npc-routine-row.now .npc-routine-hour::before { content: '▶ '; font-size: var(--fs-label); }
    .npc-routine-hour, .npc-life-time {
      flex: 0 0 auto; min-width: 48px; opacity: 0.85; font-variant-numeric: tabular-nums; font-weight: bold;
    }
    /* A log stamp is a whole date now, not a day number. */
    .npc-life-time { min-width: 104px; }
    /* How many times one line stands for, on a day that repeated it. */
    .npc-life-count { opacity: 0.7; font-variant-numeric: tabular-nums; }
    .npc-routine-sub-hdr {
      font-size: var(--fs-heading); opacity: 0.8; text-transform: uppercase; letter-spacing: 0.04em;
      margin: 12px 0 5px;
    }
    /* Biologics tab */
    .npc-bio-archetype { font-size: var(--fs-body); margin-bottom: 8px; opacity: 0.85; }
    .npc-bio-vitals {
      border: none;
      border-radius: 0; padding: 4px 0 8px; margin-bottom: 4px;
      background: none;
    }
    .npc-bio-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 10px; }
    .npc-bio-part {
      display: flex; align-items: center; gap: 8px;
      padding: 3px 0;
      border: none;
      border-radius: 0;
      font-size: var(--fs-label);
      color: var(--text-primary-hover);
      background: none;
    }
    .npc-bio-part-name { flex: 0 0 38%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .npc-bio-vital-tag {
      font-size: var(--fs-caption); text-transform: uppercase; letter-spacing: 0.05em;
      margin-left: 6px; padding: 0 4px;      border: 1px solid var(--border-npc-red); color: var(--text-text-alt-10);
    }
    .npc-bio-missing { opacity: 0.55; }
    .npc-bio-missing .npc-bio-part-name { text-decoration: line-through; }
    .npc-bio-missing-lbl { font-style: normal; opacity: 0.8; }
    /* ── Folder-bookmark tab bar ───────────────────────── */
    .npc-tab-bar {
      display: flex; gap: 4px;
      padding: 0 16px 0;
      /* Nothing behind the labels: they stick out of the panel below them the
         way the tabs of a folder stick out of the folder. */
      background: none;
      border-bottom: none;
      flex-shrink: 0;
    }
    .npc-tab {
      padding: 7px 18px 8px;
      font-size: var(--fs-body);
      cursor: pointer; user-select: none; -webkit-user-select: none;
      border: none;
      border-radius: 6px 6px 0 0;
      background: var(--bg-secondary-hover);
      color: var(--text-text-alt-4);
      position: relative; top: 0;
      transition: color 0.12s;
    }
    .npc-tab:hover:not(.active) { color: var(--border-focus-hover); }
    .npc-tab.active {
      background: var(--bg-secondary-hover);
      color: var(--text-primary-hover);
      font-weight: bold;
    }
    .npc-tab-bar--focused .npc-tab.active {
      box-shadow: inset 0 0 0 2px var(--border-focus-hover);
    }
    /* "L1 R1" / "TAB" chip in front of the first tab: names the only control
       that changes tab, now that the directions stay inside the open one. Not
       clickable, so it is skipped by every focus ring. */
    .npc-tab-hint {
      align-self: flex-end;
      margin-right: 6px;
      padding: 5px 9px 6px;
      font-size: var(--fs-chip);
      font-weight: bold;
      letter-spacing: 0.06em;
      color: var(--text-text-alt-4);
      border: none;
      border-radius: 4px;
      background: var(--bg-primary-hover-translucent-35);
      user-select: none; -webkit-user-select: none;
      pointer-events: none;
      white-space: nowrap;
    }
    /* ── Character switcher (which party member is interacting) ──
       The names are clickable, and SHIFT / SELECT steps through them; the chip
       at the end of the row names whichever of those two the player is holding
       (NPCEmpathize.js keeps it in step when a pad is plugged in or unplugged).
       Selected reads as the panel's own gold, the unselected ones a step down
       from it, so which member owns the reputation on screen is never in doubt. */
    .npc-focus-switcher {
      display: flex; flex-wrap: wrap;
      align-items: center; justify-content: center;
      gap: 5px;
      margin: 2px 0 6px;
    }
    .npc-focus-switcher-lbl {
      width: 100%;
      text-align: center;
      font-size: var(--fs-label);
      color: var(--text-text-alt-4);
    }
    .npc-focus-chip {
      cursor: pointer;
      padding: 3px 9px;
      font-size: var(--fs-label);
      white-space: nowrap;
      color: var(--text-text-alt-2);
      border: 1.5px solid var(--border-primary-hover-translucent-15);
      background: transparent;
      transition: background 0.1s, color 0.1s;
    }
    .npc-focus-chip:hover {
      background: var(--bg-primary-hover-translucent-35);
    }
    .npc-focus-chip.on {
      font-weight: bold;
      color: var(--text-primary-hover);
      border-color: var(--text-primary-hover);
      background: var(--bg-primary-hover-translucent-35);
    }
    /* The shared .char-switch-hint sits at 0.732rem/0.7 opacity, which this
       panel's black page turns into a smudge. */
    .npc-focus-hint {
      font-size: var(--fs-chip);
      opacity: 0.9;
    }
    .npc-chat-send.npc-zone-focused {
      outline: 2px solid var(--border-focus-hover);
      outline-offset: 2px;
    }
    /* ── Chat action buttons (former left-column actions) ─ */
    .npc-chat-actions-row {
      display: flex; flex-wrap: wrap; gap: 6px;
      padding: 8px 16px;
      border-top: none;
      flex-shrink: 0;
      /* A long action list (socialize/gift/bribe/attack/... plus the inline
         directions, gift and steal item lists) must not eat the whole panel and
         leave the chat log a single message tall. It only ever takes the height
         it needs, this is purely the ceiling. `_sizeChatLog` re-states it in
         pixels each render, because a percentage silently stops constraining
         anything if a link of the flex chain above loses its definite height. */
      max-height: var(--npc-actions-max, 45%); overflow-y: auto; overscroll-behavior: contain;
      scrollbar-width: auto; scrollbar-color: var(--border-focus-hover) transparent;
    }
    .npc-chat-actions-row::-webkit-scrollbar { width: 10px !important; }
    .npc-chat-actions-row::-webkit-scrollbar-track {
      background: var(--shadow-primary-hover-translucent-5) !important;
    }
    .npc-chat-actions-row::-webkit-scrollbar-thumb {
      background: var(--border-focus-hover) !important;
      border-radius: 5px !important;
      border: 3px solid transparent !important;
      background-clip: padding-box !important;
    }
    /* Every offered line, in the standing verb list and in every submenu, wears
       the one option colour (gold under Omega Tower, crimson ink under Archive
       Foundation). Only the trailing badges - odds, ♥ deltas, prices - still
       carry a colour of their own, since those read as data, not as choices. */
    .npc-chat-action-btn {
      display: inline-flex; align-items: center; gap: 5px;
      padding: 5px 11px;
      border: 1px solid var(--npc-option-border);
      border-radius: 14px;
      /* No plate behind an option: the ground is the page. */
      background: none;
      font-size: var(--fs-body); color: var(--npc-option-fg);
      cursor: pointer; user-select: none; -webkit-user-select: none;
      transition: background 0.1s, border-color 0.1s;
    }
    .npc-chat-action-btn .npc-opt-label { color: var(--npc-option-fg); }
    /* A tinted border alone was not enough to find the cursor inside the long
       pickers (Socialize, Court), where every row already carries badges of its
       own colour - odds, ♥ deltas - and the borders all sit at the same weight.
       The selected row is therefore inked in: highlighter fill, a solid ring in
       the option colour, bold text and a ▸ in the gutter, so it reads as chosen
       from across the panel rather than on close inspection. Mouse hover shares
       this exact look rather than its own fainter one: the JS mirrors the two
       into a single cursor (see _updateSelectionHighlight's onmouseenter), so a
       hovered row and a keyboard/pad-selected row must render identically or
       the highlight would appear to jump when the pointer sits still. */
    .npc-chat-action-btn:hover:not(.npc-action-disabled),
    .npc-chat-action-btn.npc-action-focused {
      border-color: var(--text-primary-hover);
      font-weight: bold;
    }
    .npc-chat-action-btn:hover:not(.npc-action-disabled)::before,
    .npc-chat-action-btn.npc-action-focused::before {
      content: '\25B8';
      font-size: var(--fs-label); line-height: 1;
      color: var(--npc-option-fg);
    }
    /* The label rides the row's own weight, or the bold above stops at the span. */
    .npc-chat-action-btn:hover:not(.npc-action-disabled) .npc-opt-label,
    .npc-chat-action-btn.npc-action-focused .npc-opt-label { font-weight: inherit; }
    /* ── Wiki (entity profiles & hyperlinks) ───────────── */
    .npc-wiki-link {
      color: var(--border-focus-hover);
      cursor: pointer;
      text-decoration: underline;
      text-underline-offset: 2px;
    }
    .npc-wiki-link:hover { text-decoration-style: solid; }
    /* The panel's back control sits in the tab bar but is a back chip, not a
       tab: same look as every other "back" in these menus, lined up with the
       tabs beside it. */
    .npc-back-btn.npc-tab-back {
      display: inline-flex; align-items: center;
      padding: 6px 12px; margin-right: 4px;
      white-space: nowrap;
    }
    .npc-entity-emblem {
      width: 130px; height: 130px;
      margin: 28px auto 8px;
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: var(--fs-display); font-weight: bold;
      font-family: var(--font-ui);
      border: 5px double var(--text-primary-hover);
      background: var(--bg-primary-hover-translucent-35);
      color: var(--text-primary-hover);
      box-shadow: inset 0 0 24px var(--border-primary-hover-translucent-15);
      flex-shrink: 0;
      user-select: none; -webkit-user-select: none;
    }
    .npc-emblem-power    { border-color: var(--text-text-alt-17); color: var(--text-gold-dark); }
    .npc-emblem-nation   { border-color: var(--text-forest-green); color: var(--text-cost-ok); }
    .npc-emblem-leader   { border-color: var(--border-purple-medium); color: var(--text-text-alt-19); }
    .npc-emblem-artifact { border-color: var(--border-blue-medium); color: var(--text-text-alt-16); }
    .npc-emblem-faction  { border-color: var(--text-blood-red); color: var(--text-text-alt-10); }
    .npc-sec-hdr--spaced {
      margin-top: 6px;
    }
    .npc-entity-kicker {
      text-align: center;
      font-size: var(--fs-label); letter-spacing: 0.16em; text-transform: uppercase;
      color: var(--text-text-alt-4);
    }
    .npc-entity-title {
      text-align: center;
      font-size: var(--fs-title); font-weight: bold; line-height: 1.25;
      padding: 0 12px 6px;
      color: var(--text-primary-hover);
    }
    .npc-dead-badge {
      display: block; margin: 4px auto 6px; width: fit-content;
      background: var(--bg-crime-dark-10);
      border: 1px solid var(--border-npc-danger-38);
      color: var(--text-text-alt-10);
padding: 2px 10px;
      font-size: var(--fs-label);
    }
    /* The way out of a world leader's article and into the person it is about.
       Every leader in the book is a simulated character, on a map or not, and
       this button opens the ordinary Empathize panel on them; the line under it
       says which version of them will be there. */
    .npc-entity-empathize {
      display: flex; flex-direction: column; align-items: center; gap: 4px;
      padding: 2px 10px 8px;
      flex-shrink: 0;
    }
    .npc-entity-empathize-note {
      text-align: center;
      font-size: var(--fs-chip); font-style: italic;
      color: var(--text-text-alt-4);
    }
    /* ── Wiki index tab (category & entry grids) ───────── */
    /* Wider tiles (fewer per row). The grid is NOT its own scroller: it used to
       be capped at a hand-counted `calc(100vh - 320px)`, which at most window
       sizes is taller than the space the panel actually leaves it, so the box
       ran off the bottom of the page and the rows past the edge could not be
       reached by any wheel tick. The right page scrolls instead, and the
       category header stays pinned to the top of it. */
    .npc-wiki-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
      gap: 8px;
      min-height: 0;
      padding-right: 6px;
    }
    /* Pinned to the top of the scrolling right page, so the category name and
       the way back out stay put while the list moves under them. */
    .npc-wiki-hdr {
      position: sticky; top: 0; z-index: 3;
      background: var(--bg-secondary-hover);
    }
    .npc-wiki-grid--cards {
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 6px;
    }
    .npc-wiki-card {
      display: flex; flex-direction: row; align-items: center; gap: 8px;
      padding: 5px 10px;
      border: 1px solid transparent;
      border-radius: 4px;
      background: none;
      cursor: pointer; user-select: none; -webkit-user-select: none;
      transition: color 0.12s, transform 0.12s;
    }
    .npc-wiki-card:hover { transform: translateY(-2px); }
    .npc-wiki-card:hover .npc-wiki-card-label,
    .npc-wiki-card:hover .npc-wiki-card-glyph { color: var(--border-focus-hover); }
    .npc-wiki-card-glyph {
      font-size: var(--fs-body); line-height: 1; color: var(--text-primary-hover);
      flex: 0 0 auto;
    }
    .npc-wiki-card-label {
      font-size: var(--fs-body); font-weight: bold; color: var(--text-primary-hover);
      flex: 1 1 auto; min-width: 0;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
      text-align: left;
    }
    .npc-wiki-card-count {
      font-size: var(--fs-label); color: var(--text-text-alt-4);
      flex: 0 0 auto; margin-left: auto;
    }
    /* Party rows sit indented under their nation's heading in a bloc's chamber */
    .npc-wiki-party-row { padding-left: 16px; }
    .npc-wiki-entry {
      display: flex; flex-direction: column; gap: 1px;
      padding: 5px 4px;
      border: 1px solid transparent;
      border-radius: 4px;
      background: none;
      cursor: pointer; user-select: none; -webkit-user-select: none;
      transition: color 0.1s;
      min-width: 0;
    }
    .npc-wiki-entry:hover .npc-wiki-entry-name { color: var(--border-focus-hover); }
    /* Selected wiki category header, plain text: no frame around it */
    .npc-sec-hdr.npc-wiki-cat-selected {
      display: inline-block;
      border: none;
      padding: 3px 0;
      box-shadow: none;
    }
    /* The category currently open (or last opened) keeps a gold border on the
       card grid, so stepping back out of a category still shows where you were.
       --accent-gold-pure rather than --border-focus-hover: the latter is brown
       in the parchment themes, and this marker has to read as gold everywhere. */
    .npc-wiki-card.npc-wiki-card-selected .npc-wiki-card-label,
    .npc-wiki-card.npc-wiki-card-selected .npc-wiki-card-glyph {
      color: var(--accent-gold-pure);
    }
    /* Keyboard / controller focus ring for in-panel grid navigation */
    .npc-wiki-card.npc-content-focused,
    .npc-wiki-entry.npc-content-focused {
      border-color: var(--accent-gold-pure);
      box-shadow: inset 0 0 0 2px var(--accent-gold-pure);
      transform: translateY(-2px);
    }
    .npc-back-btn.npc-content-focused {
      color: var(--border-focus-hover);
      outline: 2px solid var(--border-focus-hover);
      outline-offset: 2px;
      border-radius: 3px;
    }
    .npc-wiki-entry-name {
      font-size: var(--fs-body); color: var(--text-primary-hover);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .npc-wiki-entry-sub {
      font-size: var(--fs-label); color: var(--text-text-alt-4);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    /* ── Detailed character creation (CharacterCreationFull.js) ──────────
       The Create tab turns the profile into an editable sheet: one row per
       field, label left, current value right, and the same in-panel content
       focus ring the Wiki grid uses. */
    .npc-cc-hint {
      font-size: var(--fs-body); font-style: normal; color: var(--text-text-alt-4);
      margin: 2px 0 6px;
    }
    .npc-cc-row {
      display: flex; align-items: baseline; gap: 8px;
      padding: 6px 9px;
      border: 1px solid transparent;
      border-bottom: 1px solid var(--border-primary-hover-translucent-15);
      cursor: pointer; user-select: none; -webkit-user-select: none;
      font-size: var(--fs-heading); color: var(--text-primary-hover);
      transition: background 0.1s, border-color 0.1s;
      min-width: 0;
    }
    .npc-cc-row:hover,
    .npc-cc-row.npc-content-focused {
      border-color: var(--text-primary-hover);
      border-radius: 4px;
    }
    .npc-cc-row-lbl { flex: 0 0 42%; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .npc-cc-row-val {
      flex: 1 1 auto; min-width: 0; text-align: right;
      color: var(--text-text-alt-4);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .npc-cc-row-sub {
      flex: 1 1 auto; min-width: 0; text-align: right;
      font-size: var(--fs-label); font-style: normal; color: var(--text-text-alt-4);
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
    }
    .npc-cc-row-arrow { flex: 0 0 auto; font-size: var(--fs-label); color: var(--border-focus-hover); opacity: 0.75; }
    /* Small per-row reroll button beside a "pick" row's value, left of the
       arrow. Its own mousedown handler stops propagation so it never also
       opens the row's picker. */
    .npc-cc-row-rand {
      flex: 0 0 auto;
      font-size: var(--fs-chip); text-transform: uppercase; letter-spacing: 0.02em;
      padding: 1px 7px;
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 10px;
      color: var(--text-text-alt-4);
      opacity: 0.8;
      cursor: pointer;
    }
    .npc-cc-row-rand:hover {
      opacity: 1;
      color: var(--text-primary-hover);
      border-color: var(--border-focus-hover);
      background: var(--bg-primary-hover-translucent-35);
    }
    /* Running total carried by a picker: the specialization point budget, the
       only place those points are shown. */
    .npc-cc-note {
      font-size: var(--fs-body); font-weight: bold;
      color: var(--text-primary-hover);
      background: var(--bg-primary-hover-translucent-35);
      border: 1px solid var(--border-primary-hover-translucent-15);
      border-radius: 4px;
      padding: 3px 9px; margin: 0 0 6px;
      display: inline-block;
    }
    /* A level the character cannot afford yet: still readable, not clickable. */
    .npc-cc-row--spent { opacity: 0.42; }
    .npc-cc-row--spent:hover { background: none; }
    /* The row that ends creation, marked out from the fields above it. */
    .npc-cc-row--primary {
      font-weight: bold;
      border: 2px solid var(--accent-gold-pure);
      border-radius: 6px;
      margin-top: 6px;
    }
    /* The portrait is a button in the editor: it opens the sprite grid, and
       through it the bust gallery and the 3D model editor. */
    .npc-portrait-wrap.npc-cc-portrait { cursor: pointer; }
    .npc-portrait-wrap.npc-cc-portrait:hover {
      outline: 2px solid var(--border-focus-hover);
      outline-offset: -2px;
    }

/* ── Mod Manager ─────────────────────────────────────────────────────────── */
#mod-manager-container {
    position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 200;
    display: flex; align-items: center; justify-content: center;
    background: var(--shadow-black-translucent-55);
    font-family: var(--font-ui);
}
.mod-list {
    display: flex; flex-direction: column;
    overflow-y: auto; flex: 1;
    gap: 4px; padding: 8px 4px;
}
.mod-list::-webkit-scrollbar { width: 6px; }
.mod-list::-webkit-scrollbar-track { background: transparent; }
.mod-list::-webkit-scrollbar-thumb { background: var(--border-focus-hover); border-radius: 3px; }
.mod-slot {
    display: flex; align-items: center; gap: 10px;
    padding: 8px 12px;
    border: 1px solid var(--border-primary-hover-translucent-15);
    background: var(--bg-primary-hover-translucent-35);
    cursor: pointer; -webkit-user-select: none; user-select: none;
    transition: border-color 0.12s, box-shadow 0.12s;
}
.mod-slot:hover,
.mod-slot.selected {
    border-color: var(--border-focus-hover);
    box-shadow: 0 0 0 1.5px var(--border-focus-hover);
    background: var(--bg-focus-hover-translucent-15);
}
.mod-slot-order {
    font-size: 0.82em; color: var(--text-text-alt-4);
    min-width: 22px; text-align: right; flex-shrink: 0;
}
.mod-slot-status {
    font-size: 0.856em; font-weight: bold;
    min-width: 72px; flex-shrink: 0;
}
.mod-slot-status--on  { color: var(--text-text-alt-11); }
.mod-slot-status--off { color: var(--text-text-alt-5-hover); }
.mod-slot-name {
    font-size: 1.048em; color: var(--text-primary-hover);
    overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1;
}
.mod-hint-bar {
    font-size: 0.798em; color: var(--text-text-alt-4);
    text-align: center; padding: 6px 8px; flex-shrink: 0;
    border-top: none;
    font-style: normal;
}
.mod-path-value {
    font-size: var(--fs-detail-body); word-break: break-all;
}

/* ── Game Updater ────────────────────────────────────────────────────────── */
#game-updater-container {
    position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 200;
    display: flex; align-items: center; justify-content: center;
    background: var(--shadow-black-translucent-55);
    font-family: var(--font-ui);
    opacity: 0;
    transition: opacity 0.22s ease-out;
}
/* Opening and leaving, said as states rather than written a property at a
   time from the scene. */
#game-updater-container.gu-shown { opacity: 1; }
#game-updater-container.gu-closing { opacity: 0; pointer-events: none; transition: opacity 0.2s ease-out; }

/* The notice standing over everything while the game closes to apply a build. */
#gu-closing-notice {
    position: fixed; left: 0; top: 0; width: 100%; height: 100%;
    z-index: 100000; display: flex;
    align-items: center; justify-content: center; text-align: center;
    padding: 0 6%; box-sizing: border-box;
    background: var(--shadow-black-translucent-95);
    color: var(--text-gold-dark);
    font-family: var(--font-ui);
    font-size: var(--fs-detail-title);
    font-weight: bold; letter-spacing: 0.08em;
    -webkit-user-select: none; user-select: none;
    opacity: 0; transition: opacity 0.18s ease-out;
}
#gu-closing-notice.gu-shown { opacity: 1; }

/* The channel strip wears the shared tab; only the branch line under the
   name is the updater's own. */
.gu-tab { flex-direction: column; gap: 1px; }
.gu-tab-name { font-weight: bold; letter-spacing: 0.08em; }
.gu-tab-branch { font-family: var(--font-mono); font-size: var(--fs-caption); opacity: 0.7; }

/* A build is a shared list row: the version on the first line, the commit,
   the date and whoever built it on the second. */
.gu-build .item-slot-meta { font-family: var(--font-mono); }
.gu-chip--major { color: var(--text-text-alt-5-hover); font-weight: bold; }
.gu-badge {
    font-size: var(--fs-caption); font-weight: bold; letter-spacing: 0.05em;
    flex-shrink: 0;
}
.gu-badge--ok   { color: var(--text-text-alt-11); }
.gu-badge--new  { color: var(--text-gold-dark); }
.gu-badge--bad  { color: var(--text-text-alt-5-hover); }
.gu-badge--busy { color: var(--text-amber-hint); }
.gu-badge--idle { color: var(--text-text-alt-4); }

/* The console under the list: what the updater is doing, and how far it has
   got. Neither is a plate, and the bar is the one measure it owns. */
.gu-console {
    display: flex; flex-direction: column; gap: var(--sp-2);
    flex: 0 0 auto; max-height: 22vh; min-height: 0;
    padding: var(--sp-2) 0 0;
}
.gu-log {
    flex: 1 1 auto; min-height: 0;
    font-size: var(--fs-caption); color: var(--text-text-alt-4); line-height: 1.5;
}
.gu-log-line { word-break: break-all; }
.gu-progress {
    height: 4px; flex-shrink: 0;
    background: var(--bg-primary-hover-translucent-35);
}
.gu-progress--idle { opacity: 0; }
.gu-progress-fill {
    height: 100%; width: 0;
    background: var(--border-focus-hover);
    transition: width 0.15s linear;
}

/* The lines the right page has to say before anything else. */
.gu-note { margin-bottom: var(--sp-3); }
.gu-note-line + .gu-note-line { margin-top: 4px; }
.gu-note-line--major { color: var(--text-text-alt-5-hover); font-weight: bold; }
.gu-note-line--unstable { color: var(--text-amber-hint); }

/* The build's own changelog and its file list read in the detail card's
   scroll, so neither scrolls inside itself. */
.gu-changelog, .gu-files { margin-top: var(--sp-3); }
.gu-changelog-line { line-height: 1.5; word-break: break-word; max-width: 68ch; }
.gu-changelog-line--item { padding-left: 12px; text-indent: -12px; }
.gu-changelog-line--item::before { content: '2'; color: var(--text-gold-dark); margin-right: 6px; }
.gu-file-row { display: flex; align-items: baseline; gap: var(--sp-2); }
.gu-file-flag { color: var(--text-gold-dark); width: 10px; flex-shrink: 0; }
.gu-file-path { flex: 1; word-break: break-all; font-family: var(--font-mono); }
.gu-file-size { color: var(--text-detail-label); flex-shrink: 0; }
.gu-file-more { color: var(--text-detail-label); margin-top: 4px; }

/* ==========================================================================
   Shared parchment HTML overlays
   (CountryPopup, AchievementNotif, FloorDisplay, TravelTimer,
    BorderChoice, TravelDecision, PrisonTimer)
   ========================================================================== */

.html-parchment-overlay {
    position: fixed;
    z-index: 491;
    pointer-events: none;
    box-sizing: border-box;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
    font-family: var(--font-ui);
    font-weight: bold;
    box-shadow: 0 4px 10px var(--shadow-black-translucent-25);
}

/* Country popup */
.country-popup-name  { color: var(--text-gold-dark); }
.country-popup-super { color: var(--text-primary-hover); font-size: 0.892em; opacity: 0.85; margin-top: 3px; }

/* Achievement notification */
.achiev-notif-label { color: var(--text-text-alt-10); font-size: 0.856em; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 3px; }
.achiev-notif-name  { color: var(--text-disabled); }

/* Floor display */
#html-floor-display { text-align: right; }
.floor-display-num  { color: var(--text-gold-dark); }

/* Travel timer */
#html-travel-timer,
#gx-ship-travel-timer  { text-align: center; }
/* Same pen as the prison timer below it: the six type tokens, the warm value
   ink instead of pure white (ui_fixing rule 7), and no key legend under it. */
.travel-timer-label    { color: var(--text-primary-hover); font-size: var(--fs-label); text-align: center; }
.travel-timer-time     { color: var(--text-success-active); font-size: var(--fs-title); text-align: center; font-weight: bold; line-height: 1.2; }
.travel-timer-km       { color: var(--text-success-active); font-size: var(--fs-label); text-align: center; margin-top: 3px; }
.travel-timer-complete { color: var(--text-primary-hover); font-size: var(--fs-body); text-align: center; }

/* Prison timer, same plate and rhythm as the travel timer above */
#html-prison-timer     { text-align: center; }
.prison-timer-label    { color: var(--text-text-alt-4); font-size: var(--fs-label); text-align: center; }
.prison-timer-time     { color: var(--text-success-active); font-size: var(--fs-title); text-align: center; font-weight: bold; line-height: 1.2; }
.prison-timer-bounty   { color: var(--text-success-active); font-size: var(--fs-label); text-align: center; margin-top: 3px; }
.prison-timer-sleep-btn {
    display: inline-block;
    width: auto;
    margin-top: 8px;
    padding: 5px 10px;
    background: transparent;
    color: var(--text-primary-hover);
    border: 1px solid var(--border-subtle);
    border-radius: 4px;
    font-family: var(--font-ui);
    font-size: var(--fs-chip);
    font-weight: bold;
    cursor: pointer;
    pointer-events: auto; /* the overlay itself is pointer-events:none */
}
.prison-timer-sleep-btn:hover { background: var(--border-subtle); color: var(--text-danger-hover); }

/* Parchment selection menus */
#html-border-choice,
#html-travel-decision { min-width: 220px; }

.parchment-menu-item { padding: 5px 8px; color: var(--text-disabled); border-radius: 3px; }
.parchment-menu-item.active { background: var(--bg-subtle-translucent-15); color: var(--text-gold-dark); }
.parchment-menu-item.active::before { content: '▶ '; font-size: 0.784em; vertical-align: middle; }

/* window.CharSwitcher (defined identically by SpecializationMenu.js,
   CustomSceneStatus.js, ItemSystemEquipmentUI.js, CategorizedBattleSkills.js,
   SkillMaster.js, Health_ProstheticShop.js and Health_BiologicSimulation.js -
   whichever loads first wins). The strip and its L/R prompt used to be injected
   as a <style id="char-switch-hint-styles"> by each of those copies, which meant
   the size the player saw depended on load order: six copies said 0.732rem and
   SkillMaster's said 1.081rem. One rule here, at the majority size. */
.companion-switcher {
    display: flex;
    align-items: center;
    gap: 6px;
}

/* The key badge on the switcher arrow it belongs to: the one control hint the
   interface allows, so it is printed at the caption floor and read, not hinted
   at. */
.char-switch-hint {
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    font-weight: bold;
    line-height: 1;
    letter-spacing: 0.5px;
    color: var(--text-primary-hover);
    border: none;
    border-radius: 0;
    padding: 0 2px;
    opacity: 0.8;
    user-select: none;
    white-space: nowrap;
    text-transform: uppercase;
    flex-shrink: 0;
}

/* A book-spread's right page is headed by its party switcher instead of by a
   second page title: the left page already names the menu, and the tabs say
   whose hands the work is in. The switcher is drawn even for a party of one, so
   the name under the heading is never missing. The gap below it is where
   window.SpecBadge hangs the training chip, which is positioned (fixed) rather
   than laid out, hence the reserved margin. */
.companion-switcher--header {
    flex: 0 0 auto;
    justify-content: center;
    align-items: center;
    min-height: 26px;
    margin: 0 0 40px 0;
    padding-bottom: 4px;
    border-bottom: 1px solid var(--border-primary-hover-translucent-15);
}

/* Specialization badges (window.SpecBadge, SpecializationMenu.js) - chips
   naming the skill a menu or minigame is training, and the party's tier in it.
   Persistent for as long as that menu is open, unlike a toast. The plugin
   anchors the stack under the open menu's party switcher (or, failing one, in
   the top right corner of its page) so it always lands inside the border. */
#spec-badge-stack {
    position: fixed;
    z-index: 490;
    pointer-events: none;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
    /* Anchored at the canvas's right edge and pulled back by its own width, so
       the chip can never overhang the frame however the canvas is scaled. */
    transform: translateX(-100%);
}
.spec-badge {
    display: flex;
    align-items: baseline;
    gap: 0.5em;
    padding: 0.35em 0.9em;
    border: 1px solid var(--border-subtle);
    /* No plate behind a chip and no grey ink on it (ui_fixing rules 1 and 4):
       the ground is the page and every part of the badge is read. */
    background: transparent;
    color: var(--text-success-active);
    white-space: nowrap;
    max-width: 100%;
    overflow: hidden;
}
.spec-badge-name  { font-weight: bold; color: var(--text-primary-hover); }
.spec-badge-level { color: var(--text-primary-hover); font-size: var(--fs-chip); }
.spec-badge-who   { color: var(--text-text-alt-4); font-size: var(--fs-caption); }
/* Untrained reads flat; every tier above it warms up. */
.spec-badge--t1 .spec-badge-level { color: var(--text-text-alt-4); }
.spec-badge--t4, .spec-badge--t5 { border-color: var(--text-gold-dark); }

/* Toast stack (ParchmentToast.js) - top-right transient notifications */
#html-toast-stack {
    position: fixed;
    z-index: 491;
    pointer-events: none;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
}
#html-toast-stack .html-toast {
    position: static;
    padding: 0.55em 1.05em;
    border-width: 2px;
    outline-offset: -5px;
    transition: opacity 0.4s ease;
    max-width: 24em;
    /* No colour here: the severity class below carries it, and an id rule
       would outrank it. */
    line-height: 1.3;
    letter-spacing: 0.01em;
}
/* A standing notification (ParchmentToast.sticky) is up because the condition
   it names is still true, so it wears a heavier frame than a passing one. */
#html-toast-stack .html-toast--sticky {
    border-color: var(--border-danger-active);
    outline-color: var(--border-danger-active);
}
/* Info is the plain "here is what happened" plate, read at a glance over a
   moving map: its body text is a light ink on the dark parchment rather than
   the frame's own brown, which used to sink into the background. */
.html-toast--info    { color: var(--toast-text); }
.html-toast--warning { color: var(--text-text-alt-17); }
.html-toast--danger  { color: var(--text-text-alt-10); }
.html-toast--good    { color: var(--text-gold-dark); }

/* Toast body parts, built by the ParchmentToast builders (reward / need /
   specUp). Tokens only: the theme presets remap inline colour literals, so
   the notification markup carries none. */
.toast-title {
    color: var(--text-gold-dark);
    font-weight: bold;
    font-size: 1.05em;
    margin-bottom: 0.25em;
}
.toast-row {
    display: flex;
    align-items: center;
    gap: 0.4em;
    margin-top: 0.15em;
}
.toast-icon {
    display: inline-block;
    flex-shrink: 0;
    vertical-align: -0.25em;
    background-image: url('../img/system/IconSet.png');
    background-repeat: no-repeat;
    image-rendering: pixelated;
}
.toast-qty   { color: var(--toast-text-muted); }
.toast-value { color: var(--text-gold-dark); font-weight: bold; font-size: 1.05em; }
.toast-note  { color: var(--toast-text-muted); font-size: 0.95em; }

/* An item row is named in the colour of its rarity, the same ladder the
   inventory and the shop paint (js/db/Items/Rarity.json). The class is picked
   in ParchmentToast.rarityClass(). */
.toast-item-name { flex: 1; }
.toast-rarity--common    .toast-item-name { color: var(--rarity-common); }
.toast-rarity--uncommon  .toast-item-name { color: var(--rarity-uncommon); }
.toast-rarity--rare      .toast-item-name { color: var(--rarity-rare); }
.toast-rarity--epic      .toast-item-name { color: var(--rarity-epic); }
.toast-rarity--legendary .toast-item-name { color: var(--rarity-legendary); }
.toast-delta-up   { color: var(--text-success-active); font-weight: bold; }
.toast-delta-down { color: var(--text-text-alt-10); font-weight: bold; }

/* ==========================================================================
   Shop Management UI (ShopManagementUI.js)
   ========================================================================== */

#shop-mgmt-container {
    position: fixed;
    top: 0; right: 0; bottom: 0; left: 0;
    z-index: 490;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-bg-alt-1-translucent-70);
}

/* Role badge in the page header */
.shop-role-badge {
    font-size: 0.798em;
    font-weight: bold;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    padding: 3px 10px;
    border: 1px solid var(--border-success);
    color: var(--text-text-alt-17);
    background: var(--bg-bg-alt-5-translucent-15);
    white-space: nowrap;
    align-self: center;
}

.shop-role-badge.shop-role-manager  { color: var(--text-text-alt-16); background: var(--bg-bg-alt-6-translucent-12); }
.shop-role-badge.shop-role-producer { color: var(--text-text-alt-18); background: var(--bg-bg-alt-7-translucent-12); }
.shop-role-badge.shop-role-rider    { color: var(--text-text-alt-17); background: var(--bg-bg-alt-5-translucent-15); }

/* Shop status values */
.shop-status-on  { color: var(--text-text-alt-11); }
.shop-status-off { color: var(--text-text-alt-4);  }

/* Empty slot style */
.shop-slot-empty { opacity: 0.55; font-style: normal; }
.shop-slot-hint  { font-size: 0.82em; color: var(--text-text-alt-8); font-style: normal; }

/* Delivery countdown timer */
.shop-delivery-timer { color: var(--text-text-alt-17); font-weight: bold; }

/* Ingredient availability colours */
.shop-ing-ok { color: var(--text-text-alt-11); }
.shop-ing-no { color: var(--text-text-alt-5-hover); }

/* Produce status row */
.shop-can-produce { color: var(--text-text-alt-11); font-weight: bold; padding-top: 6px; }
.shop-no-mats     { color: var(--text-text-alt-5-hover); font-weight: bold; padding-top: 6px; }

/* Slot-assignment mode banner */
.shop-assign-banner {
    margin: 4px 8px 0;
    padding: 5px 10px;
    font-size: 0.842em;
    font-style: normal;
    color: var(--text-text-alt-17);
    background: var(--bg-bg-alt-5-translucent-15);
    border-left: 3px solid var(--text-text-alt-17);
    border-radius: 0 4px 4px 0;
}

/* Scrollable list area */
.shop-mgmt-list {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

/* ==========================================================================
   Blade Seed System UI (BladeSeedSystemUI.js)
   ========================================================================== */

#blade-bind-container,
#blade-status-container {
    /* The four offsets alone collapse a fixed overlay to nothing in this
       runtime (the same trap as `inset: 0`), which left these three screens
       blank: an explicit width and height is what actually fills the screen.
       z-index matches the other full screen DOM menus, so the overlay is never
       drawn under the HUD it replaces. */
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    z-index: 1000;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-bg-alt-1-translucent-70);
}

/* Warning banner */
.bs-warning {
    margin: 6px 8px;
    padding: 5px 10px;
    font-size: 0.856em;
    color: var(--text-text-alt-5-hover);
    background: var(--bg-subtle-translucent-10);
    border-left: 3px solid var(--border-danger-active);
    border-radius: 0 4px 4px 0;
}

/* Chosen appearance: the 3D viewport and its stepper on the binding page */
.bs-look {
    margin: 6px 8px 2px;
}
.bs-look-canvas {
    display: block;
    width: 100%;
    height: 150px;
    border: 1px solid var(--border-border-alt-1);
    border-radius: 4px;
    background: var(--bg-bg-alt-25-translucent-8);
    cursor: grab;
}
.bs-look-canvas:active { cursor: grabbing; }
.bs-look-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-top: 4px;
}
.bs-look-label {
    flex: 1;
    text-align: center;
    font-size: var(--fs-detail-body);
    color: var(--text-detail-label);
}
.bs-look-count {
    margin-left: 6px;
    color: var(--text-success-active);
    font-weight: bold;
}
.bs-look-arrow {
    padding: 2px 10px;
    border: 1px solid var(--border-subtle);
    border-radius: 4px;
    background: var(--bg-secondary-hover);
    color: var(--text-primary-hover);
    font-size: 0.892em;
    cursor: pointer;
}
.bs-look-arrow:hover { background: var(--bg-bg-alt-21-hover); }

/* Scrollable weapon / skill list */
.bs-weapon-list,
.bs-skill-list {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

/* Element badge (inline next to title) */
.bs-el-badge {
    font-size: var(--fs-detail-heading);
    font-weight: bold;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 3px 10px;
    border: 1px solid var(--border-success);
    background: var(--bg-bg-alt-25-translucent-8);
    white-space: nowrap;
    align-self: center;
}

/* Skill source label & hint */
.bs-src-label { font-size: var(--fs-detail-heading); opacity: 0.65; }
.bs-skill-hint { font-size: var(--fs-detail-body); color: var(--text-success-active); }

/* Stat grid: 2-column layout */
.bs-stat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px 12px;
    margin-top: 8px;
}
.bs-stat-cell {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 3px 6px;
    border-radius: 4px;
    background: var(--bg-bg-alt-25-translucent-8);
}
.bs-stat-label { color: var(--text-detail-label); font-size: var(--fs-detail-body); }
.bs-stat-value { color: var(--text-success-active); font-weight: bold; font-size: var(--fs-detail-body); }

/* Action buttons row */
.bs-actions {
    display: flex;
    gap: 8px;
    margin-top: 16px;
    flex-wrap: wrap;
}
.bs-btn {
    flex: 0 1 auto;
    min-width: 80px;
    padding: 8px 12px;
    border: 2px solid var(--border-subtle);
    border-radius: 5px;
    font-family: var(--font-ui);
    font-size: 0.892em;
    font-weight: bold;
    cursor: pointer;
    transition: background 0.12s, transform 0.08s;
    background: var(--bg-secondary-hover);
    color: var(--text-primary-hover);
}
.bs-btn:hover       { background: var(--bg-bg-alt-21-hover); transform: translateY(-1px); }
.bs-btn:active      { transform: translateY(0); }
.bs-btn-confirm     { border-color: var(--text-text-alt-11); color: var(--text-text-alt-11); }
.bs-btn-confirm:hover { background: var(--bg-bg-alt-8-translucent-15); }
.bs-btn-reshuffle   { border-color: var(--border-focus-hover); color: var(--border-focus-hover); }
.bs-btn-cancel      { border-color: var(--border-border-alt-9); color: var(--text-disabled); }

/* Spirit portrait block */
.bs-spirit-portrait {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 10px;
    margin: 6px 0;
}
.bs-spirit-portrait canvas {
    border: 2px solid var(--border-success);
    border-radius: 6px;
    image-rendering: pixelated;
}

/* EXP bar */
.bs-exp-bar-wrap {
    height: 8px;
    background: var(--bg-bg-alt-25-translucent-8);
    border: 1px solid var(--border-border-alt-1);
    border-radius: 4px;
    margin: 8px 8px 2px;
    overflow: hidden;
}
.bs-exp-bar {
    height: 100%;
    background: var(--text-text-alt-11);
    border-radius: 4px;
    transition: width 0.3s ease-out;
}
.bs-exp-text  { font-size: var(--fs-detail-body); color: var(--text-success-active); text-align: center; margin-bottom: 2px; }
.bs-evo-text  { font-size: var(--fs-detail-body); color: var(--text-success-active); text-align: center; font-style: normal; padding: 0 8px; }

/* LP value highlight */
.bs-lp-val { color: var(--text-success-active); font-weight: bold; }

/* Skills, unaffordable row */
.bs-skill-no { color: var(--text-text-alt-5-hover) !important; }

/* Skill help text */
.bs-skill-help {
    margin: 6px 8px 0;
    padding: 6px 10px;
    font-size: var(--fs-detail-prose);
    font-style: normal;
    color: var(--text-success-active);
    background: var(--bg-bg-alt-25-translucent-8);
    border-radius: 4px;
    border-left: 3px solid var(--border-success);
}

/* Right-page content scroll */
.bs-right-content {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

/* ==========================================================================
   Animal Growth System  (AnimalGrowthSystem.js)
   Livestock is bought in the Build menu and managed from the Assets menu;
   these are the shared bits both panels draw with.
   ========================================================================== */

/* Centred sprite canvas */
.ag-sprite-canvas {
    display: block;
    margin: 8px auto 10px;
    image-rendering: pixelated;
}

/* Stage colour accents */
.ag-stage-adult { color: var(--text-disabled); }
.ag-stage-baby  { color: var(--text-text-alt-9); }

/* Value colour helpers */
.ag-gold        { color: var(--text-text-alt-14-hover); }
.ag-days        { color: var(--text-text-alt-9); }
.ag-ready       { color: var(--text-disabled); font-weight: bold; }
.ag-cant-afford { color: var(--text-text-alt-8); }

/* Growth bar (inline in an inspect-spec-row) */
.ag-growth-val {
    display: flex;
    align-items: center;
    gap: 6px;
    flex: 1;
}
.ag-growth-wrap {
    flex: 1;
    height: 8px;
    background: var(--bg-bg-alt-25-translucent-8);
    border: 1px solid var(--border-border-alt-1);
    border-radius: 4px;
    overflow: hidden;
}
.ag-growth-bar {
    height: 100%;
    background: var(--border-success);
    border-radius: 4px;
    transition: width 0.3s ease-out;
}
.ag-growth-pct { font-size: 0.82em; white-space: nowrap; }

/* The livestock actions the Assets menu used to draw on a filled plate of
   their own are the shared .inspect-btn strip now; the rules that drew the
   plate, the lift and the two-pixel focus glow are gone with them. */

/* Production note (italic placeholder) */
.ag-prod-note {
    font-style: normal;
    color: var(--text-disabled);
    margin: 6px 0;
    font-size: 0.842em;
}

/* Thin separator between production entries */
.ag-divider {
    border: none;
    border-top: 1px solid var(--border-subtle);
    margin: 5px 0;
}

/* ==========================================================================
   Music Selection System UI  (MusicSelectionSystemUI.js)
   ========================================================================== */

/* A bare .book-spread appended to the body with no backdrop of its own, so the
   zoom goes on the spread itself. */
#music-sel-container {
    zoom: var(--ui-zoom, 1);
}

/* Track list (left page) */
.ms-track-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-top: 8px;
    max-height: 520px;
    overflow-y: auto;
    scrollbar-width: thin;
}

.ms-track-row {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 8px;
}

.ms-saved-mark   { color: var(--text-primary-hover); font-size: 0.856em; width: 14px; flex-shrink: 0; }
.ms-mark-empty   { visibility: hidden; }
.ms-track-name   { flex: 1; }
.ms-composer     { font-size: 0.82em; color: var(--text-disabled); white-space: nowrap; }

.ms-hint {
    font-size: 0.77em;
    color: var(--text-disabled);
    font-style: normal;
    text-align: center;
    margin-top: 8px;
}

/* Right page detail */
.ms-active-badge {
    margin: 8px 0;
    padding: 4px 10px;
    background: var(--bg-bg-alt-25-translucent-8);
    border-left: 3px solid var(--border-success);
    color: var(--text-disabled);
    font-size: 0.87em;
}

/* Pulsing music note */
@keyframes ms-note-pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50%       { opacity: 0.5; transform: scale(1.15); }
}
.ms-note-anim {
    font-size: 1.76em;
    text-align: center;
    margin: 12px 0;
    color: var(--text-text-alt-14-hover);
    animation: ms-note-pulse 1.4s ease-in-out infinite;
}

.ms-ok-hint {
    margin-top: 16px;
    font-size: 0.784em;
    font-style: normal;
    color: var(--text-disabled);
    text-align: center;
}

/* ==========================================================================
   Rent System UI  (RentSystem.js, HTML overlay on Scene_Map)
   ========================================================================== */

#rent-room-list {
    position: fixed;
    top: 16px;
    left: 16px;
    min-width: 220px;
    max-width: 320px;
    z-index: 1001;
}

.rent-list-title { margin-bottom: 6px; }

.rent-room-entry {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    padding: 4px 8px;
}

.rent-room-label { flex: 1; }

.rent-status      { white-space: nowrap; }
.rent-available   { color: var(--text-disabled); }
.rent-rented      { color: var(--text-text-alt-9); }

.rent-hint {
    font-size: 0.77em;
    color: var(--text-disabled);
    text-align: center;
    margin-top: 6px;
    font-style: normal;
}

/* ==========================================================================
   Stealing System UI  (StealingSystemUI.js)
   ========================================================================== */

/* Transparent, non-blocking backdrop so the map stays visible behind the window */
#steal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 501;
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
    pointer-events: none;
}

/* Compact dialogue-style choice window (matches #html-choice-overlay) */
#steal-window {
    pointer-events: auto;
    box-sizing: border-box;
    min-width: 280px;
    max-width: min(420px, 90vw);
    max-height: 80vh;
    display: flex;
    flex-direction: column;
    padding: 10px 8px;
    background: var(--text-danger-hover);
    border: 3px solid var(--border-subtle);
    border-radius: 6px;
    outline: 1px solid var(--border-subtle-translucent-40);
    outline-offset: -7px;
    background-image: radial-gradient(ellipse at center, transparent 40%, var(--bg-brown-vignette-10) 100%);
}

.steal-title {
    font-family: var(--font-ui);
    font-weight: bold;
    color: var(--text-primary-hover);
    text-align: center;
    padding: 2px 18px 8px;
    letter-spacing: 0.04em;
    text-shadow: none;
}

.steal-choice-list {
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    scrollbar-width: thin;
}

/* The shelf is drawn out of the backpack's own row (.item-slot): this only
   says how tight the rows sit in the little window and which one is in hand. */
.steal-choice {
    padding: 4px 12px;
    user-select: none;
    cursor: pointer;
}
.steal-choice.selected {
    background: rgba(255, 204, 102, 0.12);
}
.steal-choice.selected .item-slot-name { color: var(--text-primary-hover); }

.steal-choice-pct { white-space: nowrap; font-weight: bold; }

.steal-empty {
    font-family: var(--font-ui);
    font-style: normal;
    color: rgba(255, 204, 102, 0.55);
    text-align: center;
    padding: 8px 18px;
}

#refuel-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: var(--gradient-4), var(--bg-bg-alt-1-translucent-70);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    box-sizing: border-box;
    padding: 0;
    /* was 24px: the backdrop inset that letterboxed the panel */
}


/* ═══════════════════════════════════════════════════════════
   VEHICLE SYSTEM REFUEL UI
   ═══════════════════════════════════════════════════════════ */

.rf-subtitle {
    font-size: 1.048em;
    margin: 4px 0 10px;
    color: var(--text-text-alt-9);
}

#refuel-container .inspect-section-title {
    font-size: var(--fs-detail-heading);
}

#refuel-container .inspect-spec-row {
    font-size: var(--fs-detail-body);
}

#refuel-container .rf-label {
    font-size: var(--fs-detail-heading);
}

.rf-option-list {
    display: flex;
    flex-direction: column;
    gap: 4px;
    overflow-y: auto;
    max-height: 55%;
    scrollbar-width: thin;
}

.rf-option-row {
