#gx-fuel .gx-fuel-name { flex:0 0 78px; font-size:var(--fs-chip); letter-spacing:0.5px;
  color:var(--gx-ink-dim); text-transform:uppercase; }
#gx-fuel .gx-fuel-bar { flex:1 1 auto; height:9px; border-radius:5px;
