#gx-catalog .gx-cat-tab .gx-cat-count { margin-left:0; }
#gx-catalog .gx-cat-tab.gx-on {
  background:var(--bg-primary-hover-translucent-35);
  border-color:var(--text-primary-hover);
  color:var(--text-primary-hover); }
#gx-catalog .gx-cat-group { display:flex; align-items:center; gap:6px;
  break-after:avoid-column;
  margin:10px 0 4px; font-size:var(--fs-chip); font-weight:bold;
  letter-spacing:1px; text-transform:uppercase;
  color:var(--accent-amber-light);
  border-bottom:1px solid var(--gx-line);
  padding-bottom:3px; }
#gx-catalog .gx-cat-group:first-of-type { margin-top:4px; }
#gx-catalog .gx-cat-count { margin-left:auto; font-weight:normal; letter-spacing:0;
  color:var(--gx-ink-dim); }
#gx-catalog .gx-cat-life .gx-cat-name { color:var(--gx-accent-bio); }
#gx-catalog .gx-cat-row { display:flex; align-items:center; gap:6px; padding:4px 0; }
/* Current System hierarchy: star at depth 0, planets at 1, moons at 2. */
