  white-space:nowrap; font-size:var(--fs-body); }
#gx-catalog .gx-cat-type { display:block; font-size:var(--fs-chip);
  color:var(--gx-ink-dim); overflow:hidden; text-overflow:ellipsis;
  white-space:nowrap; }
#gx-catalog .gx-btn { margin:0; padding:3px 8px; font-size:var(--fs-chip); flex:0 0 auto; }
#gx-catalog .gx-cat-empty { color:var(--gx-ink-dim); font-size:var(--fs-body); }
#gx-tooltip { position:absolute; pointer-events:none; display:none;
  left:var(--ui-at-x, 0); top:var(--ui-at-y, 0);
  background:var(--gx-hull-deep);
  border:1px solid var(--gx-line);
  border-radius:4px; padding:4px 8px; font-size:var(--fs-body); white-space:nowrap;
