#gx-ui .gx-btn {
  pointer-events:auto; display:inline-block; cursor:pointer;
  background:transparent;
  border:1px solid var(--text-primary-hover);
  color:var(--text-primary-hover);
  border-radius:4px; padding:4px 10px; margin:4px 6px 0 0;
  font-weight:bold; font-size:var(--fs-chip); }
