  box-shadow:0 6px 24px var(--shadow-black-translucent-55); }
#gx-anomaly .gx-anom-where { font-size:var(--fs-chip); letter-spacing:0.08em; text-transform:uppercase;
  color:var(--gx-ink-dim); }
#gx-anomaly .gx-anom-body { overflow-y:auto; overscroll-behavior:contain;
  margin:10px -4px 0; padding:0 4px; font-size:var(--fs-body); line-height:1.62; }
#gx-anomaly .gx-anom-body p { margin:0 0 10px; }
#gx-anomaly .gx-anom-rewards { margin-top:8px; padding-top:8px;
  border-top:1px solid var(--gx-line);
  font-size:var(--fs-body); color:var(--accent-amber-light); }
