#gx-anomaly .gx-anom-rewards .toast-icon { vertical-align:0; }
#gx-anomaly .gx-anom-choices { display:flex; flex-direction:column; gap:6px; margin-top:12px; }
#gx-anomaly .gx-anom-choice { display:block; text-align:left; padding:8px 12px;
  border:1px solid var(--gx-line);
cursor:pointer; font-size:var(--fs-body); line-height:1.4;
  background:transparent; }
#gx-anomaly .gx-anom-choice:hover, #gx-anomaly .gx-anom-choice.focused {
  border-color:var(--text-primary-hover);
  color:var(--text-primary-hover); }
#gx-anomaly .gx-anom-choice .gx-anom-num { color:var(--accent-amber-light);
  margin-right:8px; font-weight:bold; }
/* Strip-mining console: progress, clock, and the ore as it comes in. */
#gx-mining { position:absolute; left:50%; bottom:64px; transform:translateX(-50%);
  display:none; pointer-events:auto; width:min(520px,86vw);
  background:var(--gx-hull);
  border:1px solid var(--gx-line);
  border-radius:6px; padding:12px 16px; z-index:20;
  box-shadow:0 6px 20px var(--shadow-black-translucent-55); }
#gx-mining .gx-mine-head { display:flex; align-items:baseline; gap:10px; }
#gx-mining .gx-mine-head .gx-title { margin:0; font-size:var(--fs-heading); }
#gx-mining .gx-mine-clock { margin-left:auto; font-size:var(--fs-body);
  font-family:'Consolas',monospace; color:var(--gx-accent-ship); }
#gx-mining .gx-mine-bar { height:12px; border-radius:6px; margin:8px 0 6px;
  background:var(--gx-hull-deep);
  border:1px solid var(--gx-line);
  overflow:hidden; }
#gx-mining .gx-mine-fill { height:100%; width:var(--ui-bar-w, 0%); border-radius:5px;
  background:linear-gradient(to right,var(--gx-accent-fuel-deep),var(--gx-accent-warn),var(--gx-accent-fuel));
  transition:width 0.25s linear; }
#gx-mining .gx-mine-log { font-size:var(--fs-chip); line-height:1.45; min-height:34px;
  color:var(--gx-ink-dim); }
#gx-mining .gx-mine-log b { color:var(--accent-amber-glow); }
#gx-mining .gx-mine-log .gx-rare { color:var(--gx-accent-bridge); }


/* ==========================================================================
   VOXEL WORLD HUD (VoxelWorld/VoxelWorldHUD.js)
   --------------------------------------------------------------------------
   The 3D driving / walking HUD over the destructible voxel ground. Styled
   after ItemSystemInventoryUI.js using theme tokens and serif typography.
   ========================================================================== */
#camper-drive-hud {
    position: absolute; top: 0; left: 0; width: 100%; height: 100%;
    pointer-events: none; font-family: var(--font-ui); z-index: 1;
