    line-height: 1.45;
}
#camper-drive-hud .cds-env-row {
    margin-top: 4px; font-size: var(--fs-chip); color: var(--text-text-alt-12);
}
#camper-drive-hud .cds-speed-text {
    font-size: var(--fs-title); font-weight: bold; text-align: center;
}
#camper-drive-hud .cds-rpm-row {
