    font-size: var(--fs-heading);
}


/* ==========================================================================
   WORLD MANAGER (UI/WorldManagerUI.js)
   --------------------------------------------------------------------------
   The world-select spread off the title screen, on the shared kit: Shape A on
   the outside (.book-spread of a .left-page list and a .right-page dossier),
   Shape B for the create form and the delete confirmation (.ui-overlay over
   .ui-panel). Rows are .item-slot, tabs are .backpack-tab, facts are an
   .inspect-spec-grid and every button is an .inspect-btn, so the screen wears
   the backpack's fixes without repeating them. Only what the kit has no name
   for is written here.
   ========================================================================== */
#world-manage-container {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    display: none;
    align-items: center;
    justify-content: center;
    z-index: 120;
    background: var(--shadow-black-translucent-55);
}
/* Whether the screen is up is a class on the container, never a style written
   from the scene: #menu-container-style ids are shared, and so is this one. */
#world-manage-container.wm-open {
    display: flex;
    opacity: 1;
    pointer-events: auto;
}
#world-manage-container.wm-closing {
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease-out;
}
/* The right page holds one card, not three spread rows. */
#world-manage-container .right-page {
    justify-content: flex-start;
    gap: var(--sp-3);
}
#world-manage-container .wm-list {
    gap: var(--sp-3);
    overflow-y: auto;
    min-height: 0;
}
#world-manage-container .wm-list-actions .inspect-btn {
    width: auto;
}
#world-manage-container .wm-empty {
    padding: 16px;
    text-align: center;
    font-size: var(--fs-body);
    color: var(--text-detail-label);
}
#world-manage-container .wm-world-name {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-success-active);
}
#world-manage-container .wm-active-badge {
    font-size: var(--fs-caption);
    color: var(--text-primary-hover);
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
/* The create form. */
#world-manage-container .wm-create {
    display: flex;
    flex-direction: column;
    gap: var(--sp-2);
}
#world-manage-container .wm-create label {
    font-size: var(--fs-label);
    margin-top: var(--sp-2);
    color: var(--text-detail-label);
}
#world-manage-container .wm-create input {
    background: none;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 3px;
    color: var(--text-success-active);
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    padding: 6px 8px;
    outline: none;
}
#world-manage-container .wm-create input:focus {
    border-color: var(--text-primary-hover);
}
#world-manage-container .wm-seed-row {
    display: flex;
    gap: var(--sp-2);
    align-items: center;
}
#world-manage-container .wm-seed-row #wm-seed-input {
    flex: 1;
    min-width: 0;
}
#world-manage-container .wm-status {
    font-size: var(--fs-caption);
    min-height: 18px;
    color: var(--text-highlight-active);
}
#world-manage-container .wm-tabs {
    flex-shrink: 0;
}
#world-manage-container .wm-tab-body {
    flex: 1;
    overflow-y: auto;
    min-height: 0;
}
#world-manage-container .wm-diary-list {
    flex-direction: column;
}
#world-manage-container .wm-diary-row {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    text-align: left;
    width: 100%;
}
#world-manage-container .wm-diary-row .wm-diary-names {
    font-size: var(--fs-body);
}
#world-manage-container .wm-diary-row .wm-diary-meta {
    font-size: var(--fs-caption);
    color: var(--text-detail-label);
}
/* The balance: one block of facts per hyperpower, strongest first. */
#world-manage-container .wm-power {
    margin-bottom: var(--sp-4);
}
#world-manage-container .wm-power-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: var(--sp-3);
    margin-bottom: var(--sp-1);
}
#world-manage-container .wm-power-name {
    font-family: var(--font-ui);
    font-size: var(--fs-heading);
    color: var(--text-detail-heading);
}
#world-manage-container .wm-power-territories {
    font-size: var(--fs-caption);
    color: var(--text-detail-label);
    text-align: right;
}
/* Keyboard / controller focus: the shared gold hairline, nothing behind it. */
#world-manage-container .kb-focus {
    border-color: var(--text-primary-hover);
    outline: none;
}
#world-manage-container .back-button.kb-focus,
#world-manage-container .backpack-tab.kb-focus,
#world-manage-container .inspect-btn.kb-focus,
#world-manage-container .wm-create input.kb-focus,
#world-manage-container .wm-year-selector.kb-focus {
    border: 1px solid var(--text-primary-hover);
    background: none;
}
/* Arrow-based spinners (month, year, level, population, magic). */
#world-manage-container .wm-date-row {
    display: flex;
    gap: var(--sp-3);
    align-items: stretch;
}
#world-manage-container .wm-date-row .wm-year-selector {
    flex: 1;
    min-width: 0;
}
#world-manage-container .wm-date-row .wm-year-arrow {
    padding: 2px 8px;
}
/* What a later starting year does to the monsters (enemyLevelNoticeFor), what
   a population or a magic level costs, and the one notice that is not about
   difficulty at all: there is no Earth left. */
#world-manage-container .wm-enemy-floor {
    margin: var(--sp-1) 0 2px;
    font-family: var(--font-ui);
    font-size: var(--fs-caption);
    line-height: 1.3;
    color: var(--text-highlight-active);
}
#world-manage-container .wm-story-disabled,
#world-manage-container .wm-earth-lost {
    font-weight: bold;
    color: var(--text-secondary-active);
}
#world-manage-container .wm-year-selector {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: none;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 3px;
    padding: 4px 6px;
    outline: none;
    user-select: none;
}
#world-manage-container .wm-date-label {
    flex: 1;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    color: var(--text-success-active);
}
#world-manage-container .wm-year-arrow {
    background: none;
    border: none;
    color: var(--text-primary-hover);
    font-size: var(--fs-heading);
    line-height: 1;
    padding: 2px 14px;
    cursor: pointer;
    transition: color 0.15s ease;
}
#world-manage-container .wm-year-arrow:hover {
    color: var(--text-highlight-active);
}
/* The two dialogs: the delete confirmation and the create form. */
#world-manage-container .wm-modal-overlay {
    position: absolute;
}
#world-manage-container .wm-modal {
    width: min(440px, 80%);
    max-width: 720px;
}
#world-manage-container .wm-modal-title {
    margin-top: 0;
    text-align: center;
}
#world-manage-container .wm-modal-message {
    font-family: var(--font-ui);
    font-size: var(--fs-body);
    line-height: 1.5;
    color: var(--text-success-active);
    margin: var(--sp-3) 0 var(--sp-5) 0;
    text-align: center;
}
#world-manage-container .wm-create-modal {
    width: min(560px, 90%);
    max-width: 720px;
    max-height: 88%;
    display: flex;
    flex-direction: column;
}
#world-manage-container .wm-create-modal-header {
    justify-content: space-between;
    flex-shrink: 0;
}
#world-manage-container .wm-modal-x {
    background: none;
    border: none;
    color: var(--text-detail-label);
    font-size: var(--fs-title);
    line-height: 1;
    cursor: pointer;
    padding: 0 4px;
    transition: color 0.15s ease;
}
#world-manage-container .wm-modal-x:hover {
    color: var(--text-primary-hover);
}
/* A notice with nothing to say, and the create form before it is asked for.
   Last in the block so it wins over whatever it is hiding. */
#world-manage-container .wm-hidden {
    display: none;
}


/* ==========================================================================
   CARD DUEL (Cards/CardGameDuel.js)
   --------------------------------------------------------------------------
   The duel board: lanes, the two hands, the resolve overlay. Was injected as
   <style id="cardduel-style"> the first time a duel opened.
   ========================================================================== */
#cardduel-container{position:fixed;left:0;top:0;width:100%;height:100%;z-index:60;
  font-family:var(--font-ui);color:var(--text-success-active);overflow:hidden;user-select:none;
  --cd-cell:120px;--cd-cardw:150px;--cd-cardh:220px;
  background:radial-gradient(ellipse at 50% 42%, #0d0d0d 0%, #050505 58%, #000 100%),#000;}
#cardduel-container *{box-sizing:border-box;}
#cardduel-container.cd-shake{animation:cd-shake .32s cubic-bezier(.36,.07,.19,.97) both;}
@keyframes cd-shake{10%,90%{transform:translate(-2px,1px)}20%,80%{transform:translate(4px,-2px)}
  30%,50%,70%{transform:translate(-7px,3px)}40%,60%{transform:translate(7px,-3px)}100%{transform:none}}

.cd-head{position:absolute;left:0;top:0;width:100%;padding:10px 18px;display:flex;
  align-items:center;justify-content:space-between;gap:14px;
  background:linear-gradient(180deg,rgba(0,0,0,.55),rgba(0,0,0,0));}
.cd-side{display:flex;align-items:center;gap:10px;min-width:230px;}
.cd-side.cd-right{justify-content:flex-end;}
.cd-who{font-size:1.208rem;font-weight:bold;letter-spacing:.04em;text-shadow:0 2px 0 rgba(0,0,0,.6);}
.cd-tally{font-size:2.2rem;font-weight:bold;line-height:1;min-width:44px;text-align:center;
  padding:2px 10px;border-radius:8px;background:rgba(0,0,0,.42);border:2px solid rgba(255,255,255,.16);
  transition:transform .12s ease-out;}
.cd-tally.cd-pop{transform:scale(1.45);}
.cd-p0 .cd-tally{color:#8fe3ff;border-color:#3b8fb5;}
.cd-p1 .cd-tally{color:#ffb08f;border-color:#b5613b;}
.cd-stakebar{text-align:center;font-size:1.104rem;opacity:.92;}
.cd-turnline{font-size:1.15rem;font-weight:bold;letter-spacing:.06em;}

.cd-boardwrap{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);}
.cd-grid{position:relative;display:grid;gap:12px;z-index:1;}
.cd-tile{position:relative;border-radius:10px;border:2px solid rgba(238,216,170,.22);
  background:rgba(0,0,0,.30);display:flex;align-items:center;justify-content:center;
  transition:border-color .12s,box-shadow .12s,transform .12s;overflow:visible;}
.cd-tile.cd-legal{border-color:rgba(255,232,150,.75);box-shadow:0 0 14px rgba(255,220,120,.28) inset;}
.cd-tile.cd-cursor{border-color:var(--text-primary-hover);box-shadow:0 0 0 3px rgba(255,228,134,.55),0 0 24px rgba(255,228,134,.45);}
.cd-tile.cd-own{background:rgba(38,96,132,.34);}
.cd-tile.cd-foe{background:rgba(132,58,38,.34);}
.cd-tile canvas.cd-sprite{image-rendering:pixelated;filter:drop-shadow(0 3px 3px rgba(0,0,0,.6));}
.cd-tilename{position:absolute;left:3px;right:3px;bottom:3px;text-align:center;
  font-size:calc(var(--cd-cell) * .092);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 1px 2px #000;opacity:.9;}
.cd-tilegear{position:absolute;left:3px;top:3px;display:flex;gap:3px;}
.cd-tilepower{position:absolute;right:5px;top:2px;font-weight:bold;
  font-size:calc(var(--cd-cell) * .13);
  text-shadow:0 1px 2px #000,0 0 6px #000;}
.cd-tile.cd-land{animation:cd-land .34s cubic-bezier(.18,1.6,.4,1) both;}
@keyframes cd-land{0%{transform:scale(.4) translateY(-42px);opacity:0}
  60%{transform:scale(1.14) translateY(0);opacity:1}100%{transform:scale(1)}}
.cd-tile.cd-lunge{animation:cd-lunge .42s cubic-bezier(.4,0,.2,1) both;z-index:5;}
@keyframes cd-lunge{0%{transform:none}45%{transform:translate(var(--lx),var(--ly)) scale(1.08)}100%{transform:none}}
.cd-tile.cd-bounce{animation:cd-bounce .5s cubic-bezier(.2,1.5,.4,1) both;}
@keyframes cd-bounce{0%{transform:scale(1)}40%{transform:scale(1.2)}100%{transform:scale(1)}}
.cd-tile.cd-dying{animation:cd-die .5s ease-in forwards;}
@keyframes cd-die{0%{transform:scale(1);filter:brightness(3)}
  100%{transform:scale(.25) rotate(22deg);opacity:0;filter:brightness(.2)}}
.cd-shard{position:absolute;left:50%;top:50%;width:12px;height:12px;border-radius:2px;
  background:#ffd98a;pointer-events:none;animation:cd-shard .55s ease-out forwards;}
@keyframes cd-shard{0%{transform:translate(-50%,-50%) scale(1);opacity:1}
  100%{transform:translate(calc(-50% + var(--sx)),calc(-50% + var(--sy))) scale(.2) rotate(200deg);opacity:0}}

/* Effect cards: what one leaves on a tile, and the moment it lands. */
.cd-tile.cd-swappick{border-color:#7fe2ff;box-shadow:0 0 0 3px rgba(127,226,255,.6),0 0 22px rgba(127,226,255,.5);}
