.cd-chip.cd-win{background:var(--plate-good);color:var(--accent-badge-text);}
.cd-chip.cd-loss{background:var(--plate-bad);color:var(--accent-badge-text);}
.cd-chip.cd-tie{background:var(--plate-neutral);color:var(--accent-badge-text);}
@keyframes cd-chip{0%{transform:translate(-50%,14px) scale(.4);opacity:0}
