  font-size:calc(var(--cd-cardh) * .042);}

.cd-foot{position:absolute;left:0;bottom:0;width:100%;padding:6px 16px;display:flex;
  align-items:center;justify-content:space-between;font-size:0.984rem;opacity:.88;
