  font-size:0.984rem;font-weight:bold;}
.cd-btn:hover{background:rgba(255,228,134,.22);}
.cd-btn.cd-btnsel{border-color:var(--text-primary-hover);box-shadow:0 0 0 2px rgba(255,228,134,.45);}

.cd-oppdeck{font-size:0.96rem;opacity:.7;margin-top:2px;}

.cd-banner{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%) scale(.2);
  padding:18px 46px;border-radius:14px;border:3px solid #ffe486;background:rgba(12,20,14,.92);
  text-align:center;z-index:30;opacity:0;box-shadow:0 0 60px rgba(255,220,120,.4);}
.cd-banner.cd-in{animation:cd-stamp .5s cubic-bezier(.2,1.6,.4,1) forwards;}
@keyframes cd-stamp{0%{transform:translate(-50%,-50%) scale(2.2) rotate(-8deg);opacity:0}
  70%{transform:translate(-50%,-50%) scale(.94) rotate(1deg);opacity:1}
  100%{transform:translate(-50%,-50%) scale(1);opacity:1}}
.cd-banner h1{margin:0 0 6px;font-size:2.31rem;letter-spacing:.06em;}
.cd-banner p{margin:2px 0;font-size:1.14rem;opacity:.92;}

/* The card being held is the duel's right column, so it reads on the shared
   detail scale and in the shared inks (docs/task/ui_fixing.md). It keeps a
   ground because it stands over a live board, but no frame and no glow: the
   gold hairline is the only edge it draws. The panel is narrow, so its stat
   block runs in one column rather than two. */
.cd-detail{position:absolute;right:14px;top:70px;width:304px;padding:10px 12px;border-radius:10px;
  border:1px solid var(--border-primary-hover-translucent-15);
  background:var(--bg-dark-overlay-90);z-index:20;color:var(--text-success-active);}
.cd-detail h3{margin:0 0 4px;font-size:var(--fs-detail-title);line-height:1.2;color:var(--text-detail-heading);}
.cd-detail .ui-detail-sub{margin-bottom:3px;}
.cd-detail .inspect-spec-grid{grid-template-columns:1fr;margin:5px 0;}
.cd-detail .inspect-spec-row{max-width:none;font-size:var(--fs-detail-body);}
.cd-detail .inspect-spec-label{color:var(--text-detail-label);}
.cd-detail .inspect-spec-value{color:var(--text-success-active);}
.cd-detail .cd-prompt{font-size:var(--fs-detail-body);color:var(--text-detail-heading);}
.cd-detail .cd-lore{font-style:normal;font-size:var(--fs-detail-prose);line-height:1.35;
  color:var(--text-success-active);max-width:68ch;max-height:9em;overflow:hidden;}


/* ==========================================================================
   CARD COLLECTION (Cards/CardGameCollection.js)
   --------------------------------------------------------------------------
   The binder and the deck builder. Was injected as
   <style id="cardcollection-style"> on first open.
   ========================================================================== */
#cardcol-container {
  position: fixed; left: 0; top: 0; width: 100%; height: 100%; z-index: 60;
  font-family: var(--font-ui); overflow: hidden; user-select: none;
}
#cardcol-container * { box-sizing: border-box; }

/* Both halves are columns: the grid and the dossier take the room that is
   left, the deck and the buttons keep their own. */
#cardcol-container .cgc-left,
#cardcol-container .cgc-right { display: flex; flex-direction: column; min-height: 0; }

#cardcol-container .cgc-right .inspect-spec-row,
#cardcol-container .cgc-right .ui-empty-note,
#cardcol-container .cgc-right .ui-empty-text { font-size: var(--fs-detail-body); }
#cardcol-container .cgc-right .inspect-spec-label { color: var(--text-detail-label); }
#cardcol-container .cgc-right .inspect-spec-value { color: var(--text-success-active); }
#cardcol-container .cgc-right .ui-prose {
  font-size: var(--fs-detail-prose);
  color: var(--text-success-active);
  max-width: 68ch;
}
#cardcol-container .cgc-right .ui-detail-titles > h2 {
  font-size: var(--fs-detail-title);
  line-height: 1.2;
  margin: 0;
}

#cardcol-container .cgc-count {
  font-size: var(--fs-label);
  color: var(--text-text-alt-4);
  white-space: nowrap;
}

/* ---- the shelf ---- */
.cgc-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));
  gap: var(--sp-4); overflow-y: auto; flex: 1 1 auto; min-height: 0;
  padding-right: var(--sp-2); align-content: start;
}

/* A card cell wears no plate and no frame: the rarity line down its left edge
   is the only mark, exactly as an inventory slot does (ui_fixing rules 1-2).
   The colour comes from the .rarity--* class the cell carries, read through
   currentColor, so it follows the theme and never a literal. */
.cgc-cell {
  position: relative; height: 118px; border-radius: 4px;
  border: 1px solid transparent; border-left: 4px solid currentColor;
  background: transparent; cursor: pointer;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: var(--sp-2); overflow: hidden; padding: var(--sp-2);
}

.cgc-cell:hover,
.cgc-cell.selected { border-color: var(--text-primary-hover); border-left-color: currentColor; }

/* A card already spent on the deck is still readable, only quieter. */
.cgc-cell--spent { opacity: 0.5; }

/* Dealt in, not simply drawn: a filter change riffles the shelf. */
.cgc-grid.cgc-dealing .cgc-cell {
  animation: cgc-in .34s cubic-bezier(.2,1.35,.4,1) backwards;
  animation-delay: calc(var(--d, 0) * 18ms);
}
@keyframes cgc-in {
  0% { transform: translateY(26px) rotate(-7deg) scale(.72); opacity: 0 }
  100% { transform: none; opacity: 1 }
}

.cgc-artcell {
  height: 56px; display: flex; align-items: center; justify-content: center;
  flex: 0 0 auto;
}
.cgc-cell canvas, .cgc-cell img {
  image-rendering: pixelated; max-width: 100%; max-height: 56px; object-fit: contain;
}
.cgc-cell-canvas { width: 48px; height: 48px; }

.cgc-cell .cgc-lbl {
  font-size: var(--fs-caption); text-align: center; line-height: 1.15;
  color: var(--text-success-active);
  max-height: 2.4em; overflow: hidden; width: 100%;
}

.cgc-cell .cgc-qty {
  position: absolute; right: 3px; bottom: 3px;
  font-size: var(--fs-caption); font-weight: bold;
  color: var(--text-primary-hover);
}

.cgc-empty {
  color: var(--text-text-alt-4); font-size: var(--fs-body);
  padding: var(--sp-5); text-align: center;
}

/* ---- the dossier ----
   The right page is the shared detail card: the name and its kind line take
   the detail title and label tokens, the statistics and the deck are the one
   .inspect-spec-grid stat block, and nothing here sets a size or an ink of its
   own (docs/task/ui_fixing.md). */
.cgc-dossier {
  flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column;
  color: var(--text-success-active);
}

/* The card art stands on the page: no frame, no plate. */
.cgc-art {
  height: 170px; display: flex; align-items: center; justify-content: center;
  border: none; margin-bottom: var(--sp-4);
}
.cgc-art img, .cgc-art canvas { max-width: 100%; max-height: 100%; object-fit: contain; }
.cgc-art canvas { image-rendering: pixelated; }

/* ---- the deck being built ---- */
.cgc-deck {
  flex: 0 0 auto; border-top: 1px solid var(--border-primary-hover-translucent-15);
  padding-top: var(--sp-3); color: var(--text-success-active);
}
.cgc-decklist { max-height: 150px; overflow-y: auto; margin: var(--sp-2) 0; }

/* A deck row is a spec row that can be clicked, so it takes the stat block's
   type and inks and marks itself with the one gold hairline. */
.cgc-deckrow {
  padding: 1px var(--sp-2); border-radius: 3px; cursor: pointer;
  border: 1px solid transparent;
}
.cgc-deckrow:hover { border-color: var(--text-primary-hover); }

.cgc-legal--ok  { color: var(--text-success-active); }
.cgc-legal--bad { color: var(--rarity-rare); }

/* ---- the button strip ---- */
/* The shared gold-on-black button, laid out as a wrapping row rather than the
   column .inspect-actions draws, because there are nine of them. */
.cgc-actions {
  flex: 0 0 auto; display: flex; flex-wrap: wrap; gap: var(--sp-3);
  margin-top: var(--sp-3);
}
.cgc-actions .inspect-btn {
  margin-top: 0; padding: 6px 14px;
  font-size: var(--fs-detail-body);
  box-shadow: none;
}

/* ---- booster pack ---- */
#cardpack-container{position:fixed;left:0;top:0;width:100%;height:100%;z-index:70;
  font-family:var(--font-ui);color:#f4e8cf;overflow:hidden;user-select:none;
  background:radial-gradient(ellipse at 50% 45%,rgba(60,40,90,.92),rgba(6,4,14,.97));}
#cardpack-container *{box-sizing:border-box;}
.cp-title{position:absolute;left:0;top:18px;width:100%;text-align:center;font-size:1.495rem;
  letter-spacing:.1em;text-shadow:0 2px 6px #000;}
.cp-hint{position:absolute;left:0;bottom:18px;width:100%;text-align:center;font-size:1.02rem;opacity:.75;}
.cp-pack{position:absolute;left:50%;top:50%;width:180px;height:250px;margin:-125px 0 0 -90px;
  border-radius:14px;border:3px solid #ffd469;cursor:pointer;
  background:linear-gradient(150deg,#5a2b7a,#1d1030 60%,#3a1358);
