    flex-direction: column; gap: 8px; box-sizing: border-box;
}
#arena-ui-container .arena-row {
    display: flex; align-items: center; gap: 12px; padding: 10px 14px;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-subtle-translucent-25); border-radius: 6px;
    cursor: pointer; font-family: var(--font-ui);
    transition: border-color 0.15s ease, background 0.15s ease;
}
#arena-ui-container .arena-row:hover { border-color: var(--text-primary-hover); }
#arena-ui-container .arena-row.selected {
    border-color: var(--text-primary-hover);
    background: var(--bg-tertiary-focus-translucent-45);
}
#arena-ui-container .arena-row-text { flex: 1; min-width: 0; }
#arena-ui-container .arena-row-label {
    font-weight: bold; color: var(--text-text-alt-2); font-size: 1.176rem;
}
#arena-ui-container .arena-row.selected .arena-row-label { color: var(--text-primary-hover); }
#arena-ui-container .arena-row-sub {
    font-size: 0.952rem; color: var(--text-info); white-space: nowrap;
    overflow: hidden; text-overflow: ellipsis;
}
#arena-ui-container .arena-badge {
    font-family: var(--font-ui); font-size: 0.915rem; font-weight: bold;
    color: var(--text-info); white-space: nowrap;
}
#arena-ui-container .arena-icon {
    width: 44px; height: 44px; min-width: 44px; display: flex; align-items: center;
    justify-content: center; font-size: 1.76rem; color: var(--text-primary-hover);
}
#arena-ui-container .arena-thumb {
    width: 44px; height: 44px; min-width: 44px; image-rendering: pixelated;
}
#arena-ui-container .arena-right {
    display: flex; flex-direction: column; gap: 12px; height: 100%; box-sizing: border-box;
}
#arena-ui-container .arena-right.center {
    justify-content: center; align-items: center; text-align: center; padding: 24px; gap: 14px;
}
#arena-ui-container .arena-big-glyph { font-size: 4.4rem; color: var(--text-primary-hover); line-height: 1; }
#arena-ui-container .arena-detail-head { border-bottom: 2px solid var(--border-subtle); padding-bottom: 6px; }
#arena-ui-container .arena-detail-title {
    font-family: var(--font-ui); font-size: var(--fs-detail-title); color: var(--text-detail-heading);
    margin: 0; line-height: 1.2;
}
#arena-ui-container .arena-detail-sub {
    font-size: var(--fs-detail-heading); color: var(--text-detail-label); font-family: var(--font-ui);
    text-transform: uppercase; letter-spacing: 0.5px;
}
#arena-ui-container .arena-info-card {
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-subtle-translucent-25); border-radius: 6px;
    padding: 12px; text-align: left; font-size: var(--fs-detail-body); line-height: 1.5;
    color: var(--text-success-active); box-sizing: border-box; width: 100%;
}
#arena-ui-container .arena-info-card strong { color: var(--text-detail-heading); }
#arena-ui-container .arena-info-card ul { margin: 0; padding-left: 18px; }
#arena-ui-container .arena-member {
    display: flex; align-items: center; gap: 12px; padding: 8px 10px;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-subtle-translucent-25); border-radius: 6px;
}
#arena-ui-container .arena-member-name {
    font-family: var(--font-ui); font-weight: bold; color: var(--text-primary-hover); font-size: 1.15rem;
}
#arena-ui-container .arena-member-meta { font-size: 0.96rem; color: var(--text-text-alt-2); }
#arena-ui-container .arena-action-btn {
    display: flex; justify-content: center; align-items: center; padding: 12px 24px;
    background: var(--text-primary-hover); color: var(--bg-panel);
    border: 1px solid var(--border-subtle); border-radius: 6px; cursor: pointer;
    font-weight: bold; text-transform: uppercase; font-family: var(--font-ui);
    font-size: 1.322rem; box-shadow: 0 3px 6px var(--shadow-black-translucent-25);
    transition: filter 0.15s ease, box-shadow 0.15s ease; box-sizing: border-box;
}
#arena-ui-container .arena-action-btn:hover {
    filter: brightness(1.12); box-shadow: 0 0 10px var(--shadow-gold-amber-50);
}
#arena-ui-container .arena-preview {
    width: 100%; aspect-ratio: 16 / 9; object-fit: cover;
    border: 3px double var(--text-primary-hover); border-radius: 6px;
    box-shadow: 0 4px 12px var(--shadow-black-translucent-25); box-sizing: border-box;
}
#arena-ui-container .arena-preview-missing {
    width: 100%; aspect-ratio: 16 / 9; border: 3px double var(--text-primary-hover);
    border-radius: 6px; background: var(--bg-panel); display: flex; align-items: center;
    justify-content: center; color: var(--text-info); font-family: var(--font-ui); box-sizing: border-box;
}
#arena-ui-container .arena-empty {
    opacity: 0.7; font-style: normal; margin-top: 24px; font-family: var(--font-ui);
    color: var(--text-text-alt-2); text-align: center;
}


/* ==========================================================================
   SKILL ATLAS (CharacterCreation/SkillMaster.js)
   --------------------------------------------------------------------------
   The curriculum as a sky: a three.js canvas holding one school's figure of
   coloured spheres, a layer of names projected over it, and a strip of chrome
   (the school pager, the colour key, the two rules) above. The canvas is built
   once and kept: everything that changes is painted onto the figure in place,
   because a rewritten page would take the canvas with it and a new canvas is a
   new WebGL context.
   ========================================================================== */
#skill-atlas-box.sg3-sky {
    position: relative; overflow: hidden; min-height: 0; box-sizing: border-box;
    border: none;
    background: transparent;
    box-shadow: none;
}
#skill-atlas-canvas {
    position: absolute; left: 0; top: 0; width: 100%; height: 100%;
    display: block; cursor: grab; touch-action: none;
}
/* The names are projected over the canvas and moved every frame, so the layer
   itself must never take the pointer: only the name chip does, and dragging
   anywhere else on the sky turns the figure. */
.sg3-labels {
    position: absolute; left: 0; top: 0; width: 100%; height: 100%;
    pointer-events: none; overflow: hidden;
}
.sg3-label {
    position: absolute; white-space: nowrap;
    left: var(--ms-x, 0); top: var(--ms-y, 0);
    transform: translate(-50%, 0) scale(var(--ms-label-scale, 1));
    font-family: var(--font-ui); user-select: none; will-change: transform;
}
.sg3-label-icon {
    transform: scale(0.55); transform-origin: center; vertical-align: middle;
    margin-right: -6px; margin-left: -6px; opacity: 0.9;
}
.sg3-label-name {
    pointer-events: auto; cursor: pointer; vertical-align: middle;
    font-size: 1.17rem; color: var(--text-pure-white);
    text-shadow: 0 1px 3px var(--shadow-black-translucent-75), 0 0 8px var(--shadow-black-translucent-75);
}
.sg3-label-cost {
    vertical-align: middle; margin-left: 5px;
    font-size: 1.02rem; letter-spacing: 0.3px; color: var(--text-text-alt-3);
    text-shadow: 0 1px 3px var(--shadow-black-translucent-75);
}
.sg3-label.sg3-learned .sg3-label-name { font-weight: bold; color: var(--text-forest-complete); }
.sg3-label.sg3-open .sg3-label-name { color: var(--text-secondary-active); }
.sg3-label.sg3-locked .sg3-label-name { color: var(--text-card-medium); }
.sg3-label.sg3-focus .sg3-label-name {
    font-weight: bold; color: var(--text-pure-white);
    background: var(--bg-black-translucent-96); border-radius: 4px; padding: 1px 6px;
    box-shadow: 0 0 0 1px var(--text-secondary-active);
}
/* The sky is not a page of a book: while it is up, the spread gives up its
   1560x960 plate and takes the whole screen. Scoped to .skill-fullpage, which
   only this scene ever sets. */
#menu-container .book-spread.skill-fullpage {
    width: 100%; height: 100%; max-width: none; max-height: none;
}
/* The school's name, written across the foot of its sky. */
.sg-topbar {
    display: flex; align-items: center; justify-content: center; gap: 10px;
    font-family: var(--font-ui); padding: 2px 0 8px 0; user-select: none;
}
.sg-progress { font-size: 1.145rem; letter-spacing: 1px; color: var(--text-card-medium); }
.sg-title-arrow {
    display: inline-flex; align-items: center; justify-content: center;
    width: 24px; height: 24px; vertical-align: middle; margin: 0 10px;
    color: var(--text-secondary-active); cursor: pointer;
    font-size: 1.8rem; line-height: 1; font-weight: bold; user-select: none;
}
.sg-title-name { vertical-align: middle; }
.sg-zoom {
    display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px;
    color: var(--text-secondary-active);
    cursor: pointer; font-weight: bold; line-height: 1; user-select: none; font-size: 1.4rem;
}
.sm-magic-actions { flex-direction: row; }
.sm-magic-actions > * { flex: 1 1 0; min-width: 0; }
.sg-occult {
    font-size: 1.081rem; letter-spacing: 1px; font-weight: bold; padding: 1px 6px; border-radius: 3px;
    border: 1px solid var(--text-secondary-active); color: var(--text-secondary-active);
}
.sg-occult.sg-forbidden {
    border-color: var(--text-primary-hover); color: var(--text-primary-hover);
}

/* Magical Systems wheel (CharacterCreation/SkillMaster.js): one node per
   <MagicalSystem:> value, laid out on a ring around a decorative pentacle.
   Shares the atlas node shape (.sg-ring's sizing) under its own class so the
   two views never fight over the same CSS. */
.ms-wheel-box { position: relative; flex-shrink: 0; animation:ms-fade-in 0.4s ease-out;
    width: var(--ms-wheel-size, 0); height: var(--ms-wheel-size, 0); }
@keyframes ms-fade-in { from { opacity:0; transform:scale(0.94); } to { opacity:1; transform:scale(1); } }
.ms-rim { transform-origin:50% 50%; animation:ms-rim-spin 140s linear infinite; }
@keyframes ms-rim-spin { from { transform:rotate(0deg); } to { transform:rotate(360deg); } }
.ms-pentacle { animation:ms-pentacle-glow 4s ease-in-out infinite; transform-origin:50% 50%; }
@keyframes ms-pentacle-glow { 0%, 100% { opacity:0.55; } 50% { opacity:0.95; } }
.ms-node {
    position:absolute; left: var(--ms-x, 0); top: var(--ms-y, 0); display:flex; flex-direction:column; align-items:center;
    width:140px; cursor:pointer; font-family:var(--font-ui); user-select:none;
    transition:transform 0.15s ease;
}
.ms-node:hover { transform:scale(1.06); }
.ms-ring {
    width:92px; height:92px; border-radius:50%; box-sizing:border-box;
    border:3px solid var(--border-secondary-hover-translucent-15);
    background:var(--bg-card-translucent-5);
    display:flex; align-items:center; justify-content:center;
}
.ms-pct { font-size:1.31rem; font-weight:bold; text-shadow:0 1px 2px var(--shadow-black-translucent-75); }
.ms-node.ms-selected .ms-ring { animation:ms-select-pulse 1.8s ease-in-out infinite; }
@keyframes ms-select-pulse {
    0%, 100% { box-shadow:0 0 0 3px var(--text-secondary-active), 0 0 10px var(--shadow-primary-hover-translucent-5); }
    50% { box-shadow:0 0 0 4px var(--text-secondary-active), 0 0 22px var(--shadow-primary-hover-translucent-5); }
}
/* The pupil's own class affinity: a steady gold ring so it reads apart from
   the (pulsing) click-selection highlight even when both land on one node. */
.ms-node.ms-actor .ms-ring { box-shadow:0 0 0 3px var(--accent-gold-pure), 0 0 12px var(--accent-gold-pure); }
.ms-node.ms-actor.ms-selected .ms-ring { animation:ms-select-pulse-gold 1.8s ease-in-out infinite; }
@keyframes ms-select-pulse-gold {
    0%, 100% { box-shadow:0 0 0 3px var(--accent-gold-pure), 0 0 10px var(--accent-gold-pure); }
    50% { box-shadow:0 0 0 4px var(--accent-gold-pure), 0 0 24px var(--accent-gold-pure); }
}
.ms-name {
    margin-top:7px; font-size:1.21rem; font-weight:bold; text-align:center;
    text-shadow:0 1px 2px var(--shadow-black-translucent-75);
}


/* ==========================================================================
   SKY VIEWER (GalaxySim/GalaxySimSkyViewer.js)
   --------------------------------------------------------------------------
   The naked-eye sky and its object cards. Was injected as
   <style id="galaxysim-skyviewer-style"> on first open.
   ========================================================================== */
#gsv-root { position:fixed; top:0; right:0; bottom:0; left:0; width:100vw; height:100vh;
  background:#020204; z-index:400; overflow:hidden;
  font-family:'Segoe UI',Arial,sans-serif; color:var(--text-pure-white);
  user-select:none; }
#gsv-root .gsv-svg { position:absolute; top:0; right:0; bottom:0; left:0; width:100%; height:100%;
  display:block; cursor:grab; }
#gsv-root .gsv-svg:active { cursor:grabbing; }
#gsv-root .gsv-bgrect { fill:url(#gsv-bg); }
#gsv-root .gsv-milkyway { fill:url(#gsv-milkyway); mix-blend-mode:screen; pointer-events:none; }
#gsv-root .gsv-field-star { fill:#dfe8ff; opacity:calc(var(--gsv-op,0.5) * 0.35);
  animation:gsv-twinkle linear infinite; pointer-events:none; }
@keyframes gsv-twinkle { 0%,100% { opacity:calc(var(--gsv-op,0.5) * 0.35); } 50% { opacity:var(--gsv-op,0.5); } }
#gsv-root .gsv-grid-ring { fill:none; stroke:rgba(140,170,230,0.16); stroke-width:1; }
#gsv-root .gsv-grid-spoke { stroke:rgba(140,170,230,0.10); stroke-width:1; }
#gsv-root .gsv-grid-spoke-major { stroke:rgba(160,190,255,0.22); }
#gsv-root .gsv-line { stroke:var(--gsv-line-color); stroke-width:var(--gsv-line-thickness); opacity:0.55; fill:none;
  transition:opacity .2s, stroke-width .2s; vector-effect:non-scaling-stroke; }
#gsv-root .gsv-line-zodiac { stroke:var(--gsv-zodiac-color); opacity:0.72;
  filter:drop-shadow(0 0 3px rgba(255,210,90,0.55)); }
#gsv-root .gsv-const.gsv-hover .gsv-line { opacity:1; }
#gsv-root .gsv-const.gsv-hover .gsv-line-zodiac { filter:drop-shadow(0 0 6px rgba(255,224,130,0.95)); }
#gsv-root .gsv-star-core { fill:var(--gsv-star-color); }
#gsv-root .gsv-star-core.gsv-star-zodiac { fill:#fff3c4; }
#gsv-root .gsv-star-halo { fill:url(#gsv-star-halo); }
#gsv-root .gsv-star-halo.gsv-star-zodiac { fill:url(#gsv-star-halo-gold); }
#gsv-root .gsv-const.gsv-hover .gsv-star-core { fill:#ffffff; }
#gsv-root .gsv-star-labels.gsv-hidden { display:none; }
#gsv-root .gsv-const-label text { fill:rgba(220,230,255,0.55); font-size:var(--gsv-const-label-size);
  letter-spacing:0.12em; text-transform:uppercase; text-anchor:middle; font-family:Georgia,'Times New Roman',serif;
  paint-order:stroke; stroke:rgba(2,2,6,0.7); stroke-width:var(--gsv-const-label-stroke); }
#gsv-root .gsv-const-label-zodiac text { fill:rgba(255,224,150,0.8); }
#gsv-root .gsv-zodiac-mark { fill:#ffd257; transform:rotate(45deg); transform-origin:center; }
#gsv-root .gsv-star-label { fill:rgba(255,255,255,0.85); font-size:var(--gsv-star-label-size); text-anchor:middle;
  paint-order:stroke; stroke:rgba(2,2,6,0.75); stroke-width:var(--gsv-star-label-stroke); }
#gsv-root .gsv-vignette-rect { fill:url(#gsv-vignette); pointer-events:none; }
#gsv-root .gsv-scope { position:absolute; top:0; right:0; bottom:0; left:0; z-index:6; pointer-events:none; }
#gsv-root .gsv-scope::before, #gsv-root .gsv-scope::after { content:""; position:absolute;
  left:50%; top:50%; width:min(88vmin,760px); height:min(88vmin,760px); transform:translate(-50%,-50%);
  border-radius:50%; }
#gsv-root .gsv-scope::before { box-shadow:0 0 0 9999px rgba(0,0,0,0.96); border:6px solid #1c1c1c; }
#gsv-root .gsv-scope::after { box-shadow:inset 0 0 46px 14px rgba(0,0,0,0.9), inset 0 0 8px 3px rgba(255,255,255,0.06); }
#gsv-root .gsv-topbar { position:absolute; top:16px; left:16px; display:flex; gap:14px; align-items:flex-end;
  z-index:2; pointer-events:auto; flex-wrap:wrap; max-width:80vw; }
#gsv-root .gsv-tabs { display:flex; gap:2px; pointer-events:auto;
  border-bottom:2px solid var(--border-gold-amber-30); padding-bottom:6px; }
#gsv-root .gsv-tab { pointer-events:auto; cursor:pointer; padding:6px 16px; margin:0; border-radius:4px 4px 0 0;
  background:transparent; border:1px solid transparent;
  color:var(--text-text-alt-12); font-size:17px; letter-spacing:0.4px; font-weight:600;
  transition:all .15s ease; white-space:nowrap; user-select:none; }
#gsv-root .gsv-tab:hover { background:var(--border-gold-amber-30); color:var(--text-pure-white); }
#gsv-root .gsv-tab.gsv-active { color:#1a1206; background:var(--accent-gold-pure);
  box-shadow:0 4px 10px var(--shadow-black-translucent-55); }
#gsv-root .gsv-legend { display:flex; align-items:center; gap:6px; padding-bottom:8px; font-size:15px;
  color:var(--text-text-alt-12); }
#gsv-root .gsv-legend-swatch { width:16px; height:2px; background:var(--gsv-zodiac-color);
  box-shadow:0 0 4px rgba(255,215,90,.7); display:inline-block; }
#gsv-root .gsv-bottombar { position:absolute; left:50%; bottom:20px; transform:translateX(-50%);
  text-align:center; z-index:2; pointer-events:none; max-width:90vw; }
#gsv-root .gsv-hover-name { font-size:24px; font-weight:600; letter-spacing:0.6px;
  color:var(--accent-amber-glow); text-shadow:0 2px 6px var(--shadow-black-translucent-75);
  opacity:0; transition:opacity .18s; }
#gsv-root .gsv-hover-name.gsv-visible { opacity:1; }
/* Aim reticle for pad / keyboard: those pan the sky under a fixed point rather
   than moving a cursor over it, so the point has to be visible. Hidden while
   the mouse is what is aiming (see _updateCrosshair). Sits under the scope
   vignette (z-index 6) so a telescope still frames it. */
#gsv-root .gsv-crosshair { position:absolute; left:50%; top:50%; width:34px; height:34px;
  transform:translate(-50%,-50%); z-index:3; pointer-events:none;
  opacity:0; transition:opacity .18s; }
#gsv-root .gsv-crosshair.gsv-visible { opacity:0.75; }
#gsv-root .gsv-crosshair::before, #gsv-root .gsv-crosshair::after { content:""; position:absolute;
  filter:drop-shadow(0 0 3px rgba(0,0,0,0.9)); }
/* Each arm is one gradient with a transparent band across its middle, so the
   reticle leaves a hole where the star it is naming sits. */
#gsv-root .gsv-crosshair::before { left:50%; top:0; width:1px; height:100%; margin-left:-0.5px;
  background:linear-gradient(to bottom,
    var(--accent-amber-glow) 0 34%, transparent 34% 66%,
    var(--accent-amber-glow) 66% 100%); }
#gsv-root .gsv-crosshair::after { top:50%; left:0; height:1px; width:100%; margin-top:-0.5px;
  background:linear-gradient(to right,
    var(--accent-amber-glow) 0 34%, transparent 34% 66%,
    var(--accent-amber-glow) 66% 100%); }


/* ==========================================================================
   CONTAINER / HARVEST MINI WINDOW (Crafting/ContainerSystemUI.js)
   --------------------------------------------------------------------------
   Shared by Scene_Container and Scene_BodyPartHarvest. Was injected as
   <style id="cs-mini-css"> on first open. Deliberately NOT under
   #menu-container: that id is styled fullscreen by the parchment theme and this
   is a small centred window.
   ========================================================================== */
#cs-mini, #hv-mini {
    position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
    width: 690px; max-width: 94vw; max-height: 80vh;
    display: flex; flex-direction: column;
    background: var(--bg-panel);
    color: var(--text-primary-hover);
    border: 1px solid var(--border-gold-amber);
    border-radius: 13px;
    box-shadow: 0 21px 69px rgba(0,0,0,0.66);
    font-family: "Segoe UI", system-ui, sans-serif;
    z-index: 100; opacity: 0; transition: opacity 0.18s ease-out;
    overflow: hidden;
}
#cs-mini .cs-head, #hv-mini .cs-head { display:flex; align-items:center; justify-content:center;
    padding:17px 23px; border-bottom:1px solid rgba(255,255,255,0.1); }
#cs-mini .cs-title, #hv-mini .cs-title { font-size:29px; font-weight:700; color: var(--text-primary-hover);
    letter-spacing:0.3px; text-shadow:0 1px 2px rgba(0,0,0,0.6); }
#cs-mini .cs-tabs { display:flex; gap:6px; padding:12px 15px 0; }
#cs-mini .cs-tab { flex:1; text-align:center; padding:11px 0; font-size:23px; font-weight:600; cursor:pointer;
    opacity:0.62; border-bottom:3px solid transparent; }
#cs-mini .cs-tab:hover { opacity:0.92; }
#cs-mini .cs-tab.active { opacity:1; border-bottom-color: var(--text-primary-hover); color: var(--text-primary-hover); }
/* The chest wears the pockets' own search and sort strip: the collapsed
   handle sits in the corner of the header, the sort tags on a line of their
   own over the shelf. Both are sized up to the rest of this window, which is
   drawn a good deal larger than a page of the backpack. */
#cs-mini .cs-head .msb { position:absolute; right:23px; top:50%; transform:translateY(-50%); }
#cs-mini .cs-head .msb-field { width:230px; }
#cs-mini .backpack-search-input { font-size:20px; padding:6px 11px; }
#cs-mini .cs-search { padding:10px 15px 0; margin-bottom:0; }
#cs-mini .backpack-sort-tags { gap:6px; }
#cs-mini .sort-tag { font-size:18px; padding:5px 11px; border-radius:6px; }

#cs-mini .cs-list, #hv-mini .cs-list { flex:1; overflow-y:auto; padding:12px; min-height:315px; }
#cs-mini .cs-row, #hv-mini .cs-row { display:flex; align-items:center; gap:17px; padding:12px 17px;
    border-radius:9px; cursor:pointer; }
#cs-mini .cs-row:hover, #hv-mini .cs-row:hover { background:rgba(255,255,255,0.055); }
#cs-mini .cs-row.selected, #hv-mini .cs-row.selected { background:rgba(224,182,74,0.18);
    outline:1px solid rgba(224,182,74,0.55); }
#cs-mini .cs-row.inactive, #hv-mini .cs-row.inactive { opacity:0.45; }
/* The container's weight gauge (js/plugins/Crafting/ContainerSystemUI.js). The
   three pieces were written out inline on every redraw; only the fill's width
   and colour still come from the plugin, because only it knows how full the
   sack is. */
.container-capacity {
    padding: 4px 10px 6px;
}

.container-capacity-row {
    display: flex;
    justify-content: space-between;
    font-size: 15px;
    margin-bottom: 3px;
    color: var(--text-card-medium);
}

.container-capacity-track {
    height: 8px;
    border-radius: 4px;
    background: var(--bg-subtle-translucent-15);
    overflow: hidden;
}

/* The stripe carries the item's .rarity--* class and fills from it through
   currentColor, the same way the backpack's does. The container used to paint
   it from a private third copy of the rarity ladder. */
#cs-mini .cs-rarity-bar { width:7px; align-self:stretch; border-radius:4px; flex:0 0 7px;
    background: currentColor; }
#cs-mini .cs-ic, #hv-mini .cs-ic { width:54px; height:54px; flex:0 0 54px; image-rendering:pixelated; }
#cs-mini .cs-name, #hv-mini .cs-name { flex:1; font-size:25px; white-space:nowrap; overflow:hidden;
    text-overflow:ellipsis; }
#cs-mini .cs-count { font-size:23px; opacity:0.85; font-variant-numeric:tabular-nums; }

/* The container's rows are the backpack's .item-slot now, so the icon sits in
   a wrapper and the name has a meta line under it. This window is drawn at the
   hyperdeck's larger scale, so the shared 32px gutter is widened to hold the
   54px icon and the two lines are given the window's own sizes. */
#cs-mini .cs-row .item-slot-icon { width:54px; height:54px; margin-right:0; flex:0 0 54px; }
#cs-mini .cs-row .item-slot-info { min-width:0; }
#cs-mini .cs-row .item-slot-meta { font-size:23px; opacity:0.85; margin-top:2px; }
#cs-mini .cs-row .item-slot-count { font-size:23px; margin-left:12px; }
#cs-mini .cs-row .item-rarity-bar { position:static; width:7px; height:auto; align-self:stretch;
    border-radius:4px; flex:0 0 7px; }
#hv-mini .cs-status { font-size:23px; font-weight:600; }
#hv-mini .cs-rate { font-size:23px; opacity:0.85; min-width:63px; text-align:right; font-variant-numeric:tabular-nums; }
#cs-mini .cs-empty, #hv-mini .cs-empty { text-align:center; opacity:0.62; font-size:25px;
    padding:72px 15px; font-style: normal; }
#cs-mini .cs-qty-overlay, #hv-mini .cs-qty-overlay { position:absolute; top:0; right:0; bottom:0; left:0; background:rgba(0,0,0,0.58);
    display:flex; align-items:center; justify-content:center; }
#cs-mini .cs-qty-box { background: var(--bg-panel); border:1px solid var(--border-gold-amber);
    border-radius:11px; padding:24px 27px; width:80%; text-align:center; }
#cs-mini .cs-qty-title { font-size:25px; margin-bottom:14px; }
#cs-mini .cs-qty-val { font-size:38px; margin-bottom:8px; }
#cs-mini .cs-qty-hint { font-size:21px; opacity:0.65; margin-bottom:18px; }
#cs-mini .cs-qty-btns { display:flex; gap:14px; }
#cs-mini .cs-qty-btn { flex:0 1 auto; padding:12px 22px; font-size:23px; border-radius:8px; cursor:pointer;
    background:rgba(255,255,255,0.07); }
#cs-mini .cs-qty-btn.selected { background: var(--chip-active-bg); color:var(--chip-active-fg); font-weight:700; }
#hv-mini .cs-actbar { display:flex; gap:12px; padding:14px 17px; border-top:1px solid rgba(255,255,255,0.1);
    flex-wrap:wrap; }
#hv-mini .cs-actbtn { flex:0 1 auto; min-width:144px; text-align:center; padding:12px 15px; font-size:23px;
    font-weight:600; border-radius:8px; cursor:pointer; background:rgba(255,255,255,0.07); }
#hv-mini .cs-actbtn:hover { background:rgba(255,255,255,0.12); }
#hv-mini .cs-actbtn.selected { background: var(--chip-active-bg); color:var(--chip-active-fg); }
#hv-mini .cs-actbtn.danger { color:#e8918a; }
#hv-mini .cs-actbtn.danger.selected { background:#a5352c; color:#fff; }
#hv-mini .cs-actbtn.disabled { opacity:0.4; cursor:default; background:rgba(255,255,255,0.03); }


/* ==========================================================================
   MONSTER TOURNAMENT HUD (Minigames/MonsterTournament.js)
   --------------------------------------------------------------------------
   Drawn over the 3D arena, hence pointer-events:none on the root: the mouse
   stays free to orbit the camera. Was injected as <style id='mt-hud-style'>
   once per session.
   ========================================================================== */
#mt-hud {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: 100;
    pointer-events: none; /* mouse stays free to orbit the 3D camera */
    font-family: var(--font-ui);
    user-select: none;
}
#mt-hud .mt-panel {
    position: absolute;
    background: var(--bg-panel);
    border: 1px solid var(--border-focus-hover);
    border-radius: 8px;
    box-shadow: 0 6px 22px var(--shadow-black-translucent-55);
    color: var(--text-text-alt-2);
    padding: 12px 18px;
}
#mt-hud .mt-panel.mt-active {
    border-color: var(--accent-gold-pure);
    box-shadow: 0 0 16px var(--shadow-gold-amber-50);
}
#mt-title {
    top: 14px; left: 50%; transform: translateX(-50%);
    white-space: nowrap; text-align: center;
    font-size: 22px; font-weight: bold;
    color: var(--text-primary-hover);
    padding: 9px 26px;
}
#mt-announce {
    position: absolute; top: 86px; left: 50%; transform: translateX(-50%);
    font-size: 20px; font-weight: bold; white-space: nowrap;
    color: var(--accent-amber-glow);
    background: var(--bg-dark-overlay-78);
    border: 1px solid var(--border-gold-amber-30);
    padding: 6px 20px; border-radius: 20px;
    opacity: 0; transition: opacity .3s ease;
    text-shadow: 0 1px 4px var(--shadow-black-translucent-75);
}
#mt-stats {
    bottom: 20px; left: 50%; transform: translateX(-50%);
    width: 72%; max-width: 760px;
}
#mt-stats .mt-stats-head {
    display: flex; justify-content: space-between; align-items: baseline;
    margin-bottom: 8px;
}
#mt-stats .mt-name {
    font-size: 24px; font-weight: bold;
    color: var(--text-primary-hover);
}
#mt-stats .mt-sub { font-size: 14px; color: var(--text-info); }
#mt-stats .mt-statgrid {
    display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; margin: 8px 0;
}
#mt-stats .mt-stat { text-align: center; }
#mt-stats .mt-stat .lbl { font-size: 12px; color: var(--text-info); letter-spacing: .5px; }
#mt-stats .mt-stat .val { font-size: 21px; font-weight: bold; color: var(--text-primary-hover); }
#mt-stats .mt-stats-foot {
    display: flex; justify-content: space-between; align-items: center; margin-top: 6px;
}
#mt-stats .mt-power { font-weight: bold; color: var(--text-primary-hover); }
#mt-bet, #mt-addbet {
    top: 50%; left: 50%; transform: translate(-50%, -50%);
    text-align: center; min-width: 300px;
}
#mt-bet .mt-bet-amount { font-size: 26px; margin-bottom: 4px; color: var(--text-text-alt-2); }
#mt-bet .mt-bet-amount b { color: var(--text-primary-hover); }
#mt-bet .mt-bet-avail { font-size: 18px; margin-bottom: 8px; color: var(--text-info); }
#mt-addbet .mt-addbet-title {
    font-size: 20px; font-weight: bold; margin-bottom: 10px;
    color: var(--text-primary-hover);
}
#mt-addbet { pointer-events: auto; }
#mt-addbet .mt-opt {
    padding: 8px 16px; margin: 6px 0; border-radius: 6px;
    border: 1px solid var(--border-subtle);
    color: var(--text-text-alt-2);
    cursor: pointer;
}
#mt-addbet .mt-opt:hover,
#mt-addbet .mt-opt.sel {
    border-color: var(--accent-gold-pure);
    background: var(--bg-tertiary-focus-translucent-45);
    color: var(--text-primary-hover);
}
#mt-banner {
    position: absolute; top: 38%; left: 50%; transform: translate(-50%, -50%);
    font-size: 32px; font-weight: bold; text-align: center;
    padding: 16px 34px; border-radius: 10px;
    background: var(--bg-dark-overlay-78);
    border: 2px solid var(--border-focus-hover);
    box-shadow: 0 8px 28px var(--shadow-black-translucent-75);
    color: var(--text-primary-hover);
}
#mt-banner.mt-win { color: var(--text-forest-complete); border-color: var(--accent-green-3); }
#mt-banner.mt-lose { color: var(--accent-red-3); border-color: var(--accent-red-2); }


/* ==========================================================================
   ASSETS MENU (Economy/AssetsMenu.js)
   --------------------------------------------------------------------------
   The holdings ledger, scoped to #menu-container so it sits inside the shared
   parchment spread. Was injected as <style id='assets-menu-styles'> at plugin
   load.
   ========================================================================== */
/* Every ink in this ledger was a literal out of the parchment preset's own
   palette: the row name was #1a1a1a, the heading #58180D, the caption #6b5242.
   On the near-black page those are 1.1:1, 1.5:1 and 2:1 -- the whole portfolio
   was invisible under the default preset, and only the summary cards read
   because they painted a white plate under themselves. It takes the ladder. */
/* The whole page is on the shared kit: .ui-fact-grid for the totals, .ui-list
   for the holdings, .ui-detail on the right. What is left here is only what is
   particular to a portfolio: the kind stripe, the two money tones and the
   trend graph. No plate stands behind an option and nothing is framed. */

/* Fading the spread in and out is presentation, so it is a class rather than
   three style properties set from the scene. */
#menu-container.assets-fade { opacity: 0; transition: opacity 0.22s ease-out; }
#menu-container.assets-fade.assets-fade-in { opacity: 1; }
#menu-container.assets-fade.assets-fade-out { opacity: 0; pointer-events: none; }

#menu-container .assets-summary { margin-bottom: var(--sp-4); }

/* The two money tones. A value the player reads for is the bright ink; a debt
   or a loss is the cost ink. Neither carries a plate. */
#menu-container .assets-val--gain { color: var(--text-cost-ok); }
#menu-container .assets-val--loss { color: var(--text-cost-bad); }

#menu-container .assets-list { gap: var(--sp-1); padding-right: var(--sp-2); }

#menu-container .assets-cat-header {
  font-family: var(--font-ui);
  font-size: var(--fs-heading);
  font-weight: bold;
  color: var(--text-primary-hover);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: var(--sp-3) 0 var(--sp-1);
  padding-bottom: var(--sp-1);
}

/* A holding: the kind stripe is the only mark it wears. Selection and hover
   are the shared gold hairline that .item-slot already draws. */
#menu-container .assets-row {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  padding: var(--sp-2) var(--sp-4);
  position: relative;
}

#menu-container .assets-row-bar {
  width: 3px;
  align-self: stretch;
  border-radius: 2px;
  background: var(--assets-tint, var(--text-text-alt-4));
}

#menu-container .assets-row-info { flex: 1; min-width: 0; }

#menu-container .assets-row-name {
  font-family: var(--font-ui);
  font-size: var(--fs-body);
  font-weight: bold;
  color: var(--text-success-active);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#menu-container .assets-row-sub {
  font-family: var(--font-ui);
  font-size: var(--fs-label);
  color: var(--text-text-alt-4);
}

#menu-container .assets-row-vals {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

#menu-container .assets-row-val {
  font-family: var(--font-ui);
  font-size: var(--fs-body);
  font-weight: bold;
}

#menu-container .assets-row-bought {
  font-family: var(--font-ui);
  font-size: var(--fs-caption);
  color: var(--text-text-alt-4);
}

/* The trend graph stands on the page, not on a plate inside a frame. */
#menu-container .assets-graph-box {
  padding: 0 0 var(--sp-4) 0;
  margin-bottom: var(--sp-4);
}

#menu-container .assets-graph-title { text-align: center; letter-spacing: 1px; }

#menu-container #assets-graph { width: 100%; height: auto; display: block; }

#menu-container .assets-graph-legend {
  display: flex;
  gap: var(--sp-4);
  justify-content: center;
  margin-top: var(--sp-2);
}

/* The two series name themselves in their own ink, so the graph needs no key
   of dots beside it. */
