#menu-container .assets-legend--oil { color: var(--text-cost-ok); }
#menu-container .assets-legend--soul { color: var(--text-text-alt-19); }

#menu-container .assets-detail { padding-right: var(--sp-2); }

/* Size comes from the shared right-column scale; only the ink and the caps
   are the ledger's own. */
#menu-container .assets-detail-name {
  font-family: var(--font-ui);
  font-size: var(--fs-detail-title);
  font-weight: bold;
  color: var(--text-detail-heading);
  margin: 0;
}

#menu-container .assets-detail-cat {
  font-family: var(--font-ui);
  font-size: var(--fs-detail-heading);
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-detail-label);
}

/* The holdings actions sit side by side in one strip and all wear the standard
   button: gold border, gold text, no colour of their own. */
#menu-container .assets-detail .inspect-actions,
#menu-container .inspect-actions.assets-actions-row,
#menu-container .inspect-actions:has(.assets-action) {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  gap: 8px;
}

#menu-container .assets-action {
  flex: 0 1 auto;
  min-width: 0;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#menu-container .assets-action--sell,
#menu-container .assets-action--pet {
  color: var(--text-primary-hover);
  border-color: var(--text-primary-hover);
}


/* ==========================================================================
