#gx-ship-appearance .gx-arrow:hover { background:var(--bg-tertiary-focus-translucent-45); }
#gx-ship-appearance .gx-btns { display:flex; gap:10px; margin-top:12px; }
#gx-ship-appearance .gx-btn { flex:0 1 auto; text-align:center; cursor:pointer; padding:10px 8px; border-radius:5px;
  border:2px solid var(--border-focus-hover); background:var(--bg-tertiary-focus-translucent-45);
  color:var(--accent-amber-glow); font-weight:bold; text-transform:uppercase; font-size:1.104rem; user-select:none; }
#gx-ship-appearance .gx-btn:hover { background:var(--chip-active-bg); color:var(--chip-active-fg); }
#gx-ship-appearance .gx-btn.sel { background:var(--chip-active-bg); color:var(--chip-active-fg); }
