/* ==========================================================================
   SAVE / LOAD CONFIRM MODAL (Core/SaveSystem.js)
   --------------------------------------------------------------------------
   The in-DOM confirmation window that replaces the native confirm() dialog, so
   it matches the parchment book and never freezes the canvas. Was a
   `const CONFIRM_MODAL_CSS` re-emitted as an inline <style> inside every
   overlay the scene opened.
   ========================================================================== */
.save-modal-overlay {
    position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 1200;
    display: flex; align-items: center; justify-content: center;
    background: var(--shadow-black-translucent-55);
    font-family: var(--font-ui);
    animation: saveModalFade 0.18s ease-out;
}
@keyframes saveModalFade { from { opacity: 0; } to { opacity: 1; } }
.save-modal {
    width: min(460px, 78vw);
    padding: 22px 26px 20px 26px;
    box-sizing: border-box;
    text-align: center;
    animation: saveModalPop 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes saveModalPop { from { transform: scale(0.94); } to { transform: scale(1); } }
.save-modal-title {
    margin: 0 0 12px 0;
    font-size: 1.322rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-primary-hover);
    border-bottom: none;
    padding-bottom: 8px;
}
.save-modal-message {
    font-size: 1.14rem;
    font-style: normal;
    line-height: 1.55;
    color: var(--text-success-active);
    margin-bottom: 22px;
}
.save-modal-buttons { display: flex; gap: 12px; justify-content: center; }
.save-modal-btn { min-width: 110px; }
/* --------------------------------------------------------------------------
   THE ONE MODAL LOOK
   Every confirmation window in the game wears this: the theme's panel ground,
   no frame, one soft drop shadow, and the shared button strip. A modal that
   paints its own border or its own browns reads as a different game, so none
   of them do it any more.
   -------------------------------------------------------------------------- */
.save-modal,
.cc-modal,
.army-dialog,
.quantity-box {
    border: none;
    border-radius: 6px;
    background: var(--bg-panel);
    box-shadow: 0 18px 50px var(--shadow-black-translucent-55);
    color: var(--text-success-active);
    font-family: var(--font-ui);
}

/* One button, whatever the modal calls it. Matches .inspect-btn so a
   confirmation reads as the same furniture as the card that opened it. */
.save-modal-btn,
.army-dialog-btn,
.cc-modal-actions .cc-sidebar-btn {
    font-family: var(--font-ui);
    font-size: 1.048em;
    font-weight: bold;
    text-align: center;
    padding: 8px 20px;
    border-radius: 4px;
    border: 2px solid var(--text-primary-hover);
    background: var(--bg-secondary-hover);
    color: var(--text-primary-hover);
    cursor: pointer;
    user-select: none;
    box-sizing: border-box;
    transition: all 0.2s ease;
}

.save-modal-btn.danger {
    border-color: var(--border-danger-active);
    color: var(--text-text-alt-10);
    background: var(--bg-secondary-hover);
}

.save-modal-btn:hover,
.save-modal-btn.focused,
.save-modal-btn.selected,
.army-dialog-btn:hover,
.army-dialog-btn.focused,
.army-dialog-btn.selected,
.cc-modal-actions .cc-sidebar-btn:hover,
.cc-modal-actions .cc-sidebar-btn.focused,
.cc-modal-actions .cc-sidebar-btn.selected {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    box-shadow: 0 4px 8px var(--shadow-primary-hover-translucent-5);
}


/* ==========================================================================
   FORGOTTEN GRIMOIRE (ItemSystem/ForgottenGrimoire.js)
   --------------------------------------------------------------------------
   The spell-draw page, scoped to #menu-container. Was injected as
   <style id="grimoire-style"> on first open.
   ========================================================================== */
#menu-container .grim-list { display:flex; flex-direction:column; gap:8px; overflow-y:auto; padding-right:6px; flex-grow:1; }
#menu-container .grim-actor, #menu-container .grim-card {
    font-family:var(--font-ui); cursor:pointer; border-radius:5px;
    border:1.5px solid var(--border-primary-hover-translucent-15);
    background:var(--bg-card-translucent-5);
    transition:all .15s ease; color:var(--text-primary-hover);
}
#menu-container .grim-actor { padding:8px 12px; display:flex; justify-content:space-between; align-items:center; }
#menu-container .grim-card  { padding:10px 14px; display:flex; flex-direction:column; gap:4px; }
#menu-container .grim-actor.sel, #menu-container .grim-card.sel {
    border-color:var(--accent-gold-pure);
    background:var(--bg-tertiary-focus-translucent-45);
    box-shadow:0 0 8px var(--border-primary-hover-translucent-15);
}
#menu-container .grim-card.learned { border-color:#2e7d32; background:rgba(46,125,50,0.18); }
#menu-container .grim-card.blocked { opacity:0.45; }
#menu-container .grim-card.blocked.sel { opacity:0.7; }
#menu-container .grim-blocked { font-size:0.798em; text-transform:uppercase; letter-spacing:0.5px; font-style: normal; opacity:0.9; }
/* the span is always in the card so it can be rewritten in place; an
   unblocked card must not pay for it with a blank row + flex gap */
#menu-container .grim-blocked:empty { display:none; }
#menu-container .grim-name { font-weight:bold; font-size:1.019em; display:flex; justify-content:space-between; gap:8px; }
#menu-container .grim-mp   { color:var(--accent-gold-pure); font-weight:bold; }
#menu-container .grim-desc { font-size: var(--fs-detail-prose); color: var(--text-success-active); line-height:1.35; }
/* The base stat a spell is written in (<StatReq:>, window.SkillStatReq):
   the book will not open for a reader short of it. */
