#menu-container .grim-psi .row { display:flex; justify-content:space-between; margin-top:4px; }


/* ==========================================================================
   SHARED SEARCH STRIP (UI/MenuSearchBar.js)
   --------------------------------------------------------------------------
   The one search field + filter-tag row every menu that searches reuses. Was
   injected as <style id='menu-search-bar-styles'> the first time a bar was
   built.
   ========================================================================== */
.msb {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 10px;
    flex-shrink: 0;
}
/* The field's own row: the handle keeps the right edge, the field (when it is
   open at all) fills everything left of it. */
.msb-field-only {
    flex-direction: row;
    align-items: center;
    gap: 6px;
}
.msb-field-only.msb-collapsed { justify-content: flex-end; }
.msb-field {
    position: relative;
    display: flex;
    align-items: center;
    flex: 1 1 auto;
    min-width: 0;
}
.msb-field .backpack-search-input { width: 100%; }

/* A search field never fills a row of its own: MenuSearchBar docks it into the
   page's own .page-header-bar, so it rides the SAME line as the Back button and
   the title, pinned to the right edge and only as wide as it needs to be. */
.page-header-bar > .msb-field-only {
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    width: auto;
    max-width: 45%;
    margin: 0;
    z-index: 20;
}
.page-header-bar > .msb-field-only .msb-field {
    flex: 0 0 auto;
    width: 240px;
    max-width: 100%;
}
/* No filled box under the caret: the field is a ruled line, not a panel. */
.msb-field .backpack-search-input,
.msb-field .backpack-search-input:focus {
    background: transparent;
    border: none;
    border-bottom: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 0;
    padding-left: 2px;
    padding-right: 22px;
}
.msb-field .backpack-search-input:focus {
    border-bottom-color: var(--text-primary-hover);
}
.msb-docked .msb-toggle { background: transparent; }
/* The collapsed handle: the IconSet magnifying glass (247). Never carries
   '.focusable', so the controller's cursor cannot reach it: a search is
   opened with a click. */
.msb-toggle {
    flex: 0 0 auto;
    box-sizing: border-box;
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    color: var(--text-card-medium);
    cursor: pointer;
    user-select: none;
    outline: none;
    transition: border-color 0.15s ease, color 0.15s ease;
}
.msb-toggle:hover,
.msb-toggle.open {
    color: var(--text-primary-hover);
    border-color: var(--text-primary-hover);
}
.msb-glass {
    display: block;
}
.msb-clear {
    position: absolute;
    right: 8px;
    cursor: pointer;
    font-family: var(--font-ui);
    font-size: 0.892em;
    color: var(--text-card-medium);
    padding: 0 4px;
    user-select: none;
}
.msb-clear:hover { color: var(--text-primary-hover); }
.msb-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
}
/* The sort tags read as part of the search: they sit at the right edge of the
   strip, under the search handle, not adrift on the left. */.msb-row .backpack-sort-tags {
 order: 2;
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}
.msb-label {
    font-family: var(--font-ui);
    font-size: 0.878rem;
    font-weight: bold;
    color: var(--text-card-medium);
}
.msb-sep {
    color: var(--text-card-medium);
    font-size: 0.878rem;
}
.msb-num,
.msb-select {
    box-sizing: border-box;
    background: var(--bg-primary-hover-translucent-35);
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    padding: 3px 6px;
    font-family: var(--font-ui);
    font-size: 0.878rem;
    color: var(--text-success-active);
    outline: none;
}
.msb-num { width: 60px; }
.msb-select { max-width: 55%; }
.msb-num:focus,
.msb-select:focus { border-color: var(--text-primary-hover); }
/* The count of what survived the filters, so an empty page reads as
   "nothing matched" rather than "this menu is broken". */
.msb-count {
    font-family: var(--font-ui);
    font-size: 0.878rem;
    color: var(--text-card-medium);
    margin-left: auto;
}


/* ==========================================================================
   MAIN MENU SEARCH PAGE (UI/CustomMainMenuSearch.js)
   --------------------------------------------------------------------------
   The results page and the 3D weapon viewport on its detail card. The field,
   the clear button and every filter control are the shared strip's own (see
   UI/MenuSearchBar.js above). Was injected as <style id='menu-search-styles'>
   at plugin load.
   ========================================================================== */
.menu-search-page {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}
#menu-search-filters {
    flex-shrink: 0;
}
.search-detail {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}
/* The head of an inspect card: identity and numbers in the left column, the
   turning piece as a borderless square on the right. */
.inspect-topline {
    display: flex;
    gap: 6px;
    align-items: flex-start;
    margin-bottom: 12px;
}
.inspect-topline-info {
    flex: 1 1 auto;
    min-width: 0;
    max-width: 58%;
}
.inspect-topline-info .inspect-meta-grid { margin-bottom: 0; }
/* The turning piece is a square: the card reads as an identity column and a
   plate beside it, not as a column and a tall panel. */
.inspect-topline-preview {
    flex: 1 1 auto;
    width: auto;
    min-width: 168px;
    height: 220px;
    aspect-ratio: 1 / 1;
}
/* Stacked because the column beside the square is half the width the grid's
   two columns were written for. */
.inspect-meta-grid--stacked {
    grid-template-columns: 1fr;
}
/* The square in the card carries no frame of its own. *//* The square only frames itself under the cursor, as a hint that it opens. */
.item-3d-viewport--borderless:hover {
    border-color: var(--accent-amber-glow, #d8a657);
}

/* The piece full screen, turned by hand. */
.item-model-fullscreen {
    position: fixed;
    left: 0; top: 0;
    width: 100%;
    height: 100%;
    /* A dark scrim, not the warm one the parchment panes use: the piece is lit
       from the front and a golden wash behind it drowns its own colour. */
    background: var(--shadow-black-translucent-80);
    backdrop-filter: blur(3px);
    z-index: 10000;
    display: flex;
    flex-direction: column;
}
.item-model-fullscreen-stage {
    flex: 1 1 auto;
    min-height: 0;
}
.item-model-fullscreen-stage canvas {
    width: 100%;
    height: 100%;
    display: block;
}
.item-model-fullscreen-bar {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 10px 18px;
    font-family: var(--font-ui);
}
.item-model-fullscreen-name {
    font-size: 1.2em;
    font-weight: bold;
    color: var(--text-primary-hover);
}
.item-model-fullscreen-hint {
    flex: 1 1 auto;
    font-size: var(--fs-chip);
    color: var(--text-text-alt-4);
}

/* The 3D piece on an inspect card: the search page's weapon, and the
   backpack's item on its right page. One rule, because it is one viewport. */
.search-weapon-viewport,
.item-3d-viewport {
    width: 100%;
    height: 280px;
    margin: 8px 0;
    border: 1px solid var(--border-primary-hover-translucent-15);
    border-radius: 4px;
    background: var(--shadow-primary-hover-translucent-5);
    flex-shrink: 0;
}
.search-weapon-viewport canvas,
.item-3d-viewport canvas {
    width: 100%;
    height: 100%;
    display: block;
}
/* Written after the rule above on purpose: same specificity, so the square on
   an inspect card only loses its frame if it has the last word. */
.item-3d-viewport--borderless,
.item-3d-viewport--borderless canvas {
    border: none;
    background: transparent;
}.item-3d-viewport--borderless {
    background: transparent;
    border: 1px solid transparent;
    border-radius: 4px;
    transition: border-color 0.15s ease;
    margin: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
}

/* The creature card's fact grid. Stats and ecology are read in two columns so
   a label sits beside its answer rather than at the far edge of the page, the
   same shape the character sheet and the backpack's card use. Headings stay
   full width, so the sections still read as sections. */
.inspect-spec-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: var(--sp-5);
    align-content: start;
    margin-bottom: var(--sp-3);
}
/* A pair never reads as a pair once it is wider than about 34ch, and a line
   that is a sentence rather than a pair takes the whole block. */
.inspect-spec-grid .inspect-spec-row { margin-bottom: 0; max-width: 34ch; }
.inspect-spec-grid > .inspect-bullet-item,
.inspect-spec-grid > .ui-empty-note,
.inspect-spec-grid > .inspect-spec-row--stacked { grid-column: 1 / -1; max-width: none; }
/* A stacked pair is a list, not a pair, so the measure that keeps a pair
   together must not squeeze it back into a column. */
#menu-container .item-inspect .inspect-spec-row--stacked { max-width: none; }

/* The school line under a skill's name, in the same ink the creature card's
   category line uses. */
.inspect-rarity--school { color: var(--text-gold-dark); }

/* The category / level line under a creature's name. */
.inspect-rarity--category { color: var(--text-gold-dark); }

/* The creature sprite in the inspect frame. */
.inspect-creature-canvas {
    width: 48px;
    height: 48px;
    image-rendering: pixelated;
    display: block;
}

/* The picker's own way out, held off the party rows above it. */
.target-overlay .inspect-btn.target-cancel { margin-top: var(--sp-5); }


/* ==========================================================================
   DAILY TEACHER SHOP (Economy/RandomDailyShop.js)
   --------------------------------------------------------------------------
   A parchment two-page spread sharing #menu-container / .book-spread /
   .left-page with the other book-like menus; only what is particular to the
   lesson list is stated here. Was injected as
   <style id="daily-teach-shop-style"> on first open.
   ========================================================================== */
#menu-container .teach-list { display:flex; flex-direction:column; gap:8px; overflow-y:auto; padding-right:6px; flex-grow:1; }
#menu-container .teach-actor, #menu-container .teach-card {
    font-family:var(--font-ui); cursor:pointer; border-radius:5px;
    border:1.5px solid var(--border-primary-hover-translucent-15);
    background:var(--bg-card-translucent-5);
    transition:all .15s ease; color:var(--text-primary-hover);
}
#menu-container .teach-actor { padding:8px 12px; display:flex; justify-content:space-between; align-items:center; }
#menu-container .teach-card  { padding:10px 14px; display:flex; flex-direction:column; gap:4px; }
#menu-container .teach-actor.sel, #menu-container .teach-card.sel {
    border-color:var(--accent-gold-pure);
    background:var(--bg-tertiary-focus-translucent-45);
    box-shadow:0 0 8px var(--border-primary-hover-translucent-15);
}
#menu-container .teach-card.taught { border-color:#2e7d32; background:rgba(46,125,50,0.18); }
#menu-container .teach-card.locked { opacity:0.45; cursor:not-allowed; }
#menu-container .teach-name { font-weight:bold; font-size:1.019em; display:flex; justify-content:space-between; gap:8px; }
#menu-container .teach-price { color:var(--accent-gold-pure); font-weight:bold; }
#menu-container .teach-meta { font-size:0.798em; text-transform:uppercase; letter-spacing:0.5px; opacity:0.8; }
#menu-container .teach-forbidden { color:#a01818; font-weight:bold; }
#menu-container .teach-desc { font-size:0.87em; opacity:0.85; line-height:1.35; }
#menu-container .teach-empty { text-align:center; padding:40px 20px; font-style: normal; opacity:0.7; font-family:var(--font-ui); color:var(--text-primary-hover); }
#menu-container .teach-info { padding:10px 12px; border-radius:4px; margin-top:auto;
    background:var(--bg-card-translucent-5);
    border:1px solid var(--border-primary-hover-translucent-15);
    font-family:var(--font-ui); font-size:0.87em; color:var(--text-primary-hover); }
#menu-container .teach-info .row { display:flex; justify-content:space-between; margin-top:4px; gap:10px; }


/* ==========================================================================
   HOTBAR TARGET PICKER (ItemSystem/ItemSystemHotbar.js)
   --------------------------------------------------------------------------
   The "who does this go on?" sheet a hotbar slot opens. Was injected as
   <style id='hotbar-target-picker-styles'> with the id spliced in from the
   plugin's PICKER_ID constant; that constant is still the one the markup uses,
   so it and the selectors below must be kept in step.
   ========================================================================== */
#hotbar-target-picker {
  position: fixed;
  /* Long-hand rather than `inset: 0`: the shipped NW.js runtime is older than
     that shorthand, and dropping it left the card hugging the top-left corner
     at content size instead of centring the panel over the map. */
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  z-index: 400;
  display: flex;
  align-items: center;
  justify-content: center;
  /* Deliberately unpainted: the sheet still covers the screen so no click
     reaches the map underneath, but a bandage handed out mid-step is a
     half-second question, and dimming the whole world for it made every use
     from the quick bar read as a scene change. The panel carries its own
     background and shadow, so it stands off the map without one. */
  background: transparent;
  user-select: none;
}
#hotbar-target-picker .htp-panel {
  /* Sized to be read across the room rather than squinted at: this is a modal
     question over the map, not a corner readout. */
  min-width: 520px;
  max-width: 70vw;
  margin: auto;
  padding: 24px 30px;
  background: var(--bg-panel);
  border: 2px solid var(--border-gold-amber);
  border-radius: 6px;
  box-shadow: 0 10px 30px var(--shadow-heavy);
  font-family: var(--font-ui);
}
#hotbar-target-picker .htp-title {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--text-primary-hover);
  border-bottom: none;
  padding-bottom: 10px;
  margin-bottom: 14px;
  text-align: center;
}
#hotbar-target-picker .htp-row {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 14px;
  font-size: 1.2rem;
  border: 1px solid transparent;
  border-radius: 4px;
  cursor: pointer;
  color: var(--text-success-active);
}
#hotbar-target-picker .htp-row:hover,
#hotbar-target-picker .htp-row.selected {
  background: var(--bg-primary-hover-translucent-35);
  border-color: var(--text-primary-hover);
}
#hotbar-target-picker .htp-num {
  flex: 0 0 auto;
  width: 24px;
  text-align: center;
  font-weight: bold;
  color: var(--text-primary-hover);
  opacity: 0.8;
}
#hotbar-target-picker .htp-name {
  flex: 1 1 auto;
  font-weight: bold;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#hotbar-target-picker .htp-vitals {
  flex: 0 0 auto;
  display: flex;
  gap: 18px;
  font-size: 1.05rem;
  font-weight: bold;
}
/* Gold, not the danger red the wound-coloured HP elsewhere uses: the Omega
   Tower preset paints --text-danger-hover black (it is a colour for text sat on
   a red plate), which on this black panel made the vitals unreadable. */
#hotbar-target-picker .htp-hp { color: var(--text-gold-dark); }
#hotbar-target-picker .htp-mp { color: var(--text-info); }


/* ==========================================================================
   SKILLS PAGE (BattleSystem/CategorizedBattleSkills.js)
   --------------------------------------------------------------------------
   The one thing the skills page wears that the backpack does not: a "cast
   outside a fight" flag on a list row, plus the shared search strip laid into
   the backpack's one-line toolbar. Everything else on this page -- header,
   tabs, list cards, loadout strip, inspect card -- is the backpack's own markup
   wearing the backpack's own rules (".inspect-pockets" above), so the two menus
   cannot drift apart. Was rewritten into a <style id="companion-styles"> every
   time the scene was created.
   ========================================================================== */
.skill-field-flag {
    color: var(--text-success-active);
    font-weight: bold;
    letter-spacing: 0.5px;
}

/* The stat floor a row is UNDER (<StatReq:>, window.SkillStatReq). Worn only
   by the skills this character is short on, so the flag is a warning rather
   than a label every row carries. */
.skill-req-flag {
    color: var(--text-danger-dark);
    font-weight: bold;
    letter-spacing: 0.5px;
    margin-left: 6px;
    border: 1px solid var(--text-danger-dark);
    border-radius: 3px;
    padding: 0 4px;
    font-size: 0.85em;
}

/* A skill the character is UNDER the stat floor of cannot be synced at all, so
   its card is drawn spent: the name loses its gold and the icon its colour,
   while the red requirement flag stays legible as the reason. */
.item-slot.skill-stat-locked {
    cursor: not-allowed;
}
.item-slot.skill-stat-locked .item-slot-name {
    color: var(--text-disabled);
}
.item-slot.skill-stat-locked .item-slot-icon {
    filter: grayscale(1);
    opacity: 0.55;
}
.item-slot.skill-stat-locked .skill-req-flag {
    opacity: 1;
}

/* The shared strip (UI/MenuSearchBar.js) laid into the backpack's
   one-line toolbar: field left, sort tags right. */
#menu-container .backpack-search .msb {
    margin-bottom: 0;
    min-width: 0;
}
#menu-container .backpack-search .msb-field-only {
    flex: 1 1 auto;
}
/* Collapsed it is just the handle, so it gives the row back to the sort tags
   and pins itself to the right edge. */
#menu-container .backpack-search .msb-field-only.msb-collapsed {
    flex: 0 0 auto;
    order: 9;
    margin-left: auto;
}
#menu-container .backpack-search .msb-row {
    flex: 0 0 auto;
}


/* ==========================================================================
   CHARACTER CREATION 3D THUMBNAILS (CharacterCreation/CharacterCreation3DModel.js)
   --------------------------------------------------------------------------
   The shimmer a thumbnail wears while its model is still generating. Was
   injected as <style id="cc3d-styles"> the first time the picker was drawn.
   ========================================================================== */
@keyframes cc3dPulse { 0%{opacity:0.35} 50%{opacity:0.7} 100%{opacity:0.35} }
.cc3d-loading { animation: cc3dPulse 1.1s ease-in-out infinite; }


/* ==========================================================================
   Earth adventures (Procedural/ProceduralAdventureSystem.js)
   --------------------------------------------------------------------------
   The square is answered on a stage, not in a window: the biome's own
   battleback fills the screen, the away team and whoever they are talking to
   stand on it at full height, and the card carries nothing but the node's
   prose and its branches, laid over their feet the way a visual novel lays
   its text box. The card is the only thing that scrolls.
   ========================================================================== */
#pas-adventure-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: var(--bg-bg-alt-1-translucent-70);
    display: flex;
    /* The card is read in the MIDDLE of the picture, with the cast standing
       tall to either side of it: a page of prose over a lit background is kept
       readable by the shading behind the card, not by pushing it off centre. */
    align-items: center;
    justify-content: center;
    z-index: 1000;
    box-sizing: border-box;
    animation: fadeIn 0.2s ease;
}

/* The stage layer the busts stand on: built by the plugin, sized there, and
   never in the way of a click. */
.pas-adv-scene {
    pointer-events: none;
}

.pas-adv-panel {
    position: relative;
    z-index: 2;
    background: var(--bg-secondary-hover);
    border: 3px double var(--text-primary-hover);
    border-radius: 6px;
    box-shadow: 0 10px 30px var(--shadow-primary-hover-translucent-5),
        inset 0 0 40px var(--shadow-shadow-alt-2-hover-translucent-8);
    padding: 24px 40px 22px;
    width: 1060px;
    max-width: 88vw;
    /* Centred in the picture, so it may take the height it needs. */
    max-height: 76vh;
    margin-top: 0;
    display: flex;
    flex-direction: column;
    font-family: var(--font-ui);
    box-sizing: border-box;
}

/* Held back until the node has finished writing itself out: the rows, the
   payout and the key hint all arrive at the full stop. */
.pas-adv-veiled {
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.25s ease;
}

.pas-adv-title {
    margin-bottom: 10px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border-primary-hover-translucent-15);
    color: var(--text-primary-hover);
    font-size: 1.85em;
    letter-spacing: 0.02em;
    text-align: center;
}

/* The prose is the only thing that scrolls: the rows stay put under it, so a
   long node never pushes the answer off the bottom of the card. */
.pas-adv-text {
    flex: 1 1 auto;
    overflow-y: auto;
    color: var(--text-text-alt-7);
    font-size: 1.42em;
    line-height: 1.6;
    text-shadow: 0 1px 2px var(--shadow-shadow-alt-2-hover-translucent-8);
}

.pas-adv-text p {
    margin: 0 0 14px 0;
    /* Long enough to read, short enough to find the next line on. */
    max-width: 68ch;
}

/* What the ending paid, in the backpack's own hand: one .item-slot row per
   line, its IconSet cell on the left and its count on the right. */
.pas-adv-rewards {
    margin-top: 8px;
    padding-top: 10px;
    border-top: 1px solid var(--border-primary-hover-translucent-15);
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 26vh;
    overflow-y: auto;
    flex-shrink: 0;
}

.pas-adv-rewards .pas-adv-reward {
    cursor: default;
    padding: 4px 10px;
}

.pas-adv-rewards .pas-adv-reward:hover {
    background: transparent;
    border-color: var(--border-primary-hover-translucent-15);
    box-shadow: none;
}

.pas-adv-rewards .item-slot-icon {
    width: 24px;
    height: 24px;
    margin-right: 10px;
}

.pas-adv-rewards .item-slot-name {
    font-size: 1.05em;
    white-space: normal;
    color: var(--text-primary-hover);
}

/* The answers wear the backpack's own button (.inspect-btn), centred on the
   card rather than stretched across it. */
.pas-adv-rows {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    margin-top: 14px;
}

.pas-adv-row {
    font-family: var(--font-ui);
    font-size: 1.048em;
    font-weight: bold;
    text-align: center;
    background: var(--bg-secondary-hover);
    border: 2px solid var(--text-primary-hover);
    color: var(--text-primary-hover);
    padding: 8px 20px;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s ease;
    box-shadow: 0 3px 6px var(--shadow-primary-hover-translucent-5);
    box-sizing: border-box;
    user-select: none;
    min-width: 55%;
    max-width: 100%;
}

.pas-adv-row-sel,
.pas-adv-row:hover {
    background: var(--chip-active-bg);
    color: var(--chip-active-fg);
    box-shadow: 0 4px 8px var(--shadow-primary-hover-translucent-5);
}

/* Fog-of-war preview on the initial settings board. The 9x9 of cells had no
   grid to sit in and no cell rules at all, so it drew as eighty-one stacked
   empty divs with a stray "@" in the middle instead of a map. */
.cc-fog-grid {
    display: grid;
    grid-template-columns: repeat(9, 22px);
    grid-template-rows: repeat(9, 22px);
    gap: 2px;
    justify-content: center;
    align-content: center;
    margin: 8px auto;
    padding: 8px;
    background: rgba(0, 0, 0, 0.55);
    border: 1px solid rgba(218, 165, 32, 0.3);
    border-radius: 6px;
    width: max-content;
}

.cc-fog-cell {
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: monospace;
    font-size: 0.95rem;
    font-weight: bold;
    border-radius: 2px;
    background: rgba(0, 0, 0, 0.9);
    transition: background 0.2s ease;
}

.cc-fog-cell.cc-fog-visible {
    background: rgba(218, 165, 32, 0.42);
}

.cc-fog-cell.cc-fog-seen {
    background: rgba(218, 165, 32, 0.16);
}

.cc-fog-cell.cc-fog-dark {
    background: var(--shadow-black-translucent-95);
}

.cc-fog-cell.cc-fog-player {
    background: rgba(255, 215, 0, 0.85);
    color: #1a1408;
    box-shadow: 0 0 8px rgba(255, 215, 0, 0.6);
}

/* Starting-loadout rows: the icon holds its width, the count reads as a count. */
.cc-loadout-icon {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
}

.cc-loadout-qty {
    font-family: monospace;
    font-weight: bold;
    color: var(--text-muted-hover);
}

/* ==========================================================================
   The Hypernet Chronicle (js/plugins/Quest/NewsSystem.js)

   The newspaper renders the same markup in both shells: fullscreen off the
   main menu, and inside a Hypernet OS window. This block is the parchment
   look; hypernet.css restyles the same classes to XP chrome under
   #news-history-content. Nothing here is set inline by the plugin, so the
   two themes (and any future preset) reach all of it.
   ========================================================================== */

.news-root {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    color: var(--text-success-active);
}

.news-root--fullscreen {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 1000;
    justify-content: center;
    align-items: center;
    background: radial-gradient(circle, var(--bg-dark-warm-translucent-96) 0%, var(--bg-black-translucent-96) 100%);
}

.news-spread {
    flex-direction: column;
}

/* Masthead. Hidden inside the OS window, which has its own titlebar. */
.newspaper-header {
    padding: 24px 48px 12px 48px;
    border-bottom: 6px double var(--border-subtle);
    display: flex;
    flex-direction: column;
    align-items: center;
    background: var(--bg-panel);
    position: relative;
    box-sizing: border-box;
    width: 100%;
}

.news-masthead-title {
    font-family: var(--font-ui);
    font-size: 3.52rem;
    font-weight: bold;
    color: var(--text-primary-hover);
    text-align: center;
    letter-spacing: 3px;
    margin-bottom: 4px;
}

.news-masthead-rule {
    font-family: var(--font-ui);
    font-size: 1.322rem;
    font-weight: bold;
    color: var(--text-card-medium);
    width: 100%;
    border-top: 2px solid var(--border-subtle);
    border-bottom: 2px solid var(--border-subtle);
    padding: 6px 0;
    margin-top: 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-sizing: border-box;
}

.news-masthead-strap {
    letter-spacing: 1px;
}

.news-body {
    display: flex;
    flex: 1;
    overflow: hidden;
    position: relative;
    width: 100%;
    box-sizing: border-box;
}

.news-page {
    padding: 24px 32px;
    display: flex;
    width: 50%;
    box-sizing: border-box;
}

.news-body .cc-page-left {
    border-right: 1px solid var(--border-subtle-translucent-25);
}

.news-subheader {
    text-align: center;
    font-family: var(--font-ui);
    font-size: 1.552rem;
    letter-spacing: 1px;
    margin-bottom: 16px;
}

/* Month navigator */
.news-month-nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
    font-family: var(--font-ui);
    font-size: 1.208rem;
    background: var(--bg-subtle-translucent-5);
    padding: 8px 12px;
    border-radius: 4px;
    border: 1px solid var(--border-primary-hover-translucent-15);
    width: 100%;
    box-sizing: border-box;
    user-select: none;
}

.news-month-label {
    font-weight: bold;
    color: var(--text-primary-hover);
    letter-spacing: 1px;
}

.newspaper-nav-btn {
    cursor: pointer;
    color: var(--text-primary-hover);
    font-weight: bold;
    user-select: none;
}

/* Headline list */
.news-headline-list {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding-right: 8px;
}

/* Every category is a colour role, not a hex: the modifier sets --news-cat
   and the label and the selected rule both read it. */
.news-cat--global   { --news-cat: var(--border-danger-active); }
.news-cat--bearish  { --news-cat: var(--border-danger-active); }
.news-cat--bullish  { --news-cat: var(--text-forest-green); }
.news-cat--surreal  { --news-cat: var(--text-text-alt-19); }
.news-cat--chronicle { --news-cat: var(--text-card-medium); }

.newspaper-headline-item {
 --news-cat: var(--text-card-medium);
    cursor: pointer;
    padding: 12px 16px;
    border-bottom: none;
    border-left: 3px solid transparent;
    background: transparent;
    transition: all 0.2s ease;
    box-sizing: border-box;
}

.newspaper-headline-item:hover {
    background: var(--bg-focus-hover-translucent-10);
}

.newspaper-headline-item.selected {
    background: var(--border-primary-hover-translucent-15);
    border-left-color: var(--news-cat);
}

.news-headline-meta {
    display: flex;
    justify-content: space-between;
    margin-bottom: 4px;
    font-family: var(--font-ui);
    font-size: 0.842em;
    font-weight: bold;
    color: var(--text-text-alt-4);
}

.news-headline-cat {
    color: var(--news-cat);
    letter-spacing: 0.5px;
}

.news-headline-text {
    font-family: var(--font-ui);
    font-size: 1.08rem;
    line-height: 1.3;
    color: var(--text-success-active);
}

.newspaper-headline-item.selected .news-headline-text {
