    overflow-y: auto;
    overflow-x: hidden;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--sp-4, 12px) var(--sp-6, 24px);
    align-content: start;
    scrollbar-width: thin;
    scrollbar-color: var(--text-primary-hover) var(--shadow-primary-hover-translucent-5);
}

