    gap: 10px;
    flex-wrap: wrap;
}

.vehicles-indoors-note {
    margin-bottom: 12px;
    font-family: var(--font-ui);
}

/* The travel codex header: location, coordinates and sector on one line, with
   no panel behind them. */
.travel-codex {
    font-family: var(--font-ui);
    color: var(--text-text-alt-7);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    height: 100%;
}

.travel-codex-line {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 4px 18px;
    margin-bottom: 12px;
    font-size: var(--fs-body);
}

/* The muted half of a codex pair. A label, not a heading. */
.codex-label {
    font-weight: bold;
    color: var(--text-text-alt-4);
}

/* The world-map segment the party stands on. It is a picture, not an option:
   no frame, no drop shadow, just the page it is drawn on. */
.codex-map {
    position: relative;
    width: 100%;
    border: none;
    border-radius: 4px;
    overflow: hidden;
    background: transparent;
    display: flex;
    justify-content: center;
    align-items: center;
    aspect-ratio: 4 / 3;
    margin-top: auto;
    margin-bottom: auto;
}

.codex-map-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

/* Where the party stands on that segment. The plugin hands the position over
   as --pin-x / --pin-y; it paints nothing itself. */
.codex-map-pin {
    position: absolute;
    left: var(--pin-x, 50%);
    top: var(--pin-y, 50%);
    width: 12px;
    height: 12px;
    background: var(--bg-overlay-hover);
    border: 2px solid var(--border-white-strong);
    border-radius: 50%;
    transform: translate(-50%, -50%);
    animation: dndPulse 1.8s infinite ease-in-out;
}

/* The pin's beat. It used to be built as a <style> block at runtime by
   CustomMainMenuLayout.js; the save map's pin reads it too. */
@keyframes dndPulse {
    0%   { transform: translate(-50%, -50%) scale(1); }
    70%  { transform: translate(-50%, -50%) scale(1.2); }
    100% { transform: translate(-50%, -50%) scale(1); }
}

